INSERT INTO `wp_options` VALUES (227,'elementor_remote_info_feed_data','a:3:{i:0;a:5:{s:5:\"title\";s:71:\"6 Best WordPress Image Optimization Plugins of 2024 (+Real Image Tests)\";s:7:\"excerpt\";s:116:\"Explore the top 6 WordPress image optimization plugins of 2024 for faster site speed and better SEO with real tests.\";s:7:\"created\";i:1712656602;s:5:\"badge\";s:3:\"NEW\";s:3:\"url\";s:134:\"https://blog-0c81.site.strattic.io/image-optimization-plugins/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed\";}i:1;a:5:{s:5:\"title\";s:84:\"Introducing Elementor 3.20: New Display Condition Features, Performance Improvements\";s:7:\"excerpt\";s:190:\"Version 3.20 introduces exciting new features that enhance the flexibility of Display Conditions. This version also improves the loading time of your site’s frontend and backend, and more!\";s:7:\"created\";i:1710845895;s:5:\"badge\";s:3:\"NEW\";s:3:\"url\";s:175:\"https://blog-0c81.site.strattic.io/elementor-320-display-conditions-enhacments-peformance-improvements/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed\";}i:2;a:5:{s:5:\"title\";s:97:\"Introducing Elementor 3.19: Display Conditions, Role Permissions in the Element Manager, and More\";s:7:\"excerpt\";s:230:\"Create dynamic visitor experiences, customize your teammates’ widget panels, protect forms from spam submissions, generate variations in the template library, and use URLs from the open web as a reference to generate containers.\";s:7:\"created\";i:1707315304;s:5:\"badge\";s:3:\"NEW\";s:3:\"url\";s:152:\"https://elementor.com/blog/elementor-319-display-conditions-akismet-integration/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed\";}}','no');
INSERT INTO `wp_options` VALUES (230,'_elementor_notifications_data','a:2:{s:7:\"timeout\";i:1713147460;s:5:\"value\";s:8282:\"[{\"id\":\"display-conditions-dynamic-content-3.20\",\"title\":\"Display Conditions for Dynamic Content\",\"description\":\"Transform your single post and page templates into dynamic designs that fit their content by setting display conditions based on Dynamic Tags including native WordPress Custom Fields.\",\"topic\":\"New in Elementor Pro 3.20\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/dynamic-content-pro-3.20.png\",\"chipPlan\":\"Pro\",\"chipTags\":[\"New Feature\"],\"link\":\"https:\\/\\/elementor.com\\/blog\\/elementor-320-display-conditions-enhacments-peformance-improvements\\/\",\"readMoreText\":\"Learn More\",\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"display-conditions-or-logic-3.20\",\"title\":\"Connect Display Conditions - OR Logic\",\"description\":\"Create condition groups of one or more conditions and connect them with the OR logic to display an element when either groups conditions are met.\",\"topic\":\"New in Elementor Pro 3.20\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/display-conditions-3.20.png\",\"chipPlan\":\"Pro\",\"chipTags\":[\"New Feature\"],\"link\":\"https:\\/\\/elementor.com\\/blog\\/elementor-320-display-conditions-enhacments-peformance-improvements\\/\",\"readMoreText\":\"Learn More\",\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"display-conditions-dynamic-content-3.20\",\"title\":\"Display Content on Your Terms: Decide When, Where, and by Who the Content is Viewed\",\"description\":\"Tailor the content on your page to visitors based on various rules to create a powerful experience.\",\"topic\":\"New in Elementor Pro 3.20\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/display-conditions-3.20.png\",\"chipPlan\":\"Pro\",\"chipTags\":[\"New Feature\"],\"link\":\"https:\\/\\/elementor.com\\/blog\\/elementor-320-display-conditions-enhacments-peformance-improvements\\/\",\"readMoreText\":\"Learn More\",\"cta\":\"Upgrade\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-dispaly-conditions\\/\"},{\"id\":\"display-conditions-or-logic-3.20\",\"title\":\"Discover the Professional Way to Create Dynamic Content Websites\",\"description\":\"All the tools you need to turn the content you store on WordPress into pixel perfect websites that maintain a consistent, professional design.\",\"topic\":\"Dynamic Content\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/dynamic-content-3.20.gif\",\"chipPlan\":\"Pro\",\"chipTags\":[\"New Feature\"],\"link\":\"https:\\/\\/youtu.be\\/QSpCwj5dl5g?si=OpSNnnIyqCSOPzTF\",\"readMoreText\":\"Learn More\",\"cta\":\"Upgrade\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-dynamic-content\\/\"},{\"id\":\"5-star-rating-prompt\",\"title\":\"Love the New Features? Let Us Know with 5 Stars!\",\"description\":\"Help spread the word by telling the world what you love about Elementor.\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/5-star-rating-prompt.png\",\"cta\":\"Leave a Review\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/wp-dash-notification-five-stars\\/\"},{\"id\":\"element-manager-permissions-3.19\",\"title\":\"Streamline Collaboration by Setting Permissions to Widgets in the Element Manager\",\"description\":\"Customize the widgets displayed in the Widget Panel for each user based on their assigned roles.\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/element-manager-role-permissions-3.19.png\",\"chipPlan\":\"Pro\",\"chipTags\":[\"New Feature\"],\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"element-manager-permissions-3.19\",\"title\":\"Streaml