INSERT INTO `wp_options` VALUES (633,'_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9','a:4:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:61:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:11:\"\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"HeroPress: WCEU, Overcoming Limits, A Visit To Torino\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://heropress.com/?p=6676\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:147:\"https://heropress.com/wceu-overcoming-limits-a-visit-to-torino/#utm_source=rss&utm_medium=rss&utm_campaign=wceu-overcoming-limits-a-visit-to-torino\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:12370:\"<img width=\"768\" height=\"1024\" src=\"https://heropress.com/wp-content/uploads/2024/04/861643910234c0390.14265675-rotated-1-768x1024.jpg\" class=\"attachment-large size-large wp-post-image\" alt=\"Bicycles in Piazza San Carlo - Turin\" /><div class=\"wp-block-kadence-spacer aligncenter kt-block-spacer-6676_e6503c-43\"><div class=\"kt-block-spacer kt-block-spacer-halign-center\"><hr class=\"kt-divider\" /></div></div>\n\n\n<div class=\"kb-row-layout-wrap kb-row-layout-id6676_7d9033-94 alignnone kt-row-has-bg wp-block-kadence-rowlayout\"><div class=\"kt-row-column-wrap kt-has-1-columns kt-row-layout-equal kt-tab-layout-inherit kt-mobile-layout-row kt-row-valign-top kb-theme-content-width\">\n\n<div class=\"wp-block-kadence-column kadence-column6676_75aa20-5c inner-column-1\"><div class=\"kt-inside-inner-col\">\n<h2 class=\"kt-adv-heading6676_8ef415-a0 wp-block-kadence-advancedheading\">WordCamp Europe 2024 In Torino Italy!</h2>\n\n\n\n<div class=\"wp-block-kadence-image kb-image6676_750fd9-20\"><a href=\"https://europe.wordcamp.org/2024/schedule/\" class=\"kb-advanced-image-link\"><img width=\"1024\" height=\"296\" src=\"https://heropress.com/wp-content/uploads/2025/04/wceu_updates-1024x296.jpg\" alt=\"WCEU Latest Updates\" class=\"kb-img wp-image-6680\" /></a></div>\n\n\n\n<p>This week the WCEU crew announced the <a href=\"https://europe.wordcamp.org/2024/schedule/\">schedule</a> for the event. Someone recently mentioned to me that we seem to have moved forward quite a bit regarding diversity, and I agree. </p>\n\n\n\n<p>Contributor day <a href=\"https://europe.wordcamp.org/2024/contributor-day/\">registration</a> is also open. If you&#8217;ve never been to a contributor day at a big WordCamp I highly recommend it.  It&#8217;s quite different from a small camp.</p>\n\n\n\n<p>Lastly, <a href=\"https://b09g9.r.sp1-brevo.net/mk/cl/f/sh/SMK1E8tHeG7uhthZ8hSlW9L0vytS/HPvqHlk-yGv5\">Visa invitation letters are now available</a>, so if you need that to get to Italy I recommend starting that process as quickly as possible.</p>\n</div></div>\n\n</div></div>\n\n\n<div class=\"wp-block-kadence-spacer aligncenter kt-block-spacer-6676_653e6c-d2\"><div class=\"kt-block-spacer kt-block-spacer-halign-center\"><hr class=\"kt-divider\" /></div></div>\n\n\n<div class=\"kb-row-layout-wrap kb-row-layout-id6676_b27eb7-3e alignnone kt-row-has-bg wp-block-kadence-rowlayout\"><div class=\"kt-row-column-wrap kt-has-1-columns kt-row-layout-equal kt-tab-layout-inherit kt-mobile-layout-row kt-row-valign-top kb-theme-content-width\">\n\n<div class=\"wp-block-kadence-column kadence-column6676_569127-df inner-column-1\"><div class=\"kt-inside-inner-col\">\n<h2 class=\"kt-adv-heading6676_b7b26d-d0 wp-block-kadence-advancedheading\"><a href=\"https://heropress.com/\">HeroPress.com</a> &#8211; <a href=\"https://heropress.com/essays/words-to-wordpress-the-uncharted-path-of-syed-laden/\"></a><a href=\"https://heropress.com/essays/the-time-i-left-my-island-quella-volta-che-sono-uscito-dalla-mia-isola/\">The Time I Left My Island – Quella volta che sono uscito dalla mia isola</a></h2>\n\n\n\n\n<div class=\"wp-block-image is-style-default\">\n<a href=\"https://heropress.com/essays/the-time-i-left-my-island-quella-volta-che-sono-uscito-dalla-mia-isola/\"><img width=\"300\" height=\"300\" src=\"https://heropress.com/wp-content/uploads/2024/03/matteo-min-300x300.jpg\" alt=\"Matteo Enna\" class=\"wp-image-6652\" /></a></div>\n\n\n<p>Matteo Enna was born and raised on an island, Sardinia in the Mediterranean. The sea protected him from people, the world, and everything.</p>\n\n\n\n<p><em>My story begins here, with a strong introversion orchestrating my life, a passion for computer science, PHP which had been accompanying me for about 5 years, and some small attempts to overcome my shyness.</em></p>\n\n\n\n<p>Mattero&#8217;s&#8217;s essay is <a href=\"https://heropress.com/essays/the-time-i-left-my-island-quella-volta-che-sono-uscito-dalla-mia-isola/\">available</a> on <a href=\"https://heropress.com\">HeroPress.com</a>.</p>\n</div></div>\n\n</div></div>\n\n\n<div class=\"wp-block-kadence-spacer aligncenter kt-block-spacer-6676_d45f15-09\"><div class=\"kt-block-spacer kt-block-spacer-halign-center\"><hr class=\"kt-divider\" /></div></div>\n\n\n<div class=\"kb-row-layout-wrap kb-row-layout-id6676_e64ecb-bf alignnone kt-row-has-bg wp-block-kadence-rowlayout\"><div class=\"kt-row-column-wrap kt-has-1-columns kt-row-layout-equal kt-tab-layout-inherit kt-mobile-layout-row kt-row-valign-top kb-theme-content-width\">\n\n<div class=\"wp-block-kadence-column kadence-column6676_cd0912-23 inner-column-1\"><div class=\"kt-inside-inner-col\">\n<h2 class=\"kt-adv-heading6676_0a1329-f0 wp-block-kadence-advancedheading\"><a href=\"https://wppodcasts.com\">WP Podcasts</a></h2>\n\n\n\n\n\n<a href=\"https://wppodcasts.com\"><img src=\"https://heropressnetwork.com/wp-content/uploads/2024/01/pocket_casts_single_315.png\" alt=\"Pocket Casts image\" class=\"wp-image-4316\" /></a>\n\n\n\n<p>There were <em>thirty-six</em> WordPress podcast episodes released this week! Also, <a href=\"https://underrepresented-in-tech-1.castos.com/episodes/new-cohost-and-partner#new_tab\">Underrepresented in Tech has a new cohost</a>! I&#8217;ve known Samah Nasr for a couple years now, and she&#8217;s a fantastic pick!</p>\n\n\n\n<p>FURTHERMORE, The WordPress Podcast has added a <em>fifth</em> translation to their arsenal!  Check out the <a href=\"https://wppodcasts.com/podcast/wordpress-podcast-deutsch/\">Deutch</a> version!</p>\n\n\n\n<ul>\n<li><a href=\"https://dothewoo.io/introducing-groundbreaker-empowering-women-in-tech-in-uganda/#new_tab\">Introducing Groundbreaker, Empowering Women in Tech in Uganda</a> from <a href=\"https://wppodcasts.com/podcast/do-the-woo-a-woocommerce-podcast/\">Do the Woo &#8211; A WooCommerce Podcast</a></li>\n\n\n\n<li><a href=\"https://share.transistor.fm/s/ad6e19da#new_tab\">Looking ahead to WordPress 6.6</a> from <a href=\"https://wppodcasts.com/podcast/the-wp-minute/\">The WP Minute</a></li>\n\n\n\n<li><a href=\"https://unbilleteachattanooga.com/episodio-257-de-pintxos-por-wordcamp-bilbao-con-fran-madrillano/#new_tab\">Episodio 257: De pintxos por WordCamp Bilbao, con Fran Madrillano</a> from <a href=\"https://wppodcasts.com/podcast/un-billete-a-chattanooga/\">Un billete a Chattanooga</a></li>\n\n\n\n<li><a href=\"https://wpcoffeetalk.castos.com/episodes/wpcoffeetalk-hazel-quimpo#new_tab\">WPCoffeeTalk: Hazel Quimpo</a> from <a href=\"https://wppodcasts.com/podcast/wpcoffeetalk/\">WPCoffeeTalk</a></li>\n</ul>\n\n\n\n<p>There are new episodes every single day, so be sure to stop by <a href=\"https://wppodcasts.com\">WPPodcasts.com</a> and search for things that interest you!</p>\n</div></div>\n\n</div></div>\n\n\n<div class=\"wp-block-kadence-spacer aligncenter kt-block-spacer-6676_e51ca4-06\"><div class=\"kt-block-spacer kt-block-spacer-halign-center\"><hr class=\"kt-divider\" /></div></div>\n\n\n<div class=\"kb-row-layout-wrap kb-row-layout-id6676_05f4fd-e9 alignnone kt-row-has-bg wp-block-kadence-rowlayout\"><div class=\"kt-row-column-wrap kt-has-1-columns kt-row-layout-equal kt-tab-layout-inherit kt-mobile-layout-row kt-row-valign-top kb-theme-content-width\">\n\n<div class=\"wp-block-kadence-column kadence-column6676_6cbf4d-13 inner-column-1\"><div class=\"kt-inside-inner-col\">\n<h2 id=\"wpphotos\" class=\"kt-adv-heading6676_f6d5b2-4b wp-block-kadence-advancedheading\"><a href=\"https://wordpress.org/photos\">WP Photos</a></h2>\n\n\n\n<p>Here are some of the great photos submitted to the <a href=\"https://wordpress.org/photos\">WPPhotos</a> project this week!</p>\n\n\n\n\n<a href=\"https://heropress.com/wp-content/uploads/2024/04/88166195b49103be7.73317852-scaled.jpg\"><img width=\"1024\" height=\"683\" src=\"https://heropress.com/wp-content/uploads/2024/04/88166195b49103be7.73317852-1024x683.jpg\" alt=\"Scottish highland cow walking in the heath\" class=\"wp-image-6688\" /></a><a href=\"https://creativecommons.org/share-your-work/public-domain/cc0/\">CC0</a> licensed <a href=\"https://wordpress.org/photos/photo/88166195b4/\">photo</a> by <a href=\"https://wordpress.org/photos/author/ramonvanraaij/\">Rámon van Raaij</a> from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>.\n\n\n\n<a href=\"https://heropress.com/wp-content/uploads/2024/04/346661b9e0cb19533.76383018-scaled.jpg\"><img width=\"1024\" height=\"683\" src=\"https://heropress.com/wp-content/uploads/2024/04/346661b9e0cb19533.76383018-1024x683.jpg\" alt=\"A tiny spider of 1mm in size (cricket-bat orbweaver) touching and feeling two threads of it’s web, patiently waiting for it’s next meal.\" class=\"wp-image-6687\" /></a><a href=\"https://creativecommons.org/share-your-work/public-domain/cc0/\">CC0</a> licensed <a href=\"https://wordpress.org/photos/photo/346661b9e0/\">photo</a> by <a href=\"https://wordpress.org/photos/author/ramonvanraaij/\">Rámon van Raaij</a> from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>.\n\n\n\n<a href=\"https://heropress.com/wp-content/uploads/2024/04/95661a3b98e44915.97778049-scaled.jpg\"><img width=\"1024\" height=\"683\" src=\"https://heropress.com/wp-content/uploads/2024/04/95661a3b98e44915.97778049-1024x683.jpg\" alt=\"A black-orange bug (Cercopis vulnerata, en: Black-and-red Froghopper, dt: Blutzikade) on the tip of a green fern frond\" class=\"wp-image-6686\" /></a><a href=\"https://creativecommons.org/share-your-work/public-domain/cc0/\">CC0</a> licensed <a href=\"https://wordpress.org/photos/photo/95661a3b98/\">photo</a> by <a href=\"https://wordpress.org/photos/author/werkform/\">werkform</a> from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>.\n\n\n\n<a href=\"https://heropress.com/wp-content/uploads/2024/04/417661a5b074b8106.10890799-scaled.jpg\"><img width=\"1024\" height=\"683\" src=\"https://heropress.com/wp-content/uploads/2024/04/417661a5b074b8106.10890799-1024x683.jpg\" alt=\"Brown longhaired cows with a calf in pasture with a river in the background\" class=\"wp-image-6685\" /></a><a href=\"https://creativecommons.org/share-your-work/public-domain/cc0/\">CC0</a> licensed <a href=\"https://wordpress.org/photos/photo/417661a5b0/\">photo</a> by <a href=\"https://wordpress.org/photos/author/ramonvanraaij/\">Rámon van Raaij</a> from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>.\n\n\n\n<a href=\"https://heropress.com/wp-content/uploads/2024/04/531661ad94d12f749.22038538-scaled.jpeg\"><img width=\"844\" height=\"1024\" src=\"https://heropress.com/wp-content/uploads/2024/04/531661ad94d12f749.22038538-844x1024.jpeg\" alt=\"A close-up of a tabby cat with green eyes, slightly open mouth showing teeth, standing on a wooden floor.\" class=\"wp-image-6684\" /></a><a href=\"https://creativecommons.org/share-your-work/public-domain/cc0/\">CC0</a> licensed <a href=\"https://wordpress.org/photos/photo/531661ad94/\">photo</a> by <a href=\"https://wordpress.org/photos/author/mbigul/\">Bigul Malayi</a> from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>.\n\n\n\n<a href=\"https://heropress.com/wp-content/uploads/2024/04/5616618ae7c4966d5.43056222-rotated-1-scaled.jpeg\"><img width=\"768\" height=\"1024\" src=\"https://heropress.com/wp-content/uploads/2024/04/5616618ae7c4966d5.43056222-rotated-1-768x1024.jpeg\" alt=\"Statue of lord Krishna and Arjun representing the Mahabharat battle of Hindu religion.\" class=\"wp-image-6683\" /></a><a href=\"https://creativecommons.org/share-your-work/public-domain/cc0/\">CC0</a> licensed <a href=\"https://wordpress.org/photos/photo/5616618ae7/\">photo</a> by <a href=\"https://wordpress.org/photos/author/kafleg/\">KafleG</a> from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>.\n\n\n\n\n<p>Be sure to check out the <a href=\"https://wordpress.org/photos/\">hundreds of other great photos</a>!</p>\n</div></div>\n\n</div></div>\n\n\n<div class=\"wp-block-spacer\"></div>\n\n\n\n<p>The banner at the top of this post is a <a href=\"https://creativecommons.org/share-your-work/public-domain/cc0/\">CC0</a> licensed <a href=\"https://wordpress.org/photos/photo/8616439102/\">photo</a> by <a href=\"https://wordpress.org/photos/author/elisascagnetti/\">elisascagnetti</a> from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>.</p>\n\n\n\n\n\n<p>That&#8217;s it for this week! If you&#8217;d like to get this post in your email every week, <a href=\"https://heropressnetwork.com/newsletter\">make sure you sign up</a>!</p>\n<p>The post <a href=\"https://heropress.com/wceu-overcoming-limits-a-visit-to-torino/\">WCEU, Overcoming Limits, A Visit To Torino</a> appeared first on <a href=\"https://heropress.com\">HeroPress</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 14 Apr 2024 17:40:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:119:\"Gutenberg Times: Grid Layouts are coming, Playground for preview, Interactivity API in the wild — Weekend Edition 291\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=28216\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"https://gutenbergtimes.com/grid-layouts-are-coming-playground-for-preview-interactivity-api-in-the-wild-weekend-edition-291/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:18048:\"<p>Howdy, </p>\n\n\n\n<p>Don&#8217;t forget to save the date for the <a href=\"https://make.wordpress.org/core/2024/04/04/hallway-hangout-lets-chat-about-whats-next-in-gutenberg/\"><strong>Hallway Hangout: Let’s chat about what’s next in Gutenberg</strong></a> on April 24 at 11 pm UTC / 7pm EDT  / 4 pm PDT / 1 am CEST</p>\n\n\n\n<p><strong>Rob Cairns</strong> and I chatted on his podcast about <a href=\"https://stunningdigitalmarketing.com/episode-405-wordpress-6-5-and-beyond-with-birgit-pauli-haack/\">WordPress 6.5 and beyond</a>. </p>\n\n\n\n<p>Spring is back in Munich and it&#8217;s beautiful. We are really pushing getting out and walking around town, along the river or in our big park, with 5,000 other individualists.</p>\n\n\n\n<p>Have a splendid weekend ahead! </p>\n\n\n\n<p>Yours, 💕<br /><em>Birgit</em></p>\n\n\n\n<div class=\"wp-block-group has-light-background-background-color has-background\"><div class=\"wp-block-group__inner-container is-layout-flow wp-block-group-is-layout-flow\">\n<p><strong>Table of Contents</strong></p>\n\n\n\n<ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/grid-layouts-are-coming-playground-for-preview-interactivity-api-in-the-wild-weekend-edition-291/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/grid-layouts-are-coming-playground-for-preview-interactivity-api-in-the-wild-weekend-edition-291/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/grid-layouts-are-coming-playground-for-preview-interactivity-api-in-the-wild-weekend-edition-291/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/grid-layouts-are-coming-playground-for-preview-interactivity-api-in-the-wild-weekend-edition-291/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor. </a></li></ol>\n</div></div>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p><strong>Justin Tadlock</strong>, and others collected for you <a href=\"https://developer.wordpress.org/news/2024/04/10/whats-new-for-developers-april-2024/\"><strong>What’s new for developers? (April 2024)</strong></a> around WordPress 6.5, Core track and Gutenberg plugin. The table of contents listed 21 separate updates separated for Plugins developer and theme builders. </p>\n\n\n\n<img width=\"652\" height=\"334\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/04/image-1.png?resize=652%2C334&ssl=1\" alt=\"\" class=\"wp-image-28263\" /><em>Separate Color Style variations in sidebar. </em>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p>On April 9th, <strong>Aaron Jorbin</strong> and the merry band of Core contributors published the <a href=\"https://wordpress.org/news/2024/04/wordpress-6-5-2-maintenance-and-security-release/\"><strong>WordPress 6.5.2 Maintenance and Security Release</strong></a>. &#8220;<strong>Because this is a security release, it is recommended that you update your sites immediately.</strong>&nbsp;Backports are also available for other major WordPress releases, 6.1 and later.&#8221; Jorbin emphasized. Go and update if you haven&#8217;t yet. This can wait. </p>\n\n\n\n<p class=\"has-accent-color has-light-background-background-color has-text-color has-background has-link-color wp-elements-b6fe42ed62408b6fe464d62777dc0282\">🎙️ Latest episode: <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-98/\">Gutenberg Changelog #98 – WordPress 6.5, Gutenberg 18.0 Community Theme Project and the Contributor Mentorship Program</a> with special guest Maggie Cabrera</p>\n\n\n\n<p>Release lead, <strong>Ramon Dodd</strong>, published Gutenberg plugin version 18.1 and highlighted in his post <a href=\"https://make.wordpress.org/core/2024/04/10/whats-new-in-gutenberg-18-1-10-april/\"><strong>What’s new in Gutenberg 18.1? (10 April)</strong></a>:</p>\n\n\n\n<ul>\n<li><a href=\"https://make.wordpress.org/core/2024/04/10/whats-new-in-gutenberg-18-1-10-april/#set-site-background-images-in-the-site-editor\">Set site background images in the Site Editor</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2024/04/10/whats-new-in-gutenberg-18-1-10-april/#see-more-with-data-views\">See more with data views</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2024/04/10/whats-new-in-gutenberg-18-1-10-april/#pattern-schema-and-insertion\">Pattern schema and insertion</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2024/04/10/whats-new-in-gutenberg-18-1-10-april/#swap-and-edit-template-parts\">Swap and edit template parts</a></li>\n</ul>\n\n\n\n<img width=\"652\" height=\"376\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/04/18-1_background-1024x590-1.png?resize=652%2C376&ssl=1\" alt=\"\" class=\"wp-image-28244\" /><em>Sidewide background image</em>\n\n\n\n<p><strong>Anne McCarthy</strong> demo&#8217;d in this video <a href=\"https://www.youtube.com/watch?v=dN_LaenY8bI\"><strong>WordPress Playground: the ultimate learning, testing, &amp; teaching tool for WordPress</strong></a>. WordPress Playground is an open-source project that makes makes WordPress instantly accessible for users, learners, extenders, and contributors.  Thanks to the easy creation of instant, temporary WordPress sites in your browser, you don&#8217;t need a server or a test site or local environment. &#8220;At a high level, watching this video will give you a glimpse of what it is, what it does, and how you can use it today. I highly recommend getting comfortable using it, especially as we look to the future of WordPress.&#8221; McCarthy wrote.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong>Estela Rueda</strong> invites designers and theme builders to provide feedback <a href=\"https://make.wordpress.org/design/2024/04/09/the-new-grid-experience-feedback-needed/\"><strong>The new grid experience</strong>.</a> The grid aims to enhance the visual layout capabilities within WordPress by making it more flexible and easier to use for various design needs. To gather a wide range of opinions and suggestions, the team is reaching out and encouraging people to participate in the feedback process. By visiting the provided link, users can learn more about the new grid experience and contribute their input to help shape this upcoming feature.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong>Joen Asmussen</strong> highlighted in his <a href=\"https://make.wordpress.org/design/2024/04/08/design-share-mar-25-apr-5/\"><strong>Design Share: Mar 25-Apr 5</strong></a> the design team&#8217;s work for the last two weeks, mostly about refinements of the data views.</p>\n\n\n\n<ul>\n<li>Site Editor animation refinements</li>\n\n\n\n<li>Badge fields</li>\n\n\n\n<li>Explore&nbsp;UX&nbsp;around customizing bundled data views</li>\n\n\n\n<li>Bulk actions toolbar</li>\n\n\n\n<li>WP.org Homepage Updates</li>\n\n\n\n<li>Block&nbsp;Naming &amp; Connections</li>\n</ul>\n\n\n\n<img width=\"652\" height=\"303\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/04/design-share-bundle-views.webp?resize=652%2C303&ssl=1\" alt=\"\" class=\"wp-image-28264\" /><em>Bundled data views</em>\n\n\n<div class=\"ngl-articles colored ngl-articles-50_50 ngl-articles-frontend\">\n\n	\n	<div class=\"ngl-articles-wrap ngl-articles-webview\">\n	\n						\n			<div class=\"ngl-article-mobile\">\n				<div width=\"100%\" border=\"0\">\n					<div>\n						<div valign=\"top\">\n							<div class=\"ngl-article-mob-wrap\">\n							<div class=\"ngl-article-featured\"><a href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/\" target=\"_self\" rel=\"\"><img src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/04/Features-WordPress-6.5-scaled.jpeg?w=652&ssl=1\" /></a></div><div class=\"ngl-article-title\"><a href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/\" target=\"_self\" rel=\"\"><span>About WordPress 6.5 &#8211; all in one list on blocks and site editor</span></a></div><div class=\"ngl-article-excerpt\">This week, WordPress 6.5 certainly dominated the WordPress news cycle. Articles, Videos, Threads on X, and workshops are plenty available for every type of WordPress user. This list of resources&hellip;</div>							</div>\n						</div>\n					</div>\n				</div>\n			</div>\n			\n			\n			\n\n		\n		\n		</div>\n\n</div>\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p><strong>Anne McCarthy</strong> highlighted the features of the Create-block Theme plugin on Automattic&#8217;s Design blog: <a href=\"https://automattic.design/2024/02/15/diy-block-theme/\">DIY Block Theme</a> and invites you to &#8220;<em>learn to use the Create Block Theme plugin, like our designers do, to build your own block theme</em>&#8220;</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong>Nathan Wrigley</strong> and <strong>Anchen Le Roux  </strong>announced that this year&#8217;s<strong> </strong><a href=\"https://pagebuildersummit.com/\"><strong>Page Builder Summit 7.0</strong></a> is scheduled for <strong>May 20 through May 24, 2024</strong>. A stable for the last seven years, the Page builder Summit brings a large variety of experts together to help veteran and new site builders to get better at their craft. They provide insights into technology, business, and the design for freelancers building sites for others. The list of confirmed speakers is like the who-is-who of the business! </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong>Jamie Marsland</strong> shows you on YouTube how to <a href=\"https://www.youtube.com/watch?v=xvLctp65j-Y\"><strong>Master the Grid Layouts</strong></a>. Most great-looking websites utilize some sort of grid pattern in their page layout. But while many designers accomplish this using CSS Grid, new WordPress blocks let you do it right in the editor.  Marsland shows you how to use Grid and Grid Layout blocks to create a beautiful, functional WordPress site.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p>In his article &#8220;<a href=\"https://kau-boys.com/3609/wordpress/adding-some-colors-to-the-block-theme\"><strong>Adding some Colors to the Block Theme</strong></a>&#8220;,  <a href=\"https://twitter.com/2ndKauBoy\"><strong>Bernhard Kau</strong> </a>discusses how to best add various color options to a block theme.  It&#8217;s a deep dive into the process, starting with selecting a naming convention and how they appear in theme.json as well as in the site editor&#8217;s color picker. Then Kau describes how to apply colors to various sections of the site via the color picker to maintain brand recognition. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong>&nbsp;<a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" target=\"_blank\" rel=\"noreferrer noopener\">&#8220;Keeping up with Gutenberg &#8211; Index 2024&#8221;</a>&nbsp;</strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. The previous years are also available: <strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a>&nbsp;|&nbsp;<a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong>&nbsp;|&nbsp;<strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong>&nbsp;|&nbsp;<strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor. </h2>\n\n\n\n<p><strong><a href=\"https://twitter.com/magda_paciorek\">Magdalena Paciorek</a></strong> took a <strong><a href=\"https://developer.wordpress.org/news/2024/04/11/a-first-look-at-the-interactivity-api/\">A first look at the Interactivity API</a>,</strong> and walks you through an examples code for a Donation Calculator. It&#8217;s a great way to take a first deep dive into the Interactivity API with a great instructor from Poland. Paciorek is also a speaker at WordCamp Europe 2024. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong><a href=\"https://twitter.com/polevaultweb\">Iain Poulson</a></strong>, Advanced Custom Fields, mentioned in their release post for <a href=\"https://www.advancedcustomfields.com/blog/acf-6-2-8/\">ACF 6.2.8v</a>, that the team started <a href=\"https://www.advancedcustomfields.com/blog/acf-6-2-8/\">adding support&nbsp;</a>for Block Bindings API and Interactivity API. &#8220;From&nbsp;<a href=\"https://developer.wordpress.org/news/2024/02/20/introducing-block-bindings-part-1-connecting-custom-fields/\">Block Bindings</a>&nbsp;to the&nbsp;<a href=\"https://make.wordpress.org/core/2024/03/04/interactivity-api-dev-note/\">Interactivity API</a>, WordPress 6.5 brings new opportunities to use ACF data in core WordPress blocks, and new interactivity experiences to ACF Blocks. Some of these changes features require ACF to add compatibility, and this release begins that work.&#8221; Paulson wrote. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong><a href=\"https://twitter.com/scottkclark\">Scott Kingsley Clark</a></strong> mentioned in his release post for Pods 3.2v update that the framework supports the new WordPress 6.5&nbsp;<a href=\"https://pods.io/2024/03/25/pods-3-2-feature-release-meta-revisions-and-block-bindings/\">Block Bindings API</a>.  &#8220;Specify your source as&nbsp;<code>pods/bindings-field</code>&nbsp;and then just pass the same arguments you would pass for a normal&nbsp;<code>[pods]</code>&nbsp;Shortcode or block. This will bind that dynamic output to the block you are working with. &#8221; he wrote. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p>The recording of this week&#8217;s <a href=\"https://www.youtube.com/watch?v=ndW-Kz0iDdY\"><strong>Developer Hours: Building custom blocks with the Interactivity API</strong> </a>is available on YouTube. Damon Cook from WP Engine demonstrates how he built a form submission block that leverages the API. This example will teach you how to kick-start a custom interactive block using the Create Block package, use directives to assign critical attributes to your HTML markup, create the store, and hook up the client-side JavaScript. <a href=\"https://github.com/colorful-tones/feedback-block\"><em>The final plugin is also available on GitHub</em></a></p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review. </p>\n\n\n\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience</p>\n\n\n\n<p><img alt=\"GitHub all releases\" src=\"https://img.shields.io/github/downloads/bph/gutenberg/total?style=for-the-badge\" /></p>\n\n\n\n<p class=\"has-text-align-center has-small-font-size\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p>Featured Image: City with giant WordPress logo AI generated via Noel Tock</p>\n\n\n\n<hr class=\"wp-block-separator has-css-opacity is-style-wide\" />\n\n\n\n<p class=\"has-text-align-left\"><strong>Don&#8217;t want to miss the next Weekend Edition? </strong></p>\n\n\n<form class=\"wp-block-newsletterglue-form ngl-form ngl-portrait\" action=\"https://gutenbergtimes.com/feed/\" method=\"post\"><div class=\"ngl-form-container\"><div class=\"ngl-form-field\"><label class=\"ngl-form-label\" for=\"ngl_email\"><br />Type in your Email address to subscribe.</label><div class=\"ngl-form-input\"><input type=\"email\" class=\"ngl-form-input-text\" name=\"ngl_email\" id=\"ngl_email\" /></div></div><button type=\"submit\" class=\"ngl-form-button\">Subscribe</button><p class=\"ngl-form-text\">We hate spam, too, and won&#8217;t give your email address to anyone <br />except Mailchimp to send out our Weekend Edition</p></div><div class=\"ngl-message-overlay\"><div class=\"ngl-message-svg-wrap\"></div><div class=\"ngl-message-overlay-text\">Thanks for subscribing.</div></div><input type=\"hidden\" name=\"ngl_list_id\" id=\"ngl_list_id\" value=\"26f81bd8ae\" /><input type=\"hidden\" name=\"ngl_double_optin\" id=\"ngl_double_optin\" value=\"yes\" /></form>\n\n\n<hr class=\"wp-block-separator has-css-opacity is-style-wide\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 13 Apr 2024 04:44:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"Gravatar: Maximize Your Instagram Bio: The Top Tools to Consider\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"http://blog.gravatar.com/?p=1340\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"https://blog.gravatar.com/2024/04/12/maximize-your-instagram-bio-the-top-tools-to-consider/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:18773:\"<p>On Instagram, there are two places where you can put permanent and clickable links – your bio and your stories, which can become permanent highlights. Until April 2023, you could only put one link in your bio, but since then, Instagram has increased that number to five.&nbsp;</p>\n\n\n\n<p>However, even with that change, the author bio is still quite restrictive and doesn’t allow you to customize your profile fully or add other elements.&nbsp;</p>\n\n\n\n<p>The solution to that is to put a “transition” link – one that will open a new webpage filled with all the links your heart desires, whether it’s your blog, store, portfolio, or other relevant social media pages.&nbsp;</p>\n\n\n\n<p><a href=\"https://www.instagram.com/?hl=bg\">Instagram</a> doesn’t come with this feature, so in order to get the multifunctional “link in bio,” you need a specialized tool for the job. In this guide, we’ll introduce you to 10 excellent tools for breaking free from Instagram&#8217;s limitations and expanding your online presence effectively.</p>\n\n\n\n<p>Let’s start!&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>1. Gravatar&nbsp;</strong></h2>\n\n\n\n<img width=\"660\" height=\"403\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-21.png?w=660\" alt=\"\" class=\"wp-image-1342\" /><em>Gravatar homepage</em>\n\n\n\n<p>Instagram is just one platform, and if you want to create a permanent space on the internet, you need to think about your online presence beyond social media.&nbsp;</p>\n\n\n\n<p>One way to do that is by creating a universal profile – an online identity that travels with you no matter where you go. <a href=\"https://gravatar.com/\">Gravatar</a> by <a href=\"https://automattic.com/\">Automattic</a> is a free tool that can do that and much more. While not exclusively a “link in bio” tool, Gravatar still brings a lot of useful features that you can use to expand your Instagram bio section.&nbsp;</p>\n\n\n\n<p>Here is what you can do with it!&nbsp;</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Personalize your “About” section</strong></h3>\n\n\n\n<p>It’s hard to describe yourself in a captivating way with just 150 characters, but that’s all Instagram gives you. With Gravatar, however, you have the opportunity to craft an “About” section brimming with personality. When users click on the Gravatar link, they’ll be redirected to your Gravatar profile which will look more or less like this.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"373\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-22.png?w=660\" alt=\"\" class=\"wp-image-1343\" /><em>Gravatar profile bio section</em>\n\n\n\n<p>It’s a space where you can tell <em>your story</em>, sharing not just a basic bio but also details, such as your name, pronunciation, and location.&nbsp;</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>List your verified accounts</strong></h3>\n\n\n\n<p>Linking and showing your verified accounts is important as it gives you more brand credibility, whether you&#8217;re an influencer, CEO, author, academic speaker, and so on. As a result, people who open your Gravatar profile will be more inclined to follow you on different platforms beyond Instagram, and they&#8217;ll know where to go.</p>\n\n\n\n<p>With Gravatar, you can add multiple popular platforms, including <a href=\"https://wordpress.org/\">WordPress</a>, <a href=\"https://twitter.com/x\">X/Twitter</a>, <a href=\"https://www.tumblr.com/\">Tumblr</a>, <a href=\"https://www.tiktok.com/\">TikTok</a>, <a href=\"https://github.com/\">GitHub</a>, <a href=\"https://www.twitch.tv/\">Twitch</a>, and more.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"383\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-23.png?w=660\" alt=\"\" class=\"wp-image-1344\" /><em>Gravatar’s verified accounts list</em>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Add important links</strong></h3>\n\n\n\n<p>Confined by Instagram&#8217;s solo link policy? Gravatar can help! Accentuate your profile with curated links pointing to your latest blog posts, eCommerce stores, or other important profiles and pages.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"429\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-24.png?w=660\" alt=\"\" class=\"wp-image-1345\" /><em>Gravatar links feature</em>\n\n\n\n<p>The way you display your links matters! To increase their visibility, put your most important links at the top of your profile.&nbsp;</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Share payment links and cryptocurrency wallet addresses</strong></h3>\n\n\n\n<p>Besides normal links, with Gravatar you can also create a versatile and personalized wallet, adding payment links and cryptocurrency wallets. This allows you to add another way of monetizing your online presence, as well as gather money for charity and important causes.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"446\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-25.png?w=660\" alt=\"\" class=\"wp-image-1346\" /><em>Adding payment links to your Gravatar profile</em>\n\n\n\n<p>Connect with websites like <a href=\"https://play.google.com/store/apps/details?id=com.paypal.android.p2pmobile&hl=en_US\">PayPal</a>, <a href=\"https://www.patreon.com/\">Patreon</a>, <a href=\"https://venmo.com/\">Venmo</a>, <a href=\"https://bitcoin.org/\">Bitcoin</a>, <a href=\"https://litecoin.org/\">Litecoin</a>, and <a href=\"https://dogecoin.com/\">Dogecoin</a> in seconds! And the best part is that adding wallets will not clutter your “About” section. Instead, a new button will appear called “Pay” that people will be able to click and choose the best payment option.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"339\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-26.png?w=660\" alt=\"\" class=\"wp-image-1347\" /><em>The</em> <em>“Pay” button in Gravatar’s “About” section</em>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Add your contact information</strong></h3>\n\n\n\n<p>With Gravatar, you can centralize your contact information and save users from the hunt and peck of tracking down your email or phone number.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"259\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-27.png?w=660\" alt=\"\" class=\"wp-image-1348\" /><em>Gravatar contact information</em>\n\n\n\n<p>Include only what you’re comfortable sharing publicly, striking a balance between transparency and privacy.&nbsp;Similar to the payment options section, instead of putting everything in the same profile area, a new “Contact” button appears, containing all your contact information.&nbsp;</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Add photos</strong></h3>\n\n\n\n<p>Curate a selection of images that enhance your profile’s narrative. For photographers, this is a great place to put some of your work. If you’re a thought-leadership expert, put some pictures from conferences or lectures that you’ve done.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"359\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-28.png?w=660\" alt=\"\" class=\"wp-image-1349\" /><em>Gravatar uploading photos to the profile</em>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Customize your profile design</strong></h3>\n\n\n\n<p>Your Gravatar extends the reach of your Instagram bio, so it’s very important to customize your profile to mirror your brand identity. With control over design elements such as background colors and imagery, you can align your digital profile across all social media platforms, ensuring a consistent brand journey throughout.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"338\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-29.png?w=660\" alt=\"\" class=\"wp-image-1350\" /><em>Gravatar custom color background</em>\n\n\n\n<p></p>\n\n\n\n<img width=\"660\" height=\"307\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-30.png?w=660\" alt=\"\" class=\"wp-image-1351\" /><em>Gravatar custom background image</em>\n\n\n\n<p></p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>2. w.link</strong></h2>\n\n\n\n<img width=\"660\" height=\"405\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-31.png?w=660\" alt=\"\" class=\"wp-image-1352\" /><em>w.link homepage</em>\n\n\n\n<p></p>\n\n\n\n<p><a href=\"https://w.link/\">w.link</a> is a <a href=\"https://wordpress.com/\">WordPress</a> tool for creating a “link in bio” page that allows users to deeply personalize the presentation of their links. It works the same way as a WordPress site, which means that you need a domain to launch it and know how the <a href=\"https://wordpress.org/gutenberg/\">Gutenberg editor</a> works to get the most out of its features and customization options.&nbsp;</p>\n\n\n\n<p>Its main features include:&nbsp;</p>\n\n\n\n<ul>\n<li>Customization with CSS. </li>\n\n\n\n<li>Free themes and patterns. </li>\n\n\n\n<li>Unlimited pages and users. </li>\n\n\n\n<li>Built-in newsletter and RSS. </li>\n\n\n\n<li>Brute force protection. </li>\n\n\n\n<li>1 GB of storage (this can be upgraded if you opt for a paid plan).</li>\n</ul>\n\n\n\n<p>w.link has a free version, meaning you don’t pay for the tool, but you’ll still have to pay for a custom domain. It also has four pricing tiers, starting at $4/ month paid annually and going up to $45/month, all of which include a free domain for 1 year.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>3. Linktree</strong></h2>\n\n\n\n<img width=\"660\" height=\"324\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-32.png?w=660\" alt=\"\" class=\"wp-image-1353\" /><em>Linktree homepage</em>\n\n\n\n<p></p>\n\n\n\n<p>As one of the pioneers in bio-link tools, <a href=\"https://linktr.ee/\">Linktree</a> remains a strong contender in the market and comes with a free plan that offers a decent number of options. Still, its most important features, such as enhanced customization, priority links, and advanced analytics, such as click-through rates and audience demographics, are only included in the premium tiers.&nbsp;</p>\n\n\n\n<p>Other features include:&nbsp;</p>\n\n\n\n<ul>\n<li>Ability to add QR code. </li>\n\n\n\n<li>Unlimited links. </li>\n\n\n\n<li>Tip jar and “Buy Me a Gift” option. </li>\n\n\n\n<li>Button and font styles – only in paid plans. </li>\n\n\n\n<li>Custom background images – only in paid plans.</li>\n</ul>\n\n\n\n<p>There are three pricing options: Starter, $5/ month; Pro, $9/ month; and Premium, $24/month.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>4. Lnk.bio</strong></h2>\n\n\n\n<img width=\"660\" height=\"314\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-33.png?w=660\" alt=\"\" class=\"wp-image-1354\" /><em>Lnk.bio homepage</em>\n\n\n\n<p></p>\n\n\n\n<p><a href=\"https://lnk.bio/\">Lnk.bio</a> is a tool specially designed to fit Instagram’s UI, making it easy for everyone to customize their link page and use the tool.&nbsp;</p>\n\n\n\n<p>Other interesting features include:&nbsp;</p>\n\n\n\n<ul>\n<li>Instagram API. </li>\n\n\n\n<li>Unlimited links and a personal URL. </li>\n\n\n\n<li>Option to embed music tracks and videos. </li>\n\n\n\n<li>Customizable profile pictures and image backgrounds (only available in the highest tier).</li>\n\n\n\n<li>Reports that track link clicks and patterns in audience interactions over time (this is only for the paid plans).</li>\n</ul>\n\n\n\n<p>Their pricing structure is slightly different. You can use the free version, subscribe monthly for $0.99/month, or buy a lifetime subscription to the tool for $9.99 or $24.99, depending on the features you want.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>5. Link in Profile</strong></h2>\n\n\n\n<img width=\"660\" height=\"282\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-34.png?w=660\" alt=\"\" class=\"wp-image-1355\" /><em>Link in Profile homepage</em>\n\n\n\n<p>The unique proposition of <a href=\"https://linkinprofile.com/\">Link in Profile</a> lies in its ability to use Instagram posts as direct transactional opportunities for eCommerce businesses.&nbsp;</p>\n\n\n\n<p>Its main features include:&nbsp;</p>\n\n\n\n<ul>\n<li>Any URL mentioned in the post comments is sent directly to the landing page, transforming your Instagram feed into a marketplace. </li>\n\n\n\n<li>High levels of automation it provides so that when new posts are created, new links are added without extra effort from the user. </li>\n\n\n\n<li>Branded landing page with the Instagram profile picture and Instagram name. </li>\n\n\n\n<li>Easy integration with major websites and shopping platforms like <a href=\"https://www.amazon.com/\">Amazon</a>, <a href=\"https://www.etsy.com/\">Etsy</a>, and <a href=\"https://www.shopify.com/\">Shopify</a>. </li>\n</ul>\n\n\n\n<p>Link in Profile is a tool that mostly targets businesses and individuals who are looking for a good Return on Investment (ROI) and are focused on using Instagram to sell their products and services.&nbsp;</p>\n\n\n\n<p>There is no free version, but there is a free trial to their one plan, which is $9.99/month.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>6. Campsite</strong></h2>\n\n\n\n<img width=\"660\" height=\"355\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-35.png?w=660\" alt=\"\" class=\"wp-image-1356\" /><em>Campsite homepage</em>\n\n\n\n<p><a href=\"https://campsite.bio/\">Campsite</a> is a versatile tool suitable for independent creators, agencies, organizations, and small businesses. Its paid plans come with detailed analytics that go beyond basic tracking to include metrics like bounce rate and visitor behavior, crucial for understanding the efficiency of your online content.&nbsp;</p>\n\n\n\n<p>Other features include:&nbsp;</p>\n\n\n\n<ul>\n<li>User-friendly interface and easy navigation menus.</li>\n\n\n\n<li>Bulk link editing. </li>\n\n\n\n<li>Option to add images to links. </li>\n\n\n\n<li>Pre-made themes and high customization. </li>\n\n\n\n<li>SEO settings, UTM parameters, Google Analytics, and more marketing features for paid plans. </li>\n</ul>\n\n\n\n<p>You can choose between a personal account or an organization, both with two paid tiers – Pro and Pro+, starting from $7/month for a personal and $14 for organizations with two member profiles.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>7. Beacons.ai</strong></h2>\n\n\n\n<img width=\"660\" height=\"314\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-36.png?w=660\" alt=\"\" class=\"wp-image-1357\" /><em>Beacons.ai homepage</em>\n\n\n\n<p><a href=\"https://beacons.ai/\">Beacons.ai</a> is an all-in-one creator platform with multiple apps and services, such as an Audience Manager, Media Kit, Email Marketing, W-9 Generator, and <a href=\"https://beacons.ai/i/app-pages/link-in-bio\">Link-in Bio</a>.&nbsp;</p>\n\n\n\n<p>Its main features include:&nbsp;</p>\n\n\n\n<ul>\n<li>Fully customizable landing page. </li>\n\n\n\n<li>Option to collect contact information from fans. </li>\n\n\n\n<li>Ability to sell digital products with 1-tap checkout. </li>\n\n\n\n<li>Traffic analytics. </li>\n\n\n\n<li>Access to all Beacon tools. </li>\n</ul>\n\n\n\n<p>Beacons.ai is a dynamic social commerce tool that offers a lot, even in its free version. Still, for those wanting to upgrade, there are two options: A marketing bundle for $30/month and a VIP package starting at $100/month. The VIP plan comes with everything in the lower plan, a personal advisor to help you set up everything and a physical NFC business card for US and Canada users.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>8. Milkshake</strong></h2>\n\n\n\n<img width=\"660\" height=\"364\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-37.png?w=660\" alt=\"\" class=\"wp-image-1358\" /><em>Milkshake homepage</em>\n\n\n\n<p><a href=\"https://milkshake.app/\">Milkshake</a> is an interesting tool that allows its users to create an “Insta website” with its card-style layout, which adds a layer of interactivity. Each card represents a different page – an about section, testimonials, or showcase of work – offering a full-fledged website experience.&nbsp;</p>\n\n\n\n<p>Other features include:&nbsp;</p>\n\n\n\n<ul>\n<li>Easy customization from your smartphone. </li>\n\n\n\n<li>Analytics similar to the Story Analytics page on Instagram. </li>\n\n\n\n<li>Option to create multiple Milkshake websites for different Instagram accounts. </li>\n\n\n\n<li>Integration with other social media platforms. </li>\n</ul>\n\n\n\n<p>Milkshake is a free mobile application.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>9. Shor.by</strong></h2>\n\n\n\n<img width=\"660\" height=\"386\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-38.png?w=660\" alt=\"\" class=\"wp-image-1359\" /><em>Shor.by product page</em>\n\n\n\n<p><a href=\"https://dash.shor.by/smartpage?&lp\">Shor.by</a> is most popular for its dynamic feeds, which can auto-populate with content from blogs or online shops, making it a decent option for content creators and small business owners alike.&nbsp;</p>\n\n\n\n<p>Other features include:</p>\n\n\n\n<ul>\n<li>Messenger links that allow direct communication with followers and customers. </li>\n\n\n\n<li>Integration with popular services like <a href=\"https://www.whatsapp.com/\">WhatsApp</a> and <a href=\"https://www.messenger.com/?locale=bg_BG\">Facebook Messenger</a>. </li>\n\n\n\n<li>Block editor with an option to add images, videos, texts, products, RSS, and songs. </li>\n</ul>\n\n\n\n<p>Shor.by plans start from $15/month up to $99/month for agencies.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>10. Tap Bio</strong></h2>\n\n\n\n<img width=\"660\" height=\"394\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-39.png?w=660\" alt=\"\" class=\"wp-image-1360\" /><em>Tap Bio homepage</em>\n\n\n\n<p><a href=\"https://tap.bio/@tap.bio\">Tap Bio</a> is another tool that uses card-based profiles to engage audiences.&nbsp;</p>\n\n\n\n<p>Its main features include:&nbsp;</p>\n\n\n\n<ul>\n<li>Accessible interface with a gradual learning process for those new to digital storyboarding. </li>\n\n\n\n<li>Option to put additional cards and Instagram accounts. </li>\n\n\n\n<li>Statistics and analytics. </li>\n</ul>\n\n\n\n<p>There is a free Basic plan and two paid tiers for $5/month and $12/month. You can also opt for an annual payment of $36 and $96, respectively.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Take the next step: Advance your Instagram bio with Gravatar</strong></h2>\n\n\n\n<p>Whether you’re an independent creator, an agency, or a business, you don’t have to be confined to the restrictive nature of Instagram bios. Expand into a rich hub that fully represents you, your work, and your services.&nbsp;</p>\n\n\n\n<p>There are many great options for a “link in bio” tool, but Gravatar truly stands out as one of the best options. Not only is it completely free, but it also comes with a lot of important features, such as linking your other verified profiles, adding payment links and images, and customizing your profile to fit your brand fully.&nbsp;</p>\n\n\n\n<p>Ready to transform your Instagram bio into a dynamic portal? <a href=\"https://gravatar.com/\">Step into a broader digital footprint with Gravatar</a> and define your universal online profile.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 12 Apr 2024 18:22:37 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Ronnie Burt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"Do The Woo Community: Reimagining Affiliate Programs for Your Woo Biz with Alex Standiford\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=82067\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:89:\"https://dothewoo.io/reimagining-affiliate-programs-for-your-woo-biz-with-alex-standiford/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:184:\"This episode discusses affiliate programs in depth, emphasizing the need for personalized, collaborative relationships and exploring potential drawbacks of traditional affiliate links.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 12 Apr 2024 09:07:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:80:\"Do The Woo Community: CRM Insights and the Future of WordPress with Adrian Tobey\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=81057\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://dothewoo.io/crm-insights-and-the-future-of-wordpress-with-adrian-tobey/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:268:\"In today\'s episode of Woo BizChat, Adrian Tobey from Groundhogg emphasizes the importance of CRM for businesses and the early adoption of CRM for WooCommerce shops. He also discusses potential barriers to CRM success and contemplates the future of content consumption.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 11 Apr 2024 09:55:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"Gravatar: Roadmap to a Killer Personal Brand: Essential Digital Tools\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"http://blog.gravatar.com/?p=1305\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://blog.gravatar.com/2024/04/10/personal-branding-tools/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:24424:\"<p>Whether you’re a content creator, influencer, CEO, academic, artist, or entrepreneur, building your personal brand is essential. Your brand is a mark of your unique value, so giving it more visibility helps you stand out, gives more credibility to your professional resume, and opens up a world of opportunities.&nbsp;</p>\n\n\n\n<p>You might already be thinking about your brand in your daily life, from the way you interact with your peers to the way you present yourself at networking events. But as we know, for a brand to be truly successful, it has to exist on the internet.&nbsp;</p>\n\n\n\n<p>But how do you even <em>start</em> building your personal brand in an online space where everyone is trying to do the same? The answer lies in choosing the right digital tools and platforms that help you hit your branding goals. There are thousands of tools, and not all of them will be right for your needs, which can be daunting.&nbsp;</p>\n\n\n\n<p>That’s why, to help you in your branding efforts, we gathered the best online tools to streamline this process, ensuring your personal brand reflects your true Unique Value Proposition (USP) and gets the visibility it deserves.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Website creation tools</strong></h2>\n\n\n\n<p>Your website is the cornerstone of your brand. This is a given if you offer services or have an eCommerce platform, but if your brand centers around your online persona, you might be wondering whether you even need a website if you’re maintaining your social media profiles.&nbsp;</p>\n\n\n\n<p>Social media is powerful for building an audience – there’s no doubt about that. But in reality, a website is still the granddaddy of online presence because of its dynamic and highly customizable nature.&nbsp;</p>\n\n\n\n<p>Social media platforms will confine you to work within their limitations, which means you will need to adapt your content style to what works best for their algorithms. It can be hard to present a proper biography, an overview of your work, and evergreen content on such platforms.&nbsp;</p>\n\n\n\n<p>On the other hand, a website can be whatever you want it to be – you are in full control of the way it looks and functions, and what content is posted.&nbsp;</p>\n\n\n\n<p>Whether showcasing a portfolio, hosting a blog, or highlighting services, your site is where long-lasting impressions are made, and an essential part of creating an effective website lies in picking the right tools.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Build your website on WordPress.com</strong></h3>\n\n\n\n<img width=\"660\" height=\"378\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image.png?w=660\" alt=\"\" class=\"wp-image-1308\" />\n\n\n\n<p><em>WordPress.com homepage</em></p>\n\n\n\n<p><a href=\"https://wordpress.org/\">WordPress.org</a> is <a href=\"https://w3techs.com/technologies/details/cm-wordpress\">the most popular Content Management System</a> (CMS), and it’s used by brands like <a href=\"https://slack.com/\">Slack</a>, <a href=\"https://thewaltdisneycompany.com/\">Disney</a>, <a href=\"https://edition.cnn.com/\">CNN</a>, and <a href=\"https://about.meta.com/\">Meta</a>. If you want to build a site with WordPress, we recommend choosing <a href=\"http://wordpress.com\">WordPress.com</a> as your trusted hosting provider, as it comes with built-in security and analytics tools and automatic updates.&nbsp;</p>\n\n\n\n<p>With all the technicalities taken care of, you’ll have the time and opportunity to build a great site that fully reflects your personal brand and professional goals.&nbsp;</p>\n\n\n\n<p>There are several tiers to WordPress.com, but the <a href=\"https://wordpress.com/pricing/\">Creator plan</a> is the best option for professionals as it allows you to add unlimited plugins and themes. On the other hand, the integration with <a href=\"https://jetpack.com/\">Jetpack</a> gives you essential tools to track engagement, monitor traffic sources, and understand your target audience&#8217;s demographics.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"429\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-1.png?w=660\" alt=\"\" class=\"wp-image-1309\" />\n\n\n\n<p><em>WordPress.com pricing</em></p>\n\n\n\n<p>With the Creator plan, it is very easy to get started, and if you’re serious about personal branding, having unlimited access to plugins and themes will be extremely helpful. Customize to your heart&#8217;s content with design options that resonate with your personal aesthetic, or extend functionality with plugins that offer everything from Search Engine Optimization (SEO) to social media integration.&nbsp;</p>\n\n\n\n<p>With its automatic updates, scheduling abilities, and built-in analytics, WordPress.com lets you spend more time creating brand-centric content instead of worrying about admin tasks.&nbsp;</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Add eCommerce functionality with WooCommerce</strong></h3>\n\n\n\n<img width=\"660\" height=\"330\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-2.png?w=660\" alt=\"\" class=\"wp-image-1310\" />\n\n\n\n<p><em>WooCommerce homepage</em></p>\n\n\n\n<p>One of the beautiful things about WordPress is that you can easily turn your website into an online store thanks to <a href=\"https://woo.com/\">WooCommerce</a> – the eCommerce platform <a href=\"https://barn2.com/blog/woocommerce-stats/#:~:text=The%20wordpress.org%20plugin%20repository,on%20the%20internet%20use%20WooCommerce.\">used by more than 4 million websites worldwide</a> to effectively sell their products and services online!&nbsp;</p>\n\n\n\n<p>This interactive commercial platform comes with many useful features, such as the option to add customer reviews to your product, build beautiful and categorized product galleries, upsell and cross-sell products and services, and fully customize product and checkout pages.&nbsp;</p>\n\n\n\n<p>If you want to branch out to eCommerce, we recommend opting for the <a href=\"https://wordpress.com/pricing/#:~:text=power%20of%20WooCommerce.-,Entrepreneur,-Build%20an%20online\">Entrepreneur plan</a> on WordPress.com, as it’s specially developed for people who want a full-fledged online store.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"569\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-3.png?w=660\" alt=\"\" class=\"wp-image-1311\" />\n\n\n\n<p><em>WordPress.com pricing plans</em></p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Build a newsletter</strong></h2>\n\n\n\n<p>Email marketing is powerful and still very popular among digital marketers. In fact, this marketing strategy is one of the most profitable, with a <a href=\"https://www.statista.com/statistics/804656/email-roi-perception/\">mind-boggling ROI of $36 for every dollar spent</a>.&nbsp;</p>\n\n\n\n<p>Email gives you a direct line of communication with your audience and builds a longer-lasting relationship, which is especially true with newsletters. A periodic newsletter filled with interesting how-to guides, industry insights, or inspiring success stories not only provides immense value but also bolsters engagement with your brand.&nbsp;</p>\n\n\n\n<p>WordPress.com includes a <a href=\"https://wordpress.com/newsletter/\">newsletter feature</a> with every plan, and you can easily include one anywhere on your website by adding a “subscribe” block.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"198\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-4.png?w=660\" alt=\"\" class=\"wp-image-1312\" />\n\n\n\n<p><em>WordPress subscribe block</em></p>\n\n\n\n<p>The placement is very important, so we recommend putting this form above the fold on your homepage or as a call to action at the end of a compelling blog post to boost subscription rates.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"299\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-5.png?w=660\" alt=\"\" class=\"wp-image-1313\" />\n\n\n\n<p><em>Example of placing a subscribe option above the fold</em></p>\n\n\n\n<p>This functionality allows you to convert your blog updates into rich, engaging newsletters. With no cap on the number of emails you can send, WordPress.com hands you the reins to grow your subscriber base unconstrained, unlike other platforms that may restrict your reach.&nbsp;</p>\n\n\n\n<p>Besides that, it also allows you to create gated content which is a strategy where exclusive content is provided to subscribers. The only thing you need to do is click on “Set up a paid plan” and a new window will pop up, allowing you to fully customize your paid newsletter.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"430\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-6.png?w=660\" alt=\"\" class=\"wp-image-1314\" />\n\n\n\n<p><em>Creating a paid newsletter with WordPress</em></p>\n\n\n\n<p>This feature on WordPress.com helps you reward and retain your most loyal followers, cementing a strong community around your personal brand.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Unify your digital presence across all platforms with Gravatar</strong></h2>\n\n\n\n<img width=\"660\" height=\"403\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-7.png?w=660\" alt=\"\" class=\"wp-image-1315\" />\n\n\n\n<p><em>Gravatar homepage</em></p>\n\n\n\n<p>When building your personal brand, you need to think of your online identity as a whole, not as different pieces independent of each other. Build your social media presence and blog as a cohesive online existence, which means syncing your information across platforms.&nbsp;</p>\n\n\n\n<p><a href=\"https://gravatar.com/\">Gravatar</a> is an efficient tool that centralizes and streamlines your online identity across the web, powered by your email address.&nbsp;</p>\n\n\n\n<p>Getting started with Gravatar is quick and user-friendly. With just a few steps, you’ll have a unique avatar that follows you from site to site, attaching a familiar face to your online commentary and interactions.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"373\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-8.png?w=660\" alt=\"\" class=\"wp-image-1316\" />\n\n\n\n<p><em>Example of a Gravatar profile&nbsp;</em></p>\n\n\n\n<p>Instead of adjusting your profile for each platform, you’ll have a consistent identity everywhere, including important and up-to-date details such as contact information and events.&nbsp;</p>\n\n\n\n<p>A single digital signature allows you to build a consistent online identity, making your personal brand more memorable and credible. By unifying your digital presence, Gravatar alleviates the hassle of managing multiple logins and profiles. This convenience is not only a time-saver but ensures your online identity is uniform and professional.&nbsp;</p>\n\n\n\n<p>When you create your profile, you can fully customize it to fit your needs. Here are some of the great things you can do with Gravatar’s profile editor:&nbsp;</p>\n\n\n\n<ul>\n<li>Finetune your profile background with custom colors and images.&nbsp;</li>\n</ul>\n\n\n\n<img width=\"660\" height=\"307\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-9.png?w=660\" alt=\"\" class=\"wp-image-1317\" />\n\n\n\n<p><em>Adding a custom background image to your Gravatar profile</em></p>\n\n\n\n<ul>\n<li>Connect your verified social media accounts and other profiles.&nbsp;</li>\n</ul>\n\n\n\n<img width=\"660\" height=\"383\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-10.png?w=660\" alt=\"\" class=\"wp-image-1318\" />\n\n\n\n<p><em>Linking verified accounts to your Gravatar profile</em></p>\n\n\n\n<ul>\n<li>Add customized links to promote blog posts, featured articles, upcoming events, and products.&nbsp;</li>\n</ul>\n\n\n\n<img width=\"660\" height=\"429\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-11.png?w=660\" alt=\"\" class=\"wp-image-1319\" />\n\n\n\n<p><em>Adding different links to your Gravatar profile</em></p>\n\n\n\n<ul>\n<li>Add your contact information so that people can easily get in touch.&nbsp;</li>\n</ul>\n\n\n\n<img width=\"660\" height=\"259\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-12.png?w=660\" alt=\"\" class=\"wp-image-1320\" />\n\n\n\n<p><em>Adding contact information to your Gravatar profile</em></p>\n\n\n\n<ul>\n<li>There is a QR code feature so you can quickly share your profile during networking events or put it on your physical business card.&nbsp;</li>\n</ul>\n\n\n\n<img width=\"660\" height=\"385\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-13.png?w=660\" alt=\"\" class=\"wp-image-1321\" />\n\n\n\n<p><em>QR code options for Gravatar profiles</em></p>\n\n\n\n<p>Besides the QR code, you can also generate a short link to put on your social media accounts, serving as a versatile “Link in bio” landing page.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Leverage the social media platforms that make sense for your brand</strong></h2>\n\n\n\n<p>We won’t go into too much detail about the different social media platforms, as you’re probably already aware of the most popular ones. But we do want to highlight two very important rules:&nbsp;</p>\n\n\n\n<ol>\n<li><strong>Don’t worry about being everywhere. Instead, go where your target audience is.</strong> If you’re building your personal brand as an eCommerce leadership expert, chances are your most loyal audience is on <a href=\"https://www.linkedin.com/\">LinkedIn</a> rather than <a href=\"https://www.tiktok.com/\">TikTok</a> or <a href=\"https://www.instagram.com/?hl=bg\">Instagram</a>. On the other hand, if you’re a creative personality, like an artist or a musician, then social media platforms with a younger demographic would be a better place</li>\n\n\n\n<li><strong>Be consistent in your posting. </strong>This is a universal rule among social media – you won’t be successful if you’re inconsistent with your posting schedule. What helps here is to create a social media calendar and plan out your content for the next month or two.&nbsp;</li>\n</ol>\n\n\n\n<p>Another thing you should remember if you use various platforms is that you want to retain some level of consistency in terms of how you present yourself, and furthermore, it should be easy for people to recognize your personal profile across different profiles</p>\n\n\n\n<p>Gravatar can help you maintain this consistency by giving users a constantly updated overview of your professional identity, including a list of verified social media profiles like X/Twitter (the official one, not the fish one), TikTok, <a href=\"https://www.tumblr.com/\">Tumblr</a>, Instagram, <a href=\"https://bsky.social/\">Bluesky</a>, as well as your personal WordPress website, adding even more credibility. </p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Other tools for content creation and sharing</strong></h2>\n\n\n\n<p>Consistently creating great content is hard! Thankfully, there are plenty of tools to help you out at all stages of the content development process, like the organization and planning, ideation, creation, optimization, and promotion of the final product. With the right tools, you can create a workflow that is tailored to your needs and individual processes, allowing you to be consistent with your production.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Tools for organization and content mapping</strong></h3>\n\n\n\n<p><a href=\"https://www.notion.so/integrations/asana\">Notion</a> and <a href=\"https://asana.com/\">Asana</a> are great for content planning, each offering unique benefits that can result in a more polished and professional brand persona.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"403\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-15.png?w=660\" alt=\"\" class=\"wp-image-1323\" />\n\n\n\n<p><em>Notion and Asana integration</em></p>\n\n\n\n<p>Notion&#8217;s all-encompassing workspace allows for meticulous planning, crafting, and cataloging of ideas, ensuring a brand&#8217;s narrative unfolds with precision. Asana guides the creative process with its strong project management tools, improving the content production and delivery process.</p>\n\n\n\n<p>It&#8217;s worth noting, however, that the richness of features in <a href=\"https://asana.com/apps/notion-asana\">Notion and Asana</a> comes with a moderate learning curve, but there are many <a href=\"https://forum.asana.com/t/multiple-ways-to-integrate-asana-and-notion-2023-guide/482947\">useful resources by brands</a> and other users, <a href=\"https://www.youtube.com/watch?v=g0rYATuSYnI\">especially on YouTube</a>, to help you get used to the tools.&nbsp;</p>\n\n\n\n<p>Thankfully, if you’re already familiar with the Gutenberg WordPress Editor, you shouldn’t have any issues with Notion, as their interfaces are very similar.&nbsp;</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Google Trends for ideation</strong></h3>\n\n\n\n<img width=\"660\" height=\"348\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-16.png?w=660\" alt=\"\" class=\"wp-image-1324\" />\n\n\n\n<p><em>Google Trends homepage</em></p>\n\n\n\n<p>Diving into <a href=\"https://trends.google.com/trends/\">Google Trends</a>&#8216; ocean of insights reveals a highly valuable tool that offers a glimpse into the collective consciousness. By leveraging such data, brands can adjust their content to match audience interests.&nbsp;</p>\n\n\n\n<p>Interpreting the peaks and valleys of trending topics leads to informed decisions that anchor a content strategy in the present. For instance, a digital marketer might spot an emerging trend in sustainable living and weave this theme into their blog articles, social media posts, and podcasts.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Image and video editor tools</strong></h3>\n\n\n\n<p>According to a study by the US Chambers of Commerce, <a href=\"https://gitnux.org/branding-statistics/#:~:text=The%20US%20Chamber%20of%20Commerce,recognition%20by%20up%20to%2080%25.\">55% of first impressions of brands are visual</a>, which is another proof of how important your visual representation is. It needs to be engaging, unique, and, most importantly, represent your personal values and best qualities.&nbsp;</p>\n\n\n\n<p>Not everyone is a designer but thankfully, there are tools to help every single professional to create a consistent visual brand. One of the most prominent platforms to do that is <a href=\"https://www.canva.com/en_gb/\">Canva</a>, which offers a library of templates, photos, and illustrations that can be customized to align with your personal brand’s visual theme.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"348\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-17.png?w=660\" alt=\"\" class=\"wp-image-1325\" />\n\n\n\n<p><em>Canva design tool homepage</em></p>\n\n\n\n<p>Canva Pro, the premium version, extends these capabilities with additional features like brand kits and background removal, providing an even more tailored design experience.&nbsp;</p>\n\n\n\n<p>For people looking to enhance their video editing skills, <a href=\"https://www.adobe.com/products/premiere-rush.html\">Adobe Premiere Rush</a> is a free mobile and desktop app that offers various features to help your brand grow. Its built-in camera, for example, allows for high-quality video capture, while intuitive editing tools help edit and share from anywhere, ensuring your visual narrative remains cohesive.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"386\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-18.png?w=660\" alt=\"\" class=\"wp-image-1326\" />\n\n\n\n<p><em>Adobe Premiere Rush homepage</em></p>\n\n\n\n<p>For budding personal brands, this tool simplifies the creation of professional-looking content that can resonate with audiences across various platforms.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>URL Shorteners</strong></h3>\n\n\n\n<p>URLs can be very long which makes the process of integrating them troublesome and not aesthetically pleasing. To resolve this, you can use a URL shortener. These are smart tools that allow you to create custom links with your brand name and can also track engagement.&nbsp;</p>\n\n\n\n<p>A great URL-shortening tool is <a href=\"https://www.rebrandly.com/\">Rebrandly</a> – an AI platform with more than 100 popular integrations.&nbsp;</p>\n\n\n\n<img width=\"660\" height=\"507\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-19.png?w=660\" alt=\"\" class=\"wp-image-1327\" />\n\n\n\n<p><em>Rebrandly homepage</em></p>\n\n\n\n<p>It works by selecting a relevant domain name related to your brand and using it as a consistent base for all your short links. This practice not only reinforces brand visibility but also offers detailed analytics insights to evaluate the effectiveness of your shared content.&nbsp;</p>\n\n\n\n<p>Using these analytics can transform raw data into strategic action. By examining click patterns and traffic sources, you can fine-tune your content scheduling and distribution strategies to better capture your audience&#8217;s attention.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Monitor and refine your results with analytics tools</strong></h2>\n\n\n\n<p>Building a personal brand is a continuous process, and analytical tools can provide you with helpful performance indicators. These tools clarify which areas of your personal branding strategy are thriving and which require refinement.&nbsp;</p>\n\n\n\n<p>For those just starting out on their personal branding journey, focusing on key analytics like engagement rate, follower growth over time, and website conversions can be incredibly insightful.</p>\n\n\n\n<p>Most social media platforms come with their own analytics dashboards that show metrics such as engagement rates, best-performing content by reach, and follower demographics. These data points highlight which content truly resonates with your audience, informing not only what you create but also how you can create deeper connections. You can then use these insights by experimenting with content types and posting times, and then measure the changes in engagement for continuous improvement.&nbsp;</p>\n\n\n\n<p>For example, when open rates for your newsletter seem low, consider A/B testing with different subject lines or content structures. Track the subsequent open and click-through rates to identify the most engaging approach, thus maintaining a dynamic and relevant correspondence with your audience.&nbsp;</p>\n\n\n\n<p>When it comes to website analytics, <a href=\"https://accounts.google.com/signin/v2/identifier?service=analytics&passive=1209600&continue=https%3A%2F%2Fanalytics.google.com%2Fanalytics%2Fweb%2F%23&followup=https%3A%2F%2Fanalytics.google.com%2Fanalytics%2Fweb%2F&flowName=GlifWebSignIn&flowEntry=ServiceLogin\">Google Analytics</a> is the industry standard. However, for WordPress users, <a href=\"https://jetpack.com/\">Jetpack</a> offers an accessible alternative and it’s included in both the Creator and Entrepreneur plans with WordPress.com. It provides intuitive metrics such as daily visitors, page views, and top-performing pages, all critical in gauging the traction of your online content without the daunting complexity of Google&#8217;s service.</p>\n\n\n\n<img width=\"660\" height=\"362\" src=\"https://blog.gravatar.com/wp-content/uploads/2024/04/image-20.png?w=660\" alt=\"\" class=\"wp-image-1328\" />\n\n\n\n<p><em>Jetpack homepage</em></p>\n\n\n\n<p>Conclude each analysis session with a commitment to apply what you&#8217;ve learned. Set regular intervals for review – be it weekly, bi-weekly, or monthly – to ensure your personal brand remains vibrant and effective. Remember, consistent analysis is a foundational practice that nurtures a strong and resonant personal brand, keeping you one step ahead in the exciting world of online branding.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Create a personal brand that stands out with Gravatar&nbsp;</strong></h2>\n\n\n\n<p>Creating and maintaining your personal brand is a lot of work, but don’t be discouraged! With the right tools, patience, and consistency, you can craft a professional brand that makes you proud and opens up a world of possibilities.&nbsp;</p>\n\n\n\n<p>One of the tools that will be with you every step of the way is Gravatar – your trusted online identity that travels with you no matter where you go.&nbsp;</p>\n\n\n\n<p>Gravatar is not just another addition to your digital toolset but a fundamental component that connects the dots between your various online activities. With Gravatar, you receive a unique advantage – a consistent identity that travels with you everywhere and allows you to be easily recognized by your audience.&nbsp;</p>\n\n\n\n<p>Why wait to consolidate your digital brand? <a href=\"https://gravatar.com/\">Sign up for Gravatar for free</a> and take the first step towards a unified identity. It’s time to align your online presence with your professional aspirations.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 10 Apr 2024 21:27:18 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Ronnie Burt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"WPTavern: #115 – Jamie Marsland on Turning Technical Know-How Into Popular Content\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=155317\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"https://wptavern.com/podcast/115-jamie-marsland-on-turning-technical-know-how-into-popular-content\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47823:\"Transcript<div>\n<p>[00:00:00] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p>Jukebox is a podcast, which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, turning technical know-how into popular content.</p>\n\n\n\n<p>If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com forward slash feed forward slash podcast. And you can copy that URL into most podcasts players.</p>\n\n\n\n<p>If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com forward slash contact forward slash jukebox, and use the form there.</p>\n\n\n\n<p>So on the podcast today, we have Jamie Marsland.</p>\n\n\n\n<p>Jamie has a varied background in technical corporate leadership, and has been guiding Pootlepress for over a decade. Initially a training service, Pootlepress has become a product focused company known for its WordPress plugins. Jamie&#8217;s depth of experience in the industry is increasingly overshadowed by his visibility as a YouTuber, where, as you&#8217;ll hear, much of his attention is now focused.</p>\n\n\n\n<p>In this episode, we&#8217;ll cover some new ground. We talk about a critical issue facing WordPress today, the fierce competition from platforms like Canva and Wix, and the marketing hurdles that WordPress must navigate to maintain its market share.</p>\n\n\n\n<p>We also explore Jamie&#8217;s unconventional path to becoming a content creator, discussing how he went from teaching tennis to teaching tech, and how he&#8217;s leveraged YouTube to grow his audience and business. His perspective is that it&#8217;s important to make technical concepts accessible and easy to understand.</p>\n\n\n\n<p>Making his content is a lot of work, most of which happens behind the scenes. We get into this a little more deeply, and Jamie shares his strategies for effective video creation, from planning to execution, along with his thoughts on sponsored content and its place in the YouTube ecosystem.</p>\n\n\n\n<p>If you&#8217;re curious about the future of WordPress, content creation, or the dynamics of digital learning this episode is for you.</p>\n\n\n\n<p>If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com forward slash podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p>And so without further delay, I bring you Jamie Marsland.</p>\n\n\n\n<p>I am joined on the podcast by Jamie Marsland. Hi Jamie.</p>\n\n\n\n<p>[00:03:08] <strong>Jamie Marsland:</strong> Hey there. How are you?</p>\n\n\n\n<p>[00:03:10] <strong>Nathan Wrigley:</strong> Very good. Thank you for joining me today. If you haven&#8217;t checked out what Jamie&#8217;s been doing, Jamie has had a really interesting career in the WordPress space. We&#8217;re going to talk about that. We&#8217;ll talk about his YouTube channel, and how he&#8217;s managed to grow that over the last couple of years. Before we do that Jamie, I wonder if you could introduce yourself, give us your quick WordPress bio.</p>\n\n\n\n<p>[00:03:29] <strong>Jamie Marsland:</strong> So quick WordPress bio. I&#8217;ve been running this business, Pootlepress for 14 years. Prior to that though, I had a corporate career in technical, both public businesses and private businesses, running businesses. But always in publishing, and in software publishing. I always say that because people just see me as a YouTuber these days, so I want people to understand there&#8217;s a bit more background to it.</p>\n\n\n\n<p>And then the last 14 years, I&#8217;ve been running Pootlepress. And we started off as a training business, and then we morphed into a product business. Built some plugins, which we still provide. And then over the last three years, I&#8217;ve been committing to creating content, primarily over YouTube.</p>\n\n\n\n<p>[00:04:04] <strong>Nathan Wrigley:</strong> Tell us a little bit about Pootlepress. What were the bits and pieces that you got yourself involved in? And are you a coder? Do you write the code, or did you write the code yourself? Do any of those projects still have a life, or have they been shelved for now?</p>\n\n\n\n<p>[00:04:16] <strong>Jamie Marsland:</strong> As I said, it started off as a training business, which was literally, I left my previous job. I&#8217;d introduced WordPress into that business, and we had a very expensive development team. We were running a different CMS, which nobody would&#8217;ve heard of, it was called Ektron. But it was about $5,000 per site, per year, so it was, you know, in terms of WordPress. But that was at the very low end of the CMS market. But in terms of WordPress, which is obviously free, it was much more expensive.</p>\n\n\n\n<p>And I introduced WordPress into that business. I could sort of see the market was shaking out a bit. And I looked at the WordPress market from that job, and seeing what was going on. And there were people running training courses in WordPress, but they were charging £500 a day for a WordPress training course, and selling them out.</p>\n\n\n\n<p>And I thought, that&#8217;s quite interesting. But they were going after the sort of corporate market. When I left that business, they gave me a chunk of money, and so I had some time. So I thought, well, I could start a WordPress training business. And so I took out a Google ad, and I launched a WordPress training course, because I knew WordPress really well, because I&#8217;d been using it personally for a long time.</p>\n\n\n\n<p>And I pitched a course, I think it was £99, or something like that. And within half a day I got my first order. I thought, well that&#8217;s interesting, there&#8217;s a market here. And then I ended up running 2 courses a week, with about 15 people in, traveling around the country. I ran them in London, where I&#8217;m based in Chatham. Ended up in Scotland, also Wales.</p>\n\n\n\n<p>So all around the country, running these face-to-face training courses, with people in a room, training people on WordPress. And there&#8217;s nothing quite like seeing face-to-face people using WordPress to understand, I&#8217;m going to talk about the product business in a minute, but understand some of the issues people have with WordPress, when you&#8217;re actually training them.</p>\n\n\n\n<p>I&#8217;ve traveled a lot of miles, and personally trained thousands of people now on WordPress, which is just an incredible experience to have, which you don&#8217;t actually realise until you&#8217;ve sort of gone through it.</p>\n\n\n\n<p>And then, from that, we built some plugins, and we&#8217;re going back a while now. So we built some plugins around Woo, as they were, Woo Themes. And, yeah, those plugins are still going, and we still have customers, and they&#8217;re actively supported. And the plugins now we&#8217;re releasing are Gutenberg based, I guess you&#8217;d say. So block based plugins.</p>\n\n\n\n<p>And we were there right at the start of that. So we have a free plugin called Caxton, which nobody understands, but it&#8217;s named after William Caxton. If you&#8217;re English, you probably know that. He was a, the equivalent of Gutenberg but English. And that was launched in Nashville, which Matt Mullenweg demoed actually, as part of his presentation of the launch of Gutenberg. So we were right there, right at the start of Gutenberg. So I&#8217;ve always understood that Gutenberg was going to be a big driver in the space.</p>\n\n\n\n<p>[00:06:38] <strong>Nathan Wrigley:</strong> It sounds like there&#8217;s a common thread running through quite a bit of that, which is educator basically. Do you have a sort of traditional background in education, or is it just something you find yourself drawn towards and capable of doing?</p>\n\n\n\n<p>[00:06:50] <strong>Jamie Marsland:</strong> Well, I was a tennis coach when I was 19 to 23, to help fund uni education, partly. So played a lot of tennis. And I loved coaching, I loved teaching. And looking back on that experience, that was like, okay, that&#8217;s quite an interesting thing. So I&#8217;m thinking of redoing my, they lapse tennis coaching qualifications, I&#8217;m thinking of retaking them, and going back to it at some point. Because I absolutely love teaching. You realise this as you go through this career, but I love the teaching bit of it, so yeah.</p>\n\n\n\n<p>[00:07:18] <strong>Nathan Wrigley:</strong> Do you find there&#8217;s any, the same level of love for the online teaching? Because when you described your WordPress teaching, it sounded like you were in the room with the people. And so you obviously get that immediate feedback and, you know, it&#8217;s not done via an email saying, thank you, I enjoyed your course, or whatever. You&#8217;re actually seeing people&#8217;s faces light up and what have you.</p>\n\n\n\n<p>But with the YouTube content, and all of the other bits and pieces, I just wonder if there&#8217;s any connection between your end users, your students, if you like. Do you get that same warm and fuzzy feeling?</p>\n\n\n\n<p>[00:07:45] <strong>Jamie Marsland:</strong> Yeah, definitely is, because the videos on YouTube get tons of comments these days, and I get loads of personal emails, and it&#8217;s the same with teaching people in a room. You know, you teach people in a room and you literally, it sounds a bit overblown, but people do email you and say, this is, you know, I&#8217;ve built a business out of this teaching, thank you. And it&#8217;s changed the direction of my life.</p>\n\n\n\n<p>And you definitely get that, it&#8217;s different on YouTube, but you definitely get that. Comments are fantastic, and the likes are fantastic as well. So yeah, I mean you do get that sense of fulfillment with it. And I think there&#8217;s, part of it is, tennis coaching is a really, you can teach people to play tennis properly very quickly. You see a lot of people, what I&#8217;m getting to is, I think there&#8217;s lots of ways to teach people well, which I think is a real interest of mine.</p>\n\n\n\n<p>You know, how you can take a subject, and simplify it down to core elements, so they get the basics and start flying very quickly. With tennis, there&#8217;s like three things you can teach any beginner, to get them playing decent tennis within half an hour, no problem. But you see a lot of coaches will overcomplicate things and people won&#8217;t have the same improvement so quickly.</p>\n\n\n\n<p>And I think that&#8217;s the real challenge in WordPress education as well. So I put a huge amount of thought into how I structure my videos in terms of, so people are going to be able to understand them, and do things more easily than just, this is this, this is this, this and this.</p>\n\n\n\n<p>So in terms of my videos, huge amount goes into the preparation of planning how to lay them out, to try and get the best possible outcome for the end user. Whilst at the same time, with YouTube, you have to make them engaging enough that they&#8217;re going to click on the thing in the first place to watch it.</p>\n\n\n\n<p>So there&#8217;s a lot. There&#8217;s kind of multidimensional, creating YouTube videos. You want to be educational, but if you just do a tutorial video, nobody&#8217;s going to potentially watch it, because it&#8217;s going to be boring as heck. So there&#8217;s multi-layers to doing YouTube education stuff.</p>\n\n\n\n<p>[00:09:23] <strong>Nathan Wrigley:</strong> But you don&#8217;t have like a traditional, I don&#8217;t know, pedagogy. You haven&#8217;t got a, like a teacher training qualification, or anything like that? You&#8217;ve just learned over time the process of creating something that is what you wish to create. And obviously, now that you&#8217;ve got this huge uptick in your subscriber count on the YouTube channel, you&#8217;ve obviously hit on some formula which is working.</p>\n\n\n\n<p>[00:09:40] <strong>Jamie Marsland:</strong> And I actually don&#8217;t think the traditional approach works on YouTube anyway. I don&#8217;t think you can take, you can try, but I don&#8217;t think if you take a traditional teaching approach, and stick it on YouTube, it&#8217;s not going to work. So I wouldn&#8217;t, you know, if I was putting a video on the Learn WordPress website, I wouldn&#8217;t put that same video on YouTube, because it&#8217;s a completely different context that people are consuming that information.</p>\n\n\n\n<p>[00:10:00] <strong>Nathan Wrigley:</strong> So back in the day when you stumbled across WordPress in the business that you were working with, you probably had no intuition that it was going to work out quite so well, in terms of WordPress&#8217;s ascendancy in the CMS market. How do you feel about that?</p>\n\n\n\n<p>We&#8217;re obviously at this pivotal point, where it feels that there&#8217;s maybe a little bit of slowdown in adoption. We keep talking about this number, this 43% of the internet. I can&#8217;t quite work out what that means, but it&#8217;s a big number. You know, it&#8217;s a giant proportion of the internet. Do you have any intuitions as to whether or not that&#8217;s going to keep going? Would it bother you in any way if it didn&#8217;t keep rising?</p>\n\n\n\n<p>[00:10:33] <strong>Jamie Marsland:</strong> A few things there, one is, when I was just starting off in WordPress, I could see it was going to fly, because it was starting to gain momentum. But I had all the same, you know, my developers were .net developers that were working for me. They were object orientated focused. They looked at PHP as some sort of dirt in the road, and they thought WordPress was terrible. So they&#8217;re very sneering about it.</p>\n\n\n\n<p>That has led a lot of the, I guess, teaching I do as well. You know, there&#8217;s a lot of, people will dismiss WordPress still, for not being, what I&#8217;m trying to say is, WordPress has never won out because it&#8217;s been the best CMS. It&#8217;s won out because of the ecosystem, and the other market drivers that were driving it. Like there were CMSs that had amazing workflows, editorial workflows, back in the day, and WordPress didn&#8217;t have any of that stuff.</p>\n\n\n\n<p>But WordPress won out because of the huge ecosystem, and the fact it was open source, and all these other drivers that were driving it. So I could sort of see that it was going to work back then.</p>\n\n\n\n<p>In terms of where we are now, it&#8217;s not so much the market size that&#8217;s important to me. There was a slide shared by Noel Tock, as part of his keynote at WordCamp Asia. It was a fascinating slide actually, and it talked about market share, which we know is about 43%, and leveling off a little bit.</p>\n\n\n\n<p>But then he overlaid that slide with search interest. So he looked at how many people were searching. And actually had a really interesting Twitter dialogue with Alex Denning about this as well. And that was basically showing how it grew in 2014, and then now its dived down quite steeply over the last, I think four years, in terms of search interest. So people aren&#8217;t searching for it so much. And then he also overlaid that with number of sites that are being built, which has also gone down a lot.</p>\n\n\n\n<p>Now that, for me, is probably the most important metric, yeah. So that has gone down significantly as well, from where we were at the peak. And then he also overlaid that with another metric, which was maturity of sector. So in terms of how many people are actually engaged in building WordPress sites, or producing WordPress products. And that was kind of still going up.</p>\n\n\n\n<p>So what we&#8217;ve potentially got here is the confluence of a declining market, which we&#8217;re not seeing quite yet. This is the kind of worst case scenario, with over suppliers. So if that is the case, if we do start to see some of that over the next few years, that&#8217;s going to cause a lot of pain to people, because we&#8217;re going to have a declining market, in terms of number sites being built. But we&#8217;ve got lots and lots of suppliers, lots of product people in that sector. So essentially not enough business for everyone.</p>\n\n\n\n<p>Who knows, that&#8217;s conjecture. But my spidey senses are telling me, this is possibly where we&#8217;re potentially at. And I think, if you look at the strategy, there&#8217;s a few other things that play into my mind for this as well. One is, I was at Cloudfest last week in Germany, and a lot of the hosting companies now are pitching towards, deliberately, strategically, pitching towards the agency developer market. That&#8217;s where they&#8217;re going. And there&#8217;s two reasons for that, potential reasons for that.</p>\n\n\n\n<p>One is, that&#8217;s where people spend the most money. The second reason for that is, they&#8217;re seeing a contraction of the DIY market, which would be my guess as well. So they&#8217;re seeing their overall market go down, in terms of revenue, my guess. But they&#8217;re seeing everyone trying to go after the agency developer market. Everyone that I speak to.</p>\n\n\n\n<p>I had a conversation with Wix this week, because I&#8217;ve had a demo of their product. They are deliberately going after the agency market as well. So I don&#8217;t think it&#8217;s just WordPress that are seeing this pinch at the moment, because I think there&#8217;s some recessional pressure on that stuff.</p>\n\n\n\n<p>But I do think it&#8217;s potentially an issue for WordPress, that we&#8217;re, it&#8217;s a question of what is the canary in the mine? And I&#8217;m seeing some of those signals. So yeah, I&#8217;ve got some trepidation of where the market is going to head over the next few years.</p>\n\n\n\n<p>[00:13:57] <strong>Nathan Wrigley:</strong> Can I plumb a little bit further into that, and ask you what the signals are, if you&#8217;re willing to share them? The signals that you&#8217;ve said that you were able to see. Just moments ago, you said that you had this, whatever the canary in the mine was. And you had a few little signals that you thought were illustrative of the general argument that you were making. Can you share those?</p>\n\n\n\n<p>[00:14:13] <strong>Jamie Marsland:</strong> Well, it was just those really. It just the fact that I&#8217;m seeing all the hosting companies that I&#8217;m talking to, because I talk to a lot of hosting companies, and we&#8217;ll probably come on to talk about wordpress.com. But everyone seems to have a strategy of going after the developer agency market.</p>\n\n\n\n<p>Everyone I speak to, that&#8217;s their strategy. Which makes sense, but it&#8217;s kind of interesting that it seems like that&#8217;s the direction of travel right now. And I don&#8217;t have insider information, in terms of the numbers for hosting companies. That&#8217;s just my view from the outside.</p>\n\n\n\n<p>[00:14:42] <strong>Nathan Wrigley:</strong> Yeah, there&#8217;s been a lot of talk recently. Well, certainly over the last three or four years, from various different quarters, all about the sort of shattering of the community. And I think it was, maybe it was Joost, the person, as opposed to Yoast the company. Or maybe it was Marieke, I can&#8217;t remember.</p>\n\n\n\n<p>But the idea that the community is sort of heading in two different directions. You&#8217;ve got this philanthropic side of the community, who pour lots and lots of their personal free time into the project, and wish it to grow in that way. And then you&#8217;ve got the other side, which is driven more by profit, and about how these two sides, in their estimation at least anyway, are getting further and further apart.</p>\n\n\n\n<p>And so they&#8217;re having to shout across this void. And the void gets further and further, so that the shouting has to be done louder and louder. The takeaway from that, I guess is that, if you&#8217;ve got a community which isn&#8217;t working, those two sides are not working in tandem, that&#8217;s also a problem I think.</p>\n\n\n\n<p>[00:15:30] <strong>Jamie Marsland:</strong> Yeah, absolutely. It was also interesting, because at Cloudfest, lots of hosting companies were there, because Joost was there actually. I was chatting to him and he was saying, actually one of the interesting things is that they need WordPress to succeed. If these like Wix, and Squarespace, and Shopify, if those guys start winning out, that&#8217;s going to affect the hosting company&#8217;s revenue as well. Because those are closed systems, that don&#8217;t host on their systems. There&#8217;s a lot at play in making WordPress work really, at the moment.</p>\n\n\n\n<p>[00:15:54] <strong>Nathan Wrigley:</strong> Yeah. He wrote a piece just the other day on the Post Status blog, all about how the hosting companies are, well, in many cases they&#8217;ve got their own onboarding system, and they&#8217;ve got their own page builder, or something adjacent to a page builder. And I think his central argument was, would it be a good idea if, rather than having these sort of rival system, so if you go with hosting company x, you&#8217;re tied in because you&#8217;ve bought into their package, and you understand their tooling and what have you. And if you go with hosting company y, you&#8217;re locked in over there.</p>\n\n\n\n<p>And I think his central argument was, we need WordPress to succeed, not the proprietary bits and pieces within your own systems. And in order to do that, would it be a good idea to spend less on your proprietary things, and put that investment back into, I don&#8217;t know, Five for the Future or something.</p>\n\n\n\n<p>[00:16:34] <strong>Jamie Marsland:</strong> Yeah, I think that&#8217;s a fair point. The onboarding of WordPress has been mooted a few times in the last few weeks as well. And it&#8217;s one of the big, when you train people, you realise there&#8217;s many hurdles of friction in terms of WordPress, which it&#8217;d be great to have solved, like domain names and hosting.</p>\n\n\n\n<p>I mean, you go to a hosting page, and that&#8217;s the first hurdle. You&#8217;re like, you get the average person and. Well, you compare the experience of setting up a website on Canva, and setting up a website through any WordPress host. And Canva, it&#8217;s five minutes and they, my cats could do it frankly, it&#8217;s so easy. Whereas WordPress, you have pricing tables with all sorts of things in, which are like object cash and, oh, what was that? Do I need some of that?</p>\n\n\n\n<p>There&#8217;s a world of difference in terms of the friction between WordPress and some of these no-code solutions out there. And I know historically, WordPress has always batted these things off. My worry is that might not last forever, I guess.</p>\n\n\n\n<p>That&#8217;s probably where it needs to be. That&#8217;s the competition. I had this conversation with the head of Influencer Marketing at Wix. They&#8217;ve got 500 people in marketing at Wix. I think they&#8217;ve got 200 on the influencer, no, that can&#8217;t be right. But they&#8217;ve signed up about 400 influencers.</p>\n\n\n\n<p>[00:17:37] <strong>Jamie Marsland:</strong> And I know we always talk about Wix, and the fact that they put huge amounts of money into marketing. But you compare that to WordPress, who historically have been development companies, with the odd marketing person appended on the side of it. And they&#8217;re really serious. They&#8217;re really serious, and they&#8217;ve got this, quite a cool product that&#8217;s aimed at agency market.</p>\n\n\n\n<p>So I do think that the opposition is lining up their ducks really well at the moment. If you were doing a competitor analysis, you look at, you know, I think Canva is a competitor to the brochure market. I&#8217;ve been saying this for a long time.</p>\n\n\n\n<p>They&#8217;ve got a website builder. If they want to, they can go after a lot of the brochure market, which is a lot of WordPress business. Wix, doing some really cool stuff with their Wix Studio stuff. It&#8217;s really slick. Obviously Shopify, going great guns. And then you compare this to WordPress at the moment. I worry how quickly WordPress can react.</p>\n\n\n\n<p>Let&#8217;s say I was watching your WP Builds chat today, and you were saying, what happens if it goes down to 40 and then 35? Let&#8217;s say, that did happen. Is WordPress match fit to react to that? And my worry is, at the moment, we are not, because we haven&#8217;t had to be.</p>\n\n\n\n<p>[00:18:43] <strong>Nathan Wrigley:</strong> Yeah, that&#8217;s a really interesting point, isn&#8217;t it? We literally haven&#8217;t had to be. It&#8217;s been growth, upon growth, upon growth, year on year. And obviously these rival platforms, Wix et al, they&#8217;ve obviously also had growth year, on year, on year. It hasn&#8217;t been of the same magnitude, but in terms of finance, and the bottom line, it has been.</p>\n\n\n\n<p>And if they can employ a sophisticated marketing team, that can put adverts, you know, in the Super Bowl and things like that, then that&#8217;s going to be a very difficult hurdle to overcome. Because if people do stop Googling for WordPress, or it just, you know, the mind share just disappears, and whenever somebody thinks about a website, that little three letter word pops out of everybody&#8217;s mouth. Oh yeah, Wix, I&#8217;ve heard of that. That&#8217;s going to be hard to compete with. And I think you&#8217;re right, interesting.</p>\n\n\n\n<p>[00:19:31] <strong>Jamie Marsland:</strong> If you compare brand searches, I mean, Canva is the big one. Canva completely dwarfs. You know, I think actually, if I was Wix, I&#8217;d be scared silly of Canva, frankly. I think Canva is such a behemoth in terms of it&#8217;s got, I think it&#8217;s got 165 million monthly users now. Generating cash, always been profitable, and people have grown up with it, people are using it. So, you know, my kids know how to build a website, because they&#8217;ve used Canva. And it&#8217;s the same interface, so there&#8217;s no learning curve. So, personally, I think Canva, if they wanted to, they could go and eat a lot of the Squarespace, and a lot of the Wix market, and a lot of the WordPress brochure market, if they wanted to.</p>\n\n\n\n<p>Canva have got an event coming up. The Canva Create event, which is titled Changing Work, or something like that. So we&#8217;ll see if they, because they have a, like a one page website builder in Canva at the moment. Pretty slick. You can only build a one page website, so it&#8217;s very limited. If they extend that, then that&#8217;s going to be a really interesting thing to see.</p>\n\n\n\n<p>[00:20:26] <strong>Nathan Wrigley:</strong> You clearly are fairly optimistic. Well, I say you are, obviously we&#8217;ve just had the conversation that we&#8217;ve just had. But, given the content that you are creating, I suppose there must be a part of you which is optimistic about WordPress&#8217;s future as well. Because your YouTube channel, and we will link to everything that we mention in the show notes, so you can check that out on the WP Tavern website. We&#8217;ll link to all of Jamie&#8217;s bits and pieces, properties and what have you.</p>\n\n\n\n<p>But you&#8217;ve been creating a YouTube channel. I don&#8217;t know quite how far that goes back. But I think it&#8217;s fair to say that, at the moment, you&#8217;ve got lots of heads turning in your direction. The subscriber count is on a fairly rapid rise. So bravo, well done for that.</p>\n\n\n\n<p>But the content, that I&#8217;ve seen at least anyway, is very much aligned with kind of Core WordPress. What can WordPress out the box do, without needing to bundle a bunch of plugins? So given that you are doing that, you must have some confidence in its capacity to challenge the likes of Wix and Squarespace, or maybe not.</p>\n\n\n\n<p>[00:21:22] <strong>Jamie Marsland:</strong> I mean it&#8217;s miles ahead of those things at the moment. It is important to say that, in terms of how many people are using it, and market share. I was just talking about where I look at it from a, if we were starting today, where we&#8217;re at in terms of just the marketing.</p>\n\n\n\n<p>I think WordPress is in a place where it needs to step up a gear, which it&#8217;s doing. And that&#8217;s partly why I&#8217;m optimistic about it. So, you know, my videos, a lot of them are like, I do some website recreations where I take a famous website, and I show you how to rebuild it using just Core WordPress.</p>\n\n\n\n<p>So I&#8217;m hugely optimistic about it. It&#8217;s got some hurdles to get over. But the core, imagine if we didn&#8217;t have Gutenberg right now. Imagine where we&#8217;d be if we didn&#8217;t have Gutenberg. I know there&#8217;s lots of people that don&#8217;t like Gutenberg, but imagine that situation.</p>\n\n\n\n<p>And actually also, interestingly, WordPress has doubled, and I&#8217;m not saying this is down to Gutenberg, but it&#8217;s doubled its market share since Gutenberg was released. So at the very least, it hasn&#8217;t harmed the growth of WordPress.</p>\n\n\n\n<p>[00:22:12] <strong>Nathan Wrigley:</strong> So the content that you are creating is around the block editor, and what have you. I&#8217;d love to get into the process of that, because your videos, and again, pause this, go and watch some of Jamie&#8217;s content. You&#8217;ll know what I&#8217;m talking about as soon as you&#8217;ve got three minutes into it.</p>\n\n\n\n<p>You obviously put a real value on quality. I&#8217;m imagining there&#8217;s quite a lot of editing and retakes, and all of that. You&#8217;ve mentioned before that you spend a long time planning everything out. Why are you doing this? What is the point of having a YouTube channel? What do you get out of it, aside from the pleasure that you may derive? What&#8217;s your north star with that project?</p>\n\n\n\n<p>[00:22:44] <strong>Jamie Marsland:</strong> Yeah, well, originally it was just to create some content that kind of countered the narrative that you couldn&#8217;t do stuff in the block editor, I think, probably. So I just started producing some content just with, I guess a slight experiment, I suppose. And then it started to get some traction and feedback, so I carried on. I just carried on.</p>\n\n\n\n<p>And it was actually a post by Chris Lema, that talked about trying to become a content machine. I think it was something like that. Which kind of inspired me to really start committing towards it. And I could just sense that there was something happening in terms of creating the content.</p>\n\n\n\n<p>And now it&#8217;s got to the point where it&#8217;s generating revenue. It&#8217;s generating more revenue than the other bits of the business, which wasn&#8217;t the plan. But then people start emailing you and saying, well, we&#8217;d like to sponsor this. We&#8217;d like to put our name to this content.</p>\n\n\n\n<p>And the last two contracts I&#8217;ve signed, in terms of the description of what it was, one had talent in quotes at the top, which is bizarre. And the other had influencer, which is really bizarre. And now that&#8217;s driving revenue. It&#8217;s driving revenue back to the product business, and it&#8217;s driving revenue back to the training business. That was not the intention of why I started it.</p>\n\n\n\n<p>[00:23:48] <strong>Nathan Wrigley:</strong> Okay, that&#8217;s really fascinating. So it was just done out of a desire to put content out there. It transformed itself into something that was getting the eyeballs. And then I presume, off the back of that, yeah, the sponsorship, emails start arriving and what have you.</p>\n\n\n\n<p>A difficult decision must have been had, or a difficult decision must have been, had to have been made at some point. How much time does Jamie put into this in the future, you know? Okay, it&#8217;s successful now. Will it continue to grow? Should I be concentrating on the business? Should I be concentrating on the videos? Yeah, I guess you&#8217;ve got to sit the family down and have that conversation.</p>\n\n\n\n<p>[00:24:21] <strong>Jamie Marsland:</strong> Well it&#8217;s a bit strange to say, you know, when you&#8217;re 50, what do you do for a living? And you have to say, I&#8217;m a YouTuber. It was hard enough to explain to my mother what I did in WordPress, and now it&#8217;s, she just looks at me blankly like I&#8217;m crazy. But I think the other thing is, I absolutely love it. So it wasn&#8217;t like I was drawn to the challenge of creating interesting creative content, and that was the prime thing that got me to create lots of video content. I absolutely love the creative process, and challenge of creating video content. So it was like, oh okay, this is maybe what I should have been doing a while back.</p>\n\n\n\n<p>[00:24:53] <strong>Nathan Wrigley:</strong> Does the sponsorship bring with it a different approach to creating content? What I mean by that is, when you were just doing the content because you enjoyed doing the content, you could put things out on any schedule, I guess. You know, miss a month, it doesn&#8217;t matter, it was just a bit of fun. But then as soon as the sponsorships start to come in, I guess you&#8217;ve got to be a bit more methodical about it, bit more timely about it, and they&#8217;re going to want a return on that investment. So has it changed your opinion of it, as a thing that you do?</p>\n\n\n\n<p>[00:25:21] <strong>Jamie Marsland:</strong> Not yet, but I&#8217;m quite early into it, so ask me maybe in a couple of years time. And I think the thing with the sponsorship, all the sponsored content I&#8217;m doing so far is stuff that I&#8217;ve pitched it to them actually, a lot of it. Even though people will email me a lot these days, and ask for sponsored content. I&#8217;ll often have ideas of an interesting piece of content, and then, because I know most people in the WordPress market now.</p>\n\n\n\n<p>And having a YouTube channel is a great way to network, by the way. So you know, for example, a good example is with the guys over at Stellar. I&#8217;ve done a few pieces with them. But I had the idea, wouldn&#8217;t it be great fun to do a piece of content which was, I think we&#8217;re going to call it, I hired an ethical hacker to break into my website and here&#8217;s what happened. You know, which is like a really interesting idea as a piece of content.</p>\n\n\n\n<p>So I&#8217;ve actually found an ethical hacker, he&#8217;s based in Malaga, and I&#8217;m going to go and see him, and that&#8217;ll be part of the video as well. The interesting thing about the sponsorship is how you take an idea and make it interesting, and compelling for people watching the content, so they still want to watch it. That&#8217;s a really creative challenge as well. But in terms of, it hasn&#8217;t changed my opinion yet, but I&#8217;m very early to the financial bit of it.</p>\n\n\n\n<p>[00:26:21] <strong>Nathan Wrigley:</strong> Well let&#8217;s hope you still maintain the enthusiasm. What does the process look like then? You mentioned that you&#8217;ve come up with some innovative titles, and you&#8217;re obviously telephoning people up, and trying to find hackers here, there, and everywhere. But what is the process, to put out a half an hour, an hour long piece of content? Just give us an insight.</p>\n\n\n\n<p>Because I think everybody has the impression that, oh, YouTube, it&#8217;s easy. There, he&#8217;s staring at the camera, he&#8217;s talking, he&#8217;s making it up as he goes along. And I&#8217;m sure it&#8217;s not like that. I&#8217;m sure there must be hours, and hours, and hours. What does it take to put out one of your videos?</p>\n\n\n\n<p>[00:26:49] <strong>Jamie Marsland:</strong> As an example, I&#8217;ve got a video coming out today with wordpress.com. It&#8217;s a five minute video and it probably took two days. That sort of magnitude. There&#8217;s like the initial idea, and then I always, always now, get the title and thumbnail sorted first. If anyone&#8217;s going to do this stuff, you&#8217;ve got to do that first with YouTube. It sounds a bit crass, but you&#8217;ve just got to do it. So get the packaging right. And I think only once you&#8217;ve got that right do you know the video&#8217;s going to fly. So that&#8217;s a really good process to go through.</p>\n\n\n\n<p>And then it&#8217;s just around, planning is everything, and the creative idea behind the flow of the video. I&#8217;ve developed a blueprint now, which I use on a lot of my videos, which is about having a hook, and then adding loops into the video, so you keep people engaged throughout the video. So it&#8217;s almost like this layer that you layer on top of a video. So when you&#8217;re seeing the video, you&#8217;re seeing somebody talk about something, but actually there&#8217;s hopefully a blueprint behind it.</p>\n\n\n\n<p>[00:27:36] <strong>Nathan Wrigley:</strong> There&#8217;s a story in there somewhere. There&#8217;s a methodology behind it all.</p>\n\n\n\n<p>[00:27:39] <strong>Jamie Marsland:</strong> That is getting natural to me now. So when I&#8217;m planning videos, I understand, I don&#8217;t have to think. When you first start doing YouTube, you have to think about everything like that, because it&#8217;s not natural. It is to some people, but it&#8217;s wasn&#8217;t to me. So you&#8217;ve got to plan it, in terms of that blueprint. How to structure it. Hook people at the start, keep them engaged throughout, plus educate them along the journey. So there&#8217;s quite a lot going on.</p>\n\n\n\n<p>[00:27:58] <strong>Nathan Wrigley:</strong> Yeah. Do you do sponsor bits inside the video? What I mean is, is the sponsorship clearly defined in the content that you do? So there&#8217;s an ad for hosting company x, or whatever it may be. And then you get back to being in the video, it&#8217;s Jamie talking to the camera and what have you. Or are you open to creating sponsored videos about particular product or company?</p>\n\n\n\n<p>[00:28:17] <strong>Jamie Marsland:</strong> So both really. So at the moment I&#8217;ve got pre-rolls that go on the front of all my videos, which is, at the moment, InstaWP are sponsoring that space. But I&#8217;ve also done videos where I do website recreation, with certain tools. So I&#8217;ve done one with Kadence and GiveWP, where I recreated the Charity Water website using their tools.</p>\n\n\n\n<p>So they give me a challenge, and I try and rebuild it using Kadence and their tools. And I did one with Spectra One as well. So that&#8217;s kind of how that works. The one I&#8217;m doing with Stellar and SolidWP will be, it&#8217;ll be sponsored by them and it&#8217;s going to be, this is the challenge, but this is what happens when we try and hack into a website without any security, this is what happens when we try and hack into a website with some security. It kind of varies in a way.</p>\n\n\n\n<p>[00:28:57] <strong>Nathan Wrigley:</strong> Okay, so you&#8217;ve got a, you can, approach Jamie if you want to make content.</p>\n\n\n\n<p>[00:29:01] <strong>Jamie Marsland:</strong> And I&#8217;ve also got, if you go to my YouTube sponsorship page, I&#8217;ve also got this series of videos going on at the moment where we give my daughters a challenge with a product. We&#8217;ve got five people lined up actually, who have signed up. And the first one we did was Kadence AI. So, can Meg and Lily build a website in 10 minutes, using Kadence AI?</p>\n\n\n\n<p>And that&#8217;s another sponsorship opportunity as well. And that&#8217;s them using the Kadence tools to try and do a task, and we just film them doing the task. And I think that&#8217;s really interesting from a content point of view, but it&#8217;s also really interesting from a product point of view. Because they&#8217;re beginners, they&#8217;re not web pros, how beginners use their plugins.</p>\n\n\n\n<p>[00:29:35] <strong>Nathan Wrigley:</strong> That&#8217;s really fascinating, and you get your family involved as well.</p>\n\n\n\n<p>[00:29:37] <strong>Jamie Marsland:</strong> Well they get the money actually with that one as well, because they&#8217;re both at universities now. I&#8217;ve got another daughter called Hetty who wants in on the action, she hasn&#8217;t done it yet. But yeah, the money goes to them to fund their accommodation at uni, which is really helpful.</p>\n\n\n\n<p>[00:29:50] <strong>Nathan Wrigley:</strong> That is so nice. That&#8217;s so great. One thing that we should mention is, of course, and you did mention it before. But you know you&#8217;re doing something right. Well, you didn&#8217;t mention this bit before, but you know you&#8217;re doing something right when people such as Matt Mullenweg drop your name in the State of the Word. And off the back of, I guess being seen by Matt, you&#8217;re now creating content, or you&#8217;re about to create content.</p>\n\n\n\n<p>[00:30:11] <strong>Jamie Marsland:</strong> Yeah, we&#8217;ve done three, fourth one going out today.</p>\n\n\n\n<p>[00:30:14] <strong>Nathan Wrigley:</strong> So this is wordpress.com. You&#8217;re making videos in that space. How&#8217;s that process going? Are you enjoying that?</p>\n\n\n\n<p>[00:30:19] <strong>Jamie Marsland:</strong> Yeah, it&#8217;s great. Basically it&#8217;s a series of videos called Build and Beyond. So I&#8217;m partnering with them for a series of videos, kind of aimed at the sort of developer agency market again, which is interesting. Because there&#8217;s lots of stuff going on in wordpress.com that people don&#8217;t know about. So it&#8217;s trying to show some of that stuff, but also just kind of speak to the broader market about the cool stuff you can do with WordPress actually.</p>\n\n\n\n<p>And obviously I&#8217;ve got resources of some amazing people in wordpress.com to lean on, in creating content. It&#8217;s kind of like a fabulous thing to happen. And obviously it&#8217;s great from my point of view, because it gets my name on wordpress.com, I&#8217;m on their blog.</p>\n\n\n\n<p>And hopefully it&#8217;s adding value to their brand, which is the idea. Part of my plan with that is to kind of shine a light on some of the cool stuff happening in WordPress, in the broader community. So hopefully a video&#8217;s going out in a few hours, which talks about some of the developers you should follow in the WordPress ecosystem. It&#8217;s trying to shine a light on the cool stuff that&#8217;s happening out there as well.</p>\n\n\n\n<p>[00:31:12] <strong>Nathan Wrigley:</strong> I don&#8217;t quite know how to phrase this question. I&#8217;ll ask it, and maybe I&#8217;ll change the wording of it. Do you think there&#8217;s something different about you. Do you think the route to success, in the way that you are doing it with WordPress content, do you think that&#8217;s something you were born with, if you know what I mean? Do you have that capacity? Were you always able to be a raconteur? Can you control the room? Have you always had the ability to talk? Do you understand kind of where I&#8217;m going? Do you believe that this is something that anybody could do with a little bit of hard work and patience, or is there something a bit special about you?</p>\n\n\n\n<p>[00:31:39] <strong>Jamie Marsland:</strong> There&#8217;s nothing special about me, but there&#8217;s definitely, a lot of my roles in, especially before Pootlepress, were being the communicator between the technical people, and the commercial people. I was that person that could take technical ideas, and then translate them to non-technical people, so they could understand from a business point of view why they were important to do. So I&#8217;ve definitely enjoyed being in that spot, taking really complex ideas, and make simple for people to understand.</p>\n\n\n\n<p>[00:32:05] <strong>Nathan Wrigley:</strong> I think it also takes a certain amount courage to push through with something like this. Because the idea of putting things out, and thinking, well, I&#8217;ve made it, people will watch it. That takes a certain level of courage I think, because it&#8217;s easy to think that people will watch it, feel great disappointment if they don&#8217;t. But in your case, it didn&#8217;t turn out that way.</p>\n\n\n\n<p>[00:32:22] <strong>Jamie Marsland:</strong> No. We have this running joke with my wife, which is, there&#8217;s three types of people in the world. People that think they&#8217;re worse than they actually are. People think they&#8217;re about right, in terms of their opinion of themself, and people that think they&#8217;re better than they actually are. My wife thinks she&#8217;s slightly worse than, she&#8217;s got far more talent than she thinks she has. I think I&#8217;m probably slightly above, which I think helps in this space.</p>\n\n\n\n<p>[00:32:44] <strong>Nathan Wrigley:</strong> I think that&#8217;s great. Thank you for joining me today, Jamie. It&#8217;s been a real pleasure. It&#8217;s been an absolute delight watching your videos, and watching your popularity grow. Let&#8217;s hope that if we were to have the same conversation in 2, 3, 4, 5 years time, it would still be on an upward spike. Let&#8217;s hope that&#8217;s the case. Jamie, thank you for joining me today.</p>\n\n\n\n<p>[00:33:02] <strong>Jamie Marsland:</strong> Thanks very much.</p>\n</div>\n\n\n\n<p>On the podcast today we have <a href=\"https://www.youtube.com/c/JamieMarsland/videos\">Jamie Marsland</a>.</p>\n\n\n\n<p>Jamie has a varied background in technical corporate leadership, and has been guiding Pootlepress for over a decade. Initially a training service, <a href=\"https://www.pootlepress.com/\">Pootlepress</a> has become a product-focused company known for its WordPress plugins. Jamie&#8217;s depth of experience in the industry is increasingly overshadowed by his visibility as a YouTuber, where, as you’ll hear, much of his attention is now focussed.</p>\n\n\n\n<p>In this episode we cover some new ground. We talk about a critical issue facing WordPress today, the fierce competition from platforms like Canva and Wix, and the marketing hurdles that WordPress must navigate to maintain its market share.</p>\n\n\n\n<p>We also explore Jamie&#8217;s unconventional path to becoming a content creator, discussing how he went from teaching tennis to teaching tech, and how he&#8217;s leveraged YouTube to grow his audience and business. His perspective is that it’s important to make technical concepts accessible and easy to understand. Making his content is a lot of work, most of which happens behind the scenes.</p>\n\n\n\n<p>We get into this a little more deeply and Jamie shares his strategies for effective video creation, from planning to execution, along with his thoughts on sponsored content and its place in the YouTube ecosystem.</p>\n\n\n\n<p>If you’re curious about the future of WordPress, content creation, or the dynamics of digital learning, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p><a href=\"https://www.pootlepress.com/\">Pootlepress</a></p>\n\n\n\n<p><a href=\"https://wordpress.org/plugins/caxton/\">Caxton</a></p>\n\n\n\n<p><a href=\"https://wordpress.org/state-of-the-word/\">State of the Word 2023</a></p>\n\n\n\n<p><a href=\"https://www.youtube.com/c/JamieMarsland/videos\">Jamie&#8217;s YouTube channel</a></p>\n\n\n\n<p><a href=\"https://asia.wordcamp.org/2024/session/the-future-of-wordpress/\">Noel Tock at WordCamp Asia</a></p>\n\n\n\n<p><a href=\"https://wptavern.com/podcast/98-marieke-van-de-rakt-on-uniting-the-wordpress-community-for-a-stronger-future\">Marieke van de Rakt on Uniting the WordPress Community for a Stronger Future</a></p>\n\n\n\n<p><a href=\"https://poststatus.com/the-future-is-open-source/\">The future is open-source</a></p>\n\n\n\n<p><a href=\"https://www.canva.com/canva-create/\">Canva Create</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 10 Apr 2024 14:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"Akismet: reCAPTCHA V2 vs V3: Key Differences (And the Best Alternative)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://akismet.com/?p=283843\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"https://akismet.com/blog/recaptcha-v2-vs-v3/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:22701:\"<p>Every website needs spam protection. If you’re part of an enterprise&#8209;level team, you know the shocking number of resources companies actually have to devote to this. Without some kind of software that helps filter out spam and bot activity, teams might spend more time dealing with fake activity than real&nbsp;visitors.</p>\n\n\n<p><a href=\"https://www.google.com/recaptcha/about/\">reCAPTCHA</a> is one of the most popular options for organizations that want to protect their websites from spam. It’s relatively easy to implement on most websites — you just need to know which version is best for your site.&nbsp;</p>\n\n\n<p>However, it can disrupt the user experience and provide less&#8209;than&#8209;perfect results. That’s why anti&#8209;spam solutions like <a href=\"https://akismet.com/features/\">Akismet</a> (which works completely in the background with AI technology) are quickly becoming the preferred option for organizations looking to streamline the UX and maximize the effectiveness of their online presence. We’ll discuss that option a bit&nbsp;later.</p>\n\n\n<p>In this guide, we’ll introduce you to reCAPTCHA and help you pick the right version for your organization’s needs. We’ll also show you to Akismet, the best reCAPTCHA alternative on the market.&nbsp;</p>\n\n\n\n<span id=\"more-283843\"></span>\n\n\n<h2 class=\"wp-block-heading\">What is&nbsp;reCAPTCHA?</h2>\n\n<p>You’re probably familiar with a CAPTCHA, even if you don’t know it by name. CAPTCHA stands for ‘Completely Automated Public Turing Test to Tell Computers and Humans&nbsp;Apart’.</p>\n\n\n<img width=\"1102\" height=\"408\" src=\"https://akismet.com/wp-content/uploads/2024/04/image.png\" alt=\"reCAPTCHA homepage with information about the tool\" class=\"wp-image-283844\" />\n\n\n\n<p>That name is a mouthful, but it describes precisely what a CAPTCHA does. It’s a system you can implement <a href=\"https://akismet.com/blog/how-to-add-wordpress-contact-form/\">alongside forms</a> to ensure that only humans can use them. Created at the turn of the 21st century, a basic CAPTCHA simply distorted letters and asked the user to identify them. The technology has continued to evolve over the years and is now known as reCAPTCHA. That’s what we’re looking at today. Google purchased this technology in 2009 and continually works to improve upon it.&nbsp;</p>\n\n\n<p>As a website admin, if there’s a submission that can’t pass a reCAPTCHA test, then you may be dealing with a&nbsp;bot.</p>\n\n\n<p>Or a human.&nbsp;</p>\n\n\n<p>Unfortunately, as reCAPTCHA has evolved to stay ahead of the ever&#8209;increasing sophistication of bots, the tests have become so complicated that, in many cases, real humans are prevented from using&nbsp;forms.</p>\n\n<p>Despite the potential drawbacks, systems like this are essential in today’s digital landscape. Any popular website deals with huge numbers of spam attacks, including unwelcome comments, <a href=\"https://akismet.com/blog/forum-spam/\">fake registrations</a>, and login&nbsp;attempts.</p>\n\n<p>Quality reCAPTCHA systems are capable of filtering out many bot submissions. You’ll still need to deal with spam, but in much smaller&nbsp;numbers.</p>\n\n<p>Though not originally invented by the organization, <a href=\"https://www.google.com/recaptcha/about/\" target=\"_blank\" rel=\"noreferrer noopener\">reCAPTCHA</a> is now a free service (with some limitations for enterprises) that Google provides, and that you can implement for any website or web application. You even get to choose between different versions, depending on the type of protection you want to&nbsp;implement.</p>\n\n\n<img width=\"1274\" height=\"546\" src=\"https://akismet.com/wp-content/uploads/2024/04/image-1.png\" alt=\"reCAPTCHA v3 vs reCAPTCHA v2\" class=\"wp-image-283846\" />\n\n\n<p>These versions offer very different experiences and reCAPTCHA implementations. In the next section, we’ll explore what those differences are, and discuss the evolution from the first version of reCAPTCHA to the current&nbsp;model.</p>\n\n<h2 class=\"wp-block-heading\">The evolution of reCAPTCHA from V1 to&nbsp;V3</h2>\n\n<p>reCAPTCHA has evolved fairly dramatically since its inception. The changes in how the reCAPTCHA system works reflect new developments in the technology used to combat bots and spam. Let’s take a look at the three major&nbsp;versions.</p>\n\n\n<h3 class=\"wp-block-heading\">reCAPTCHA V1</h3>\n\n\n<p>The first version of reCAPTCHA launched in 2007, and it displayed images with distorted textual characters. You can still see this type of CAPTCHA in many places on the web. You’re unable to copy the text, and the letters are heavily distorted to deter programs that might try to analyze the image’s&nbsp;contents.</p>\n\n\n<img width=\"760\" height=\"294\" src=\"https://akismet.com/wp-content/uploads/2024/04/image-2.png\" alt=\"CAPTCHA with instructions on entering two words\" class=\"wp-image-283847\" />\n\n\n<p>This type of CAPTCHA also fulfilled a secondary purpose. A lot of the images of text were taken from digitized books. If you resolved this type of CAPTCHA, you not only proved that you’re human, but you also helped software better recognize the language in digitized&nbsp;books.</p>\n\n<p>Overall, this is the most straightforward type of reCAPTCHA you can implement for your organization. It’s relatively easy for most people to solve (as CAPTCHAs should be). However, it’s also become outdated over&nbsp;time.</p>\n\n<p>These days, there’s plenty of software and bots that are sophisticated enough to recognize the letters that images contain. That means reCAPTCHA V1 is no longer an effective&nbsp;option.</p>\n\n\n<h3 class=\"wp-block-heading\">reCAPTCHA V2</h3>\n\n\n\n<p>reCAPTCHA V2 is where Google stepped in. They acquired the software in 2009 and launched V2 in 2014.&nbsp;</p>\n\n\n<p>This version of reCAPTCHA offered a <em>very </em>different experience from anything else on the market. Instead of having visitors solve a puzzle to prove they’re human, reCAPTCHA V2 shows a simple checkbox that says, “I am not a&nbsp;robot”.</p>\n\n\n<img width=\"948\" height=\"566\" src=\"https://akismet.com/wp-content/uploads/2024/04/image-3.png\" alt=\"reCAPTCHA with a checkbox for I am not a robot\" class=\"wp-image-283848\" />\n\n\n<p>As an end user, all you have to do is click on the checkbox. reCAPTCHA V2 analyzes the user behavior during that process, and only presents further challenges if the system suspects it’s dealing with a&nbsp;bot.</p>\n\n<p>Those subsequent challenges typically involve image recognition tasks. reCAPTCHA V2 might ask you to select all the images that contain a specific element, like vehicles or&nbsp;stairs.</p>\n\n\n<img width=\"874\" height=\"634\" src=\"https://akismet.com/wp-content/uploads/2024/04/image-4.png\" alt=\"grid of images to review\" class=\"wp-image-283849\" />\n\n\n<p>The goal of these changes was to make CAPTCHAs more user&#8209;friendly. reCAPTCHA V1 is often frustrating for visitors, since it’s easy to mistake some of the characters shown in the&nbsp;images.</p>\n\n<p>In other words, visitors often needed multiple tries to resolve a V1 reCAPTCHA. With V2, some visitors will still need to solve rote verification challenges, but most can just check a box and&nbsp;proceed.</p>\n\n\n<h3 class=\"wp-block-heading\">reCAPTCHA V3</h3>\n\n\n<p>V3 is the latest version of reCAPTCHA and the current industry standard. It launched in 2018, and it offers human verification that works entirely in the background of a&nbsp;website.</p>\n\n<p>With reCAPTCHA V3, visitors don’t need to solve any challenges or tick any verification boxes. The software analyzes user behavior and gives each visitor a score. Depending on the score, it can determine whether a visitor is a human or a&nbsp;bot.</p>\n\n<p>As the administrator, you can lower or raise the threshold for human verification with reCAPTCHA V3. The software gives you control over how strict it is, and whether it should completely block traffic it deems to be from&nbsp;bots.</p>\n\n<p>Overall, reCAPTCHA V3 is better from a user&#8209;experience standpoint. Instead of forcing visitors to interact with a CAPTCHA system or solve random challenges, V3 simply analyzes their behavior behind the scenes. A human visitor may be locked out if they are incorrectly determined to be a bot, but this should be rare (depending on your chosen&nbsp;settings).</p>\n\n<h2 class=\"wp-block-heading\">Understanding reCAPTCHA&nbsp;V2</h2>\n\n<p>These days, it doesn’t make sense to use reCAPTCHA V1, whether it’s for a small business or an enterprise&#8209;level website. That version of the software is deprecated, which means your choice will be between V2 and V3 (or a completely different&nbsp;alternative).</p>\n\n<p>reCAPTCHA V2 aims to minimize the number of visitors who need to solve challenges to prove they’re human. With V2, most visitors will only see a simple checkbox they need to tick to prove that they’re not&nbsp;bots.</p>\n\n<p>This can seem like a rudimentary approach, but it works because V2 also analyzes user behavior in the background. If it sees suspicious activity, it will also ask visitors to resolve visual&nbsp;challenges.</p>\n\n<p>In practice, only a small number of human visitors should be presented with those additional challenges. This can be a safer approach than using a CAPTCHA system that works fully in the background because it provides a second chance for humans falsely labeled as robots. Plus, it doesn’t allow the site admin to reduce the level of strictness, as is the case for&nbsp;V3.</p>\n\n\n<p>The downside of reCAPTCHA V2 is that it will inconvenience visitors in some cases. However, presenting challenges can also help to keep your organization’s website safer.&nbsp;</p>\n\n\n<p>Aside from the occasional annoyance for visitors, versions of reCAPTCHA that rely on visual challenges can present accessibility issues. reCAPTCHA offers audio versions of its challenges for visitors with visual impairments, but the system is not&nbsp;perfect.</p>\n\n\n<p>Google provides support for <a href=\"https://developers.google.com/recaptcha/docs/display\" target=\"_blank\" rel=\"noreferrer noopener\">implementing reCAPTCHA V2</a> on your website using JavaScript. It’s worth noting that while the service is free, it only supports up to one million assessments per month.&nbsp;</p>\n\n\n<p>If you do require additional assessments, you’ll need to budget for a <a href=\"https://cloud.google.com/recaptcha-enterprise/pricing\">reCAPTCHA Enterprise</a>&nbsp;plan.</p>\n\n<h2 class=\"wp-block-heading\">Understanding reCAPTCHA&nbsp;V3</h2>\n\n<p>reCAPTCHA V3 is the latest version of the CAPTCHA software. It does away with human verification challenges, and instead uses a score system that works entirely in the&nbsp;background.</p>\n\n<p>When you implement reCAPTCHA V3 to protect a form, it automatically analyzes the behavior of any user who tries to access it. The software uses an algorithm to determine if a visitor is a human or a bot, by scoring them using specific&nbsp;criteria.</p>\n\n<p>The approach of V3 is completely different from previous versions of the software. You can calibrate the scoring system for your site to decide what is an acceptable threshold for determining ‘human behavior’, and block traffic the system thinks is&nbsp;suspicious.</p>\n\n<p>This version of the software offers the most user&#8209;friendly implementation of CAPTCHA. That’s because visitors don’t need to deal with challenges or interact with any elements to prove that they’re&nbsp;human.</p>\n\n<p>The downside of this approach is that it can lead to more false negatives. No bot detection system is perfect, and without challenges, your organization might end up dealing with more spam&nbsp;submissions.</p>\n\n<p>In terms of integration, you can <a href=\"https://developers.google.com/recaptcha/docs/v3\">implement reCAPTCHA V3</a> on your website using JavaScript. The code is different from V2, and you get a lot of control over how the implementation works and how sensitive it is when it comes to scoring user&nbsp;behavior.</p>\n\n<h2 class=\"wp-block-heading\">Choosing between reCAPTCHA V2 and&nbsp;V3</h2>\n\n<p>Any organization with a significant online presence needs some sort of protection against spam and bot activity. reCAPTCHA V2 and V3 are among the most popular options because they’re relatively easy to implement, and they have generous free&nbsp;plans.</p>\n\n<p>Using V3 might seem like the logical option, since it’s the latest version of the reCAPTCHA software. In practice, though, V2 continues to be an incredibly popular version of the&nbsp;software.</p>\n\n<p>Both V2 and V3 provide comprehensive protection from spam for your website, but they do it using two different approaches. Despite being older, V2 offers a more secure experience, since it still implements a challenge system for suspicious&nbsp;visitors.</p>\n\n<p>V3, on the other hand, can be more prone to false positives/negatives. Since you can configure what the software does if it detects suspicious activity, there’s more room for potential human error during the implementation&nbsp;process.</p>\n\n<p>Overall, reCAPTCHA V2 offers a more secure experience that is ideal for sensitive forms. If you have forms dealing with sensitive user data, having the option to present challenges can help you avoid problems like fake ecommerce&nbsp;orders.</p>\n\n<p>reCAPTCHA V3 can be incredibly effective, but it prioritizes user experience over higher levels of security. This makes it a better option for less sensitive forms and user submissions, such as comments&nbsp;sections.</p>\n\n<p>You <em>can </em>configure reCAPTCHA V3 to be more strict in detecting bot activity. The downside of this approach is that it can increase the rate of false positives. If you use reCAPTCHA to block bot traffic, and it mistakes a human visitor for a fake one, they’re unlikely to be happy with the&nbsp;experience.</p>\n\n<p>Ultimately, there is no single best version of reCAPTCHA. You’ll need to consider the relative strengths and weaknesses of each one to determine which is most appropriate for your website. (There are also alternative tools you can use, which we’ll discuss&nbsp;shortly.)</p>\n\n<p>When it comes time to implement one of these systems, Google provides plenty of useful documentation for both reCAPTCHA V2 and V3. Your organization can set either one up manually, or via plugins if you use a content management system (CMS) like&nbsp;WordPress.</p>\n\n<p>Both versions of reCAPTCHA are free for up to one million validations per&nbsp;month.</p>\n\n<h2 class=\"wp-block-heading\">Exploring the alternatives to&nbsp;reCAPTCHA</h2>\n\n<p>reCAPTCHA is not the only option at your disposal. If you’re not happy with the approach that either V2 or V3 uses, then it’s smart to consider <a href=\"https://akismet.com/blog/captcha-alternatives/\">alternatives to CAPTCHA technology</a> for your spam&nbsp;protection.</p>\n\n<p>While there are a variety of anti&#8209;spam solutions available, <a href=\"https://akismet.com/features/\">Akismet</a> is the only one that rivals reCAPTCHA in terms of how easy it is to implement <em>and</em> its success rate. With Akismet, you get bot protection with 99.99%&nbsp;accuracy.</p>\n\n\n<img width=\"1243\" height=\"846\" src=\"https://akismet.com/wp-content/uploads/2024/04/image-5.png\" alt=\"stats about Akismet\'s success\" class=\"wp-image-283850\" />\n\n\n<p>More importantly, Akismet doesn’t rely on challenges to separate humans from bots. It offers a solution that works in the background to protect your website from spam, and it provides a fully free plan for personal websites and&nbsp;blogs.</p>\n\n<p>For professional websites, <a href=\"https://akismet.com/pricing/\">there’s flexible pricing</a>. Small businesses can get the protection they need via the Pro plan for just $9.95 per month (when billed yearly). For <a href=\"https://akismet.com/enterprise/\">enterprise&#8209;level spam protection</a>, organizations can get plans and pricing that’s customized around their specific&nbsp;needs.</p>\n\n<h2 class=\"wp-block-heading\">Akismet: The leader in spam&nbsp;protection</h2>\n\n<p>No matter which spam protection solution you choose for your organization, it needs to fulfill two key criteria. The first is to protect you against as much spam and bot activity as possible, with the fewest false positives along the way. The second is to protect a strong user&nbsp;experience.</p>\n\n<p>The importance of that user experience can’t be discounted. Some CAPTCHA solutions, like reCAPTCHA V2, are aggressive when it comes to presenting challenges after they detect suspicious activity. In some cases, reCAPTCHA V2 can force visitors to solve multiple challenges before giving them the green&nbsp;light.</p>\n\n<p>That aggressive approach to spam detection can keep your website safe. The downside is that it can scare visitors away because solving multiple CAPTCHAs is not an enjoyable&nbsp;experience.</p>\n\n<p><a href=\"https://akismet.com/blog/convertkit-customerstory/\">Akismet solves this problem</a> by providing behind&#8209;the&#8209;scenes detection based on machine learning. It analyzes data from real spam on over 100 million websites to provide the most accurate detection&nbsp;possible.</p>\n\n\n<img width=\"1126\" height=\"628\" src=\"https://akismet.com/wp-content/uploads/2024/04/image-6.png\" alt=\"Aksimet page with the text \" />\n\n\n<p>Akismet provides simple integration with all kinds of websites, and it’s particularly easy to implement if you’re using WordPress. Your website administrator can <a href=\"https://wordpress.org/plugins/akismet/\" target=\"_blank\" rel=\"noreferrer noopener\">install the Akismet plugin</a>, activate it, and start filtering spam right&nbsp;away.</p>\n\n\n<img width=\"1097\" height=\"508\" src=\"https://akismet.com/wp-content/uploads/2024/04/image-7.png\" alt=\"Akismet plugin listing\" class=\"wp-image-283852\" />\n\n\n<p>Although Akismet filters spam and bot activity in the background, you can also check to make sure it doesn’t flag any real submissions as spam. This is rare, but it sometimes happens, and Akismet learns from these situations to avoid flagging similar activity in the&nbsp;future.</p>\n\n<h2 class=\"wp-block-heading\">Frequently asked&nbsp;questions</h2>\n\n<p>If you still have any questions about spam protection and what solutions to consider, this section will aim to answer them. Let’s start by recapping the key elements of&nbsp;reCAPTCHA.</p>\n\n<h3 class=\"wp-block-heading\">What is&nbsp;reCAPTCHA?</h3>\n\n<p>reCAPTCHA is a CAPTCHA solution offered by Google. You can choose from reCAPTCHA V2 or V3 for your website, and implement either option using&nbsp;JavaScript.</p>\n\n<p>Both versions of the software offer unique approaches to how they protect your website from spam. You can use either version for free for up to one million validations per&nbsp;month.</p>\n\n<h3 class=\"wp-block-heading\">What is the primary goal of reCAPTCHA in website&nbsp;security?</h3>\n\n<p>The primary goal of reCAPTCHA is to stop spam form submissions. That includes spam comments, brute&#8209;force attacks through login screens, fake payment information, and other types of&nbsp;attacks.</p>\n\n<p>The software does this by helping to distinguish between real interactions on a website and bots. Different versions of reCAPTCHA use unique approaches to achieve this&nbsp;protection.</p>\n\n<h3 class=\"wp-block-heading\">How have CAPTCHA mechanisms evolved over the years, leading up to reCAPTCHA V2 and&nbsp;V3?</h3>\n\n<p>Over time, CAPTCHA mechanisms have evolved to rely less on challenges and more on behind&#8209;the&#8209;scenes analysis. With reCAPTCHA V1, visitors were forced to solve challenges to prove they were human. Whereas the newest version of the software (V3) analyzes behavior without any input required from&nbsp;visitors.</p>\n\n<h3 class=\"wp-block-heading\">Can bots still bypass reCAPTCHA systems? And if so, how do newer versions mitigate&nbsp;this?</h3>\n\n<p>CAPTCHA systems are always in a race to stay ahead of newer, stronger bots. There’s a community of malicious actors who work to bypass reCAPTCHA protections, as well as other similar systems. This is because <a href=\"https://akismet.com/blog/what-is-a-spambot/\">spambots</a> and automated attacks can be incredibly lucrative, and there’s significant interest in programs that can bypass well&#8209;known&nbsp;CAPTCHAs.</p>\n\n<p>Newer versions mitigate this risk through continued development. Any CAPTCHA solution you choose needs to get regular updates to both the core software and its spam database, in order to stay ahead of attackers. If the solution you’re using doesn’t do this, it will quickly become&nbsp;outdated.</p>\n\n<h3 class=\"wp-block-heading\">Can I use reCAPTCHA V2 and V3 simultaneously for added&nbsp;security?</h3>\n\n<p>Yes, you can use reCAPTCHA V2 and V3 on the same website to protect different pages and assets. Google includes information on how to implement both versions of reCAPTCHA in its developer&nbsp;handbook.</p>\n\n<h3 class=\"wp-block-heading\">What is the best alternative to&nbsp;reCAPTCHA?</h3>\n\n<p>Akismet offers the best alternative to reCAPTCHA for both small business websites and enterprise&#8209;level projects. You can easily implement Akismet on any type of website, but it’s particularly easy to do so if your organization uses&nbsp;WordPress.</p>\n\n<h3 class=\"wp-block-heading\">How does Akismet’s approach to spam protection differ from traditional CAPTCHA&nbsp;methods?</h3>\n\n<p>Akismet uses machine learning to analyze spam from the millions of websites that use it. This gives it access to one of the largest databases in the world for spam and bot activity, which means fewer false&nbsp;positives.</p>\n\n<p>With Akismet, visitors also don’t need to solve challenges to prove they’re human. The software can analyze their submissions and use its training to determine what’s spam and what&nbsp;isn’t.</p>\n\n<h2 class=\"wp-block-heading\">Akismet: The most trusted solution for spam&nbsp;protection</h2>\n\n\n<p>If you’re looking for the easiest solution to implement with the most accurate results and absolutely zero interference for your visitors, your best choice is Akismet. It’s blocked over 500 billion instances of spam and is used on over 100 million sites.&nbsp;</p>\n\n\n<p>reCAPTCHA offers some additional customization, but also comes with risks like false positives that lock out real users and an annoying experience that could reduce your conversions. You can integrate Akismet with any system via an open API, or take advantage of its popular, pre&#8209;built plugin for WordPress&nbsp;sites.</p>\n\n\n<p>Many website owners can use Akismet absolutely free. <a href=\"https://akismet.com/pricing/\">Explore Akismet plans</a>.&nbsp;</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 10 Apr 2024 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Jen Swisher\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Do The Woo Community: Leveraging WooCommerce for Wyrmwood Gaming with Douglas Costello\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=81053\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://dothewoo.io/leveraging-woocommerce-for-wyrmwood-gaming-with-douglas-costello/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"The Woo team and Douglas discuss Wyrmwood\'s journey, Kickstarter success, challenges of growth, and multi-channel commerce.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 10 Apr 2024 09:49:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:41:\"Donncha: Speculating on what to load next\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://odd.blog/?p=89590546\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://odd.blog/2024/04/10/speculating-on-what-to-load-next/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1974:\"<p>The <a href=\"https://wordpress.org/plugins/speculation-rules/\">Speculative Loading</a> plugin for WordPress is a plugin you should probably try out on your site, especially if you use <a href=\"https://wordpress.org/plugins/wp-super-cache/\">WP Super Cache</a> or <a href=\"https://wordpress.org/plugins/jetpack-boost/\">Jetpack Boost</a> to cache things. It uses the new speculation API that Chrome/Edge supports to load pages in the background if you even hover over a link.</p>\n\n\n\n<p>It will dynamically prefetch or prerender pages before they&#8217;re requested by the visitor on your site, which means that the page will show instantly when the visitor actually clicks the link.</p>\n\n\n\n<p>It doesn&#8217;t work in Firefox yet, but it won&#8217;t hurt either, as the browser will just ignore the extra bits and pieces added to the page.</p>\n\n\n\n<p>The default &#8220;moderate&#8221; eagerness works fine for me. The &#8220;eager&#8221; setting appeared to load links if the cursor got anywhere near them, which was a little too aggressive.</p>\n\n\n\n<p>You won&#8217;t notice your browser loading the page in the Network tab of the webdev tools, but if you <code>tail</code> your access_log, you&#8217;ll see the requests go through when you hover over the links.</p>\n\n\n\n<p>Browse around this site, or take a look at my <a href=\"https://inphotos.org\">photoblog</a> for a feel of what it does.</p>\n\n\n\n<p>There&#8217;s more info in the <a href=\"https://make.wordpress.org/core/2024/04/09/speculative-loading-in-wordpress/\">make blog post</a> about it, and this <a href=\"https://make.wordpress.org/core/2024/04/09/speculative-loading-in-wordpress/#comment-46522\">insightful comment</a> about the wastefulness of loading pages that might not be used, especially for visitors on limited data plans, or low powered devices. That&#8217;s definitely something to think about before using this plugin. I may yet remove it later, and I&#8217;ll update this post if I do.</p>\n\n\n\n<p></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 10 Apr 2024 09:43:28 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Donncha\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"Matt: Beeper &amp; Texts\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=113285\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://ma.tt/2024/04/beeper-texts/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1124:\"<p>It&#8217;s such a delight when a plan comes together and unfolds, especially when it&#8217;s something you&#8217;ve been working on for many years. Today the <a href=\"https://automattic.com/2024/04/09/automattic-acquires-beeper/\">announcement went out</a> that we&#8217;re combining the best technology from Beeper and Texts to create a great private, secure, and open source messaging client for people to have control of their communications. We&#8217;re going to use the Beeper brand, because it&#8217;s fun. This is not unlike how browsers have evolved, where solid tech and encryption on top of an open ecosystem has created untold value for humanity. <a href=\"https://blog.beeper.com/2024/04/09/beeper-is-joining-automattic/\">Eric Migicovsky has written well about the plan going forward</a>.</p>\n\n\n\n<p>A lot of people are asking about iMessage on Android&#8230; I have zero interest in fighting with Apple, I think instead it&#8217;s best to focus on messaging networks that want more engagement from power-user clients. This is an area I&#8217;m excited to work on when I return from my sabbatical next month.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 10 Apr 2024 00:00:55 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"WordPress.org blog: WordPress 6.5.2 Maintenance and Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=17195\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://wordpress.org/news/2024/04/wordpress-6-5-2-maintenance-and-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4851:\"<p><strong>Note: Due to an issue with the initial package, WordPress 6.5.1 was not released. 6.5.2 is the first minor release for WordPress 6.5.</strong></p>\n\n\n\n<p>This security and maintenance release features <a href=\"https://core.trac.wordpress.org/query?status=closed&id=!60398&milestone=6.5.2&group=status&order=priority\">2 bug fixes on Core</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/60577\">12 bug fixes for the Block Editor</a>, and 1 security fix.</p>\n\n\n\n<p><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong> Backports are also available for other major WordPress releases, 6.0 and later.</p>\n\n\n\n<p>You can <a href=\"https://wordpress.org/wordpress-6.5.2.zip\">download WordPress 6.5.2 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p>WordPress 6.5.2 is a short-cycle release. The next major release will be <a href=\"https://make.wordpress.org/core/6-6/\">version 6.6</a> and is currently planned for 16 July 2024.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p>The security team would like to thank the following people for responsibly reporting vulnerabilities, and allowing them to be fixed in this release:</p>\n\n\n\n<ul>\n<li>A cross-site scripting (XSS) vulnerability affecting the Avatar block type; reported by <a href=\"https://johnblackbourn.com/\">John Blackbourn</a> of the WordPress security team. Many thanks to <a href=\"https://twitter.com/stealthcopter\">Mat Rollings</a> for assisting with the research.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p>This release was led by <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/isabel_brison/\">Isabel Brison</a>, and <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>.</p>\n\n\n\n<p>WordPress 6.5.2 would not have been possible without the contributions of the following people. Their asynchronous coordination to deliver maintenance and security fixes into a stable release is a testament to the power and capability of the WordPress community.</p>\n\n\n\n<p class=\"is-style-wporg-props-medium\"><a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/wildworks\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/andraganescu\">Andrei Draganescu</a>, <a href=\"https://profiles.wordpress.org/artemiosans\">Artemio Morales</a>, <a href=\"https://profiles.wordpress.org/iCaleb\">Caleb Burks</a>, <a href=\"https://profiles.wordpress.org/colind\">colind</a>, <a href=\"https://profiles.wordpress.org/talldanwp\">Daniel Richards</a>, <a href=\"https://profiles.wordpress.org/ocean90\">Dominik Schilling</a>, <a href=\"https://profiles.wordpress.org/fabiankaegy\">Fabian Kägy</a>, <a href=\"https://profiles.wordpress.org/mamaduka\">George Mamadashvili</a>, <a href=\"https://profiles.wordpress.org/gziolo\">Greg Ziółkowski</a>, <a href=\"https://profiles.wordpress.org/isabel_brison\">Isabel Brison</a>, <a href=\"https://profiles.wordpress.org/audrasjb\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/joemcgill\">Joe McGill</a>, <a href=\"https://profiles.wordpress.org/johnbillion\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/thelovekesh\">Lovekesh Kumar</a>, <a href=\"https://profiles.wordpress.org/mmaattiiaass\">Matias Benedetto</a>, <a href=\"https://profiles.wordpress.org/mukesh27\">Mukesh Panchal</a>, <a href=\"https://profiles.wordpress.org/swissspidy\">Pascal Birchler</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/sean212\">Sean Fisher</a>, <a href=\"https://profiles.wordpress.org/SergeyBiryukov\">Sergey Biryukov</a>, <a href=\"https://profiles.wordpress.org/coffee2code/\">Scott Reilly</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">How to contribute</h2>\n\n\n\n<p>To get involved in WordPress core development, head over to Trac, <a href=\"https://core.trac.wordpress.org/report/6\">pick a ticket</a>, and join the conversation in the <a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">#core</a> channel. Need help? Check out the <a href=\"https://make.wordpress.org/core/handbook/\">Core Contributor Handbook</a>.</p>\n\n\n\n<p><em>Thanks to <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a>, <em><a href=\"https://profiles.wordpress.org/ehtis\">Ehtisham S.</a>,</em></em> <a href=\"https://profiles.wordpress.org/audrasjb\">Jb Audras</a>, <em>and <em><a href=\"https://profiles.wordpress.org/angelasjin/\">Angela Jin</a></em> for proofreading.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 09 Apr 2024 22:00:18 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Aaron Jorbin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"Do The Woo Community: Simplifying Crypto Payments for WooCommerce with Stijn Paumen\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=81046\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://dothewoo.io/simplifying-crypto-payments-for-woocommerce-with-stign-paumen/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:119:\"The conversation with Stijn Paumen, CEO of Helio, explores cryptocurrency, stable coins, and their impact on merchants.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 09 Apr 2024 09:02:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"Do The Woo Community: Increase Your Woo Product Sales Using Admin Demos with Vikas Singhal\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=81040\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:89:\"https://dothewoo.io/increase-your-woo-product-sales-using-admin-demos-with-vikas-singhal/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:121:\"Vikas Singhal from InstaWP shares insights on the significance of admin demos in the WordPress and WooCommerce ecosystem.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 08 Apr 2024 08:23:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:120:\"Gutenberg Times: WordPress 6.5, register Font collections, working with templates, or playground — Weekend Edition 290\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=28091\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"https://gutenbergtimes.com/wordpress-6-5-register-font-collections-working-with-templates-or-playground-weekend-edition-290/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:13157:\"<p>Howdy, </p>\n\n\n\n<p>This week, WordPress 6.5 certainly dominated the WordPress news cycle. Articles, Videos, Threads on X, and workshops are plenty available for every type of WordPress user. <a href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/\">I compiled a separate list for your perusal or to point people to wandering about</a>.</p>\n\n\n\n<p>As a reader of this newsletter, you have kept up with all the changes, for sure. &nbsp;😍 The newsletter is a little shorter today, so enjoy the rest of the weekend. </p>\n\n\n\n<p>Yours, 💕<br /><em>Birgit</em></p>\n\n\n\n<p><em>PS: I am experimenting with AI summaries, I slightly edited, mostly for brevity.  The two pieces are marked. Please reach out to me, how you think about it&#8230; </em></p>\n\n\n\n<div class=\"wp-block-group has-light-background-background-color has-background\"><div class=\"wp-block-group__inner-container is-layout-flow wp-block-group-is-layout-flow\">\n<p><strong>Table of Contents</strong></p>\n\n\n\n<ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/wordpress-6-5-register-font-collections-working-with-templates-or-playground-weekend-edition-290/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/wordpress-6-5-register-font-collections-working-with-templates-or-playground-weekend-edition-290/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/wordpress-6-5-register-font-collections-working-with-templates-or-playground-weekend-edition-290/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/wordpress-6-5-register-font-collections-working-with-templates-or-playground-weekend-edition-290/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor. </a></li></ol>\n</div></div>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p>With the release, core contributors are starting to work on WordPress 6.6. <strong>Anne McCarthy</strong> invites you to a <a href=\"https://make.wordpress.org/core/2024/04/04/hallway-hangout-lets-chat-about-whats-next-in-gutenberg/\"><strong>Hallway Hangout: Let’s chat about what’s next in Gutenberg</strong></a>. The discussion/demos will cover Dataviews, synced pattern overrides, Zoomed out view, Grid layout, Pattern styles and Style inheritance. The virtual meeting will take place on <strong>April 24 at 23:00 UTC</strong> / 7 pm EDT / 4pm PDT.</p>\n\n\n<div class=\"ngl-articles colored ngl-articles-full ngl-articles-frontend\">\n\n	\n	<div class=\"ngl-articles-wrap ngl-articles-webview\">\n	\n						\n			<div class=\"ngl-article-mobile\">\n				<div width=\"100%\" border=\"0\">\n					<div>\n						<div valign=\"top\">\n							<div class=\"ngl-article-mob-wrap\">\n							<div class=\"ngl-article-featured\"><a href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/\" target=\"_self\" rel=\"\"><img src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/04/Features-WordPress-6.5-scaled.jpeg?w=652&ssl=1\" /></a></div><div class=\"ngl-article-title\"><a href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/\" target=\"_self\" rel=\"\"><span>About WordPress 6.5 &#8211; all in one list on blocks and site editor</span></a></div><div class=\"ngl-article-excerpt\">This week, WordPress 6.5 certainly dominated the WordPress news cycle. Articles, Videos, Threads on X, and workshops are plenty available for every type of WordPress user. This list of resources&hellip; <a href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/\" class=\"ngl-article-read-more\" target=\"_self\">Read more.</a></div>							</div>\n						</div>\n					</div>\n				</div>\n			</div>\n			\n			\n			\n\n		\n		\n		</div>\n\n</div>\n\n\n<p class=\"has-accent-color has-light-background-background-color has-text-color has-background has-link-color wp-elements-b6fe42ed62408b6fe464d62777dc0282\">🎙️ Latest episode: <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-98/\">Gutenberg Changelog #98 – WordPress 6.5, Gutenberg 18.0 Community Theme Project and the Contributor Mentorship Program</a> with special guest Maggie Cabrera</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p><strong>Wes Theron</strong>, contributor to the training team, published a series of videos on  <strong>how to work with templates </strong>on YouTube </p>\n\n\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<p>In his video, <a href=\"https://www.youtube.com/watch?v=ICMir7dO9M4\"><strong>WordPress Block Themes in 250 seconds</strong></a>, <strong>Jamie Marsland</strong> provides a concise but comprehensive overview of Block Themes in WordPress. He covers the basics of how Block Themes work, demonstrates their flexibility and ease of use, and explains how they differ from traditional WordPress themes by enabling users to have more control over their site&#8217;s design without needing to write code. Jamie also gives a quick tour of the WordPress editor with a Block Theme enabled, highlighting its features and capabilities. <em>(AI, slightly edited) </em></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p>Now the Font Library is part of WordPress, Justin Tadlock&#8217;s latest tutorial is on <a href=\"https://developer.wordpress.org/news/2024/04/01/how-to-register-custom-font-collections-for-the-font-library/\"><strong>How to register custom font collections for the Font Library</strong></a> with the built-in API. &#8220;By default, WordPress ships with a single collection that lets you install fonts from the Google Fonts library. But as a developer, you can offer a more curated experience by building custom collections.&#8221; he wrote.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p>In <em>WP Jukebox</em> podcast episode titled <a href=\"https://wptavern.com/podcast/114-tammie-lister-on-the-journey-through-design-and-theming\"><strong>Tammie Lister on the Journey Through Design and Theming</strong></a>, Tammie Lister discusses with <strong>Nathan Wrigley</strong> her experiences and the evolution of her career in design and WordPress theming. The conversation sheds light on the changing landscape of WordPress design, the introduction of new technologies, and how these shifts have influenced the approach to creating engaging and effective themes. Throughout the episode, Lister offers insights into her process and reflections on the future of design in the WordPress ecosystem. <em>(AI summary slightly edited for brevity)</em> </p>\n\n\n\n<p><strong>&nbsp;<a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" target=\"_blank\" rel=\"noreferrer noopener\">&#8220;Keeping up with Gutenberg &#8211; Index 2024&#8221;</a>&nbsp;</strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. The previous years are also available: <strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a>&nbsp;|&nbsp;<a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong>&nbsp;|&nbsp;<strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong>&nbsp;|&nbsp;<strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor. </h2>\n\n\n\n<p><strong>Jeremy Holcombe</strong> wrote a tutorial on <a href=\"https://kinsta.com/blog/headless-wordpress-gutenberg/\"><strong>How to parse Gutenberg content for headless WordPress</strong></a> and explained how to parse Gutenberg content as&nbsp;HTML&nbsp;using the&nbsp;WordPress REST API&nbsp;in a&nbsp;Next.js&nbsp;static site. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><strong>Artur Piszek</strong> shared a quick tip:  <a href=\"https://piszek.com/2024/03/19/get_comment_delimited_block_content/\"><strong>Writing serialized Gutenberg blocks in PHP</strong></a> on using the <code>get_comment_delimited_block_content</code> function. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p><a href=\"https://wordpress.github.io/wordpress-playground/\"><em>WordPress Playground</em></a> is so much bigger than Blocks. It&#8217;s a fascinating, if not mind blowing tool for developers and product companies. Ronny Shani wrote an <a href=\"https://developer.wordpress.org/news/2024/04/05/introduction-to-playground-running-wordpress-in-the-browser/\"><strong>Introduction to Playground: running WordPress in the browser</strong></a>. She covers the basic some built-in features and how to create a blueprint. She also has plenty of examples and links to learn more for you.</p>\n\n\n\n<p>You can use Playground to test the <a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Gutenberg Nightly</a>. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p>In his live stream, <strong>Ryan Welcher</strong>  worked on a playground blueprint to for a live preview of his plugin Advanced Query Loop. He used various methods, to add content to a Playground site: <a href=\"https://www.youtube.com/watch?v=Bz2INc3_yAw\"><strong>Using Playground to preview plugins | Gutenberg 18.0 Review</strong></a></p>\n\n\n\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review. </p>\n\n\n\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience</p>\n\n\n\n<p><img alt=\"GitHub all releases\" src=\"https://img.shields.io/github/downloads/bph/gutenberg/total?style=for-the-badge\" /></p>\n\n\n\n<p class=\"has-text-align-center has-small-font-size\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p>Featured Image:  Elephant-cement-blocks by Pooja Derashri, <a href=\"https://wordpress.org/photos/photo/32765c4d4c/\">found on WordPress Photos</a></p>\n\n\n\n<hr class=\"wp-block-separator has-css-opacity is-style-wide\" />\n\n\n\n<p class=\"has-text-align-left\"><strong>Don&#8217;t want to miss the next Weekend Edition? </strong></p>\n\n\n<form class=\"wp-block-newsletterglue-form ngl-form ngl-portrait\" action=\"https://gutenbergtimes.com/feed/\" method=\"post\"><div class=\"ngl-form-container\"><div class=\"ngl-form-field\"><label class=\"ngl-form-label\" for=\"ngl_email\"><br />Type in your Email address to subscribe.</label><div class=\"ngl-form-input\"><input type=\"email\" class=\"ngl-form-input-text\" name=\"ngl_email\" id=\"ngl_email\" /></div></div><button type=\"submit\" class=\"ngl-form-button\">Subscribe</button><p class=\"ngl-form-text\">We hate spam, too, and won&#8217;t give your email address to anyone <br />except Mailchimp to send out our Weekend Edition</p></div><div class=\"ngl-message-overlay\"><div class=\"ngl-message-svg-wrap\"></div><div class=\"ngl-message-overlay-text\">Thanks for subscribing.</div></div><input type=\"hidden\" name=\"ngl_list_id\" id=\"ngl_list_id\" value=\"26f81bd8ae\" /><input type=\"hidden\" name=\"ngl_double_optin\" id=\"ngl_double_optin\" value=\"yes\" /></form>\n\n\n<hr class=\"wp-block-separator has-css-opacity is-style-wide\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 06 Apr 2024 11:30:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Justin Tadlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:15;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"Gutenberg Times: About WordPress 6.5 – all in one list on blocks and site editor\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=28104\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:63:\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:17381:\"<p>This week, WordPress 6.5 certainly dominated the WordPress news cycle. Articles, Videos, Threads on X, and workshops are plenty available for every type of WordPress user. </p>\n\n\n\n<p>This list of resources if for all who need to dive deeper into certain aspects or have to field questions about the new release. I didn&#8217;t aim for completeness, I might have missed past publications for sure. If I did, feel free to email a link to pauli@gutenbergtimes.com. If you are seeking information not posted here, Anne McCarthy has you covered:</p>\n\n\n\n<p>📗 <strong>Anne McCarthy</strong> published the ultimate&nbsp;<a href=\"https://nomad.blog/2024/03/13/wordpress-6-5-source-of-truth/\"><strong>WordPress 6.5 Source of&nbsp;Truth</strong></a>&nbsp;for you. In this over 10,000-word opus, you’ll find the updates tagged for each group of WordPress users. They would be relevant to end users, theme or plugin authors, developers, site admins, and enterprises. For selective reading, you could use your browser’s “Find on page” feature and search for these tags. McCarthy lists 15 priority items, with an array of 26 sub-items, and then another 23 additional items, and closes with information about items that didn’t make it into the release for one reason or another.</p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\"><a href=\"https://make.wordpress.org/core/2024/03/15/wordpress-6-5-field-guide/\">WordPress 6.5 Field Guide</a></blockquote>\n</div>\n\n\n\n<p class=\"has-light-background-background-color has-background has-large-font-size\">🎥 <strong>Bud Kraus</strong>&nbsp;invites you to the Learn WordPress Online Workshop:&nbsp;<strong><a href=\"https://www.meetup.com/learn-wordpress-online-workshops/events/299175971/\">What’s New In WordPress 6.5</a></strong>? on&nbsp;<strong>April 9, 2024, at 19:00 UTC</strong>. He’ll cover, among other features</p>\n\n\n\n<p class=\"has-light-background-background-color has-background has-large-font-size\">🎥 Also,&nbsp;<strong>April 9, 2024, at 14:00 UTC</strong>,&nbsp;<strong>Nick Diego</strong>&nbsp;and&nbsp;<strong>Damon Cook</strong>&nbsp;invite you to the next&nbsp;<a href=\"https://www.meetup.com/learn-wordpress-online-workshops/events/300032710/\"><strong>Developer Hours: Building custom blocks with the Interactivity API</strong>.&nbsp;</a><strong>Damon Cook</strong>&nbsp;from WP Engine will demonstrate how he built a form submission block that leverages the API.</p>\n\n\n\n<p class=\"has-large-font-size\"><strong>Table of Contents</strong></p>\n\n\n\n<ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/#general-information\">General Information</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/#design-tools\">Design Tools</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/#font-library\">Font Library</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/#block-bindings-api\">Block Bindings API</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/#block-hooks-api\">Block Hooks API</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/about-wordpress-6-5-all-in-one-list/#interactivity-api\">Interactivity API</a></li></ol>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"general-information\">General Information</h2>\n\n\n\n<p>🎉 <a href=\"https://wordpress.org/news/2024/04/regina/\"><strong>WordPress 6.5 “Regina”</strong></a> Official Release Post</p>\n\n\n\n<div class=\"wp-block-group has-accent-background-color has-background\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<a href=\"https://wordpress.org/news/2024/04/regina/\"><img width=\"652\" height=\"435\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/04/image.png?resize=652%2C435&ssl=1\" alt=\"\" class=\"wp-image-28113\" /></a>\n</div></div>\n\n\n\n<p>🛬 <strong><a href=\"https://wordpress.org/download/releases/6-5/\">WordPress 6.5 Landing page</a></strong> Check out the new&nbsp;WordPress 6.5 page&nbsp;to learn more about the numerous enhancements and features of this release—including short demos of highlighted features.</p>\n\n\n\n<p>📗 <strong>Leonardo Nurugha</strong>, documentation co-lead of the release, posted: <a href=\"https://www.hostinger.com/blog/wordpress-6-5\"><strong>WordPress 6.5 “Regina” Is Here – Key Features and Changes</strong></a></p>\n\n\n\n<p>📗 <strong>Carlos Daniele</strong>&nbsp;took a deep dive into the most important features for the Kinsta Blog:&nbsp;<a href=\"https://www.therepository.email/?mailpoet_router&endpoint=track&action=click&data=WyI1NTYiLCIxam9oNGRrYjZ2Zm84dzRvb293ZzRvczg4Z2swNHM0dyIsIjEwMTgiLCJkYjkzYzgwOWZlZmIiLGZhbHNlXQ\"><strong>What’s new in WordPress 6.5: Font Library, DataViews, Block Bindings, Interactivity API, and much more!</strong></a></p>\n\n\n\n<p>📗 <strong>Courtney Robertson</strong>&nbsp;published a&nbsp;<a href=\"https://www.godaddy.com/resources/news/whats-new-in-wordpress-6-5\" target=\"_blank\" rel=\"noreferrer noopener\"><strong>What’s new in WordPress 6.5</strong></a>&nbsp;walk-through and separated the updates for site builders and users from those relevant for developers.</p>\n\n\n\n<p>🧵 <strong>Rich Tabor</strong> created an <a href=\"https://twitter.com/richard_tabor/status/1775477094031741249\"><strong>18-message Twitter thread</strong></a> listing the main highlights of the release together with mini-videos. <a href=\"https://rich.blog/wordpress-6-5/\">The list</a> is also available on his blog</p>\n\n\n\n<p>📘 <strong>Matt Medeiros</strong> has some sound advice for WordPress users around 6.5 in his video <a href=\"https://www.youtube.com/watch?v=U5aYK1MPbWA\"><strong>Watch BEFORE You Update to WordPress 6.5 &#8220;Regina&#8221;</strong></a></p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<p>📽️ Learn.WordPress contributor, Wes Theron, posted a <a href=\"https://www.youtube.com/watch?v=DtJwcJF9LM8\">walk -through the WordPress 6.5 version on YouTube</a>. He covered:</p>\n\n\n\n<ul>\n<li>Improvements to the Cover block</li>\n\n\n\n<li>Renaming blocks and improved drag and drop functionality </li>\n\n\n\n<li>Box shadow support</li>\n\n\n\n<li>New powerful views in the Site Editor</li>\n\n\n\n<li>Robust revisions  </li>\n\n\n\n<li>Using the Font Library </li>\n\n\n\n<li>General UX improvements</li>\n</ul>\n\n\n\n<p>&nbsp;📽️ <strong>Jamie Marsland</strong>&nbsp;<a href=\"https://www.youtube.com/watch?v=tf8w0xMNToY\"><strong>explains WordPress 6.5 in 250 seconds</strong></a>.</p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\"><a href=\"https://make.wordpress.org/core/2024/03/09/miscellaneous-editor-changes-in-wordpress-6-5/\">Miscellaneous Editor changes in WordPress 6.5</a></blockquote>\n</div>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\"><a href=\"https://make.wordpress.org/core/2024/03/05/unification-of-the-site-and-post-editors-in-6-5/\">Unification of the site and post editors in 6.5</a></blockquote>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"design-tools\">Design Tools</h2>\n\n\n\n<p>📽️ <strong>Dave Smith</strong> published a video to show off <a href=\"https://www.youtube.com/watch?v=ySyJRYAbU_M\"><strong>these tiny link editing changes that just made WordPress 6.5 so much better</strong></a>.</p>\n\n\n\n<p>📙 <a href=\"https://developer.wordpress.org/news/2024/03/21/drop-shadow-updates-in-wordpress-6-5/\"><strong>Drop Shadow updates in WordPress 6.5</strong></a> &#8211; WordPress 6.5 brings drop shadow options to the end user. This post summarizes how to use the controls for various blocks, and how to remove core presets.</p>\n\n\n\n		\n			<div class=\"jetpack-videopress-player__wrapper\"> <div class=\"toolbelt-video-wrapper\"></div></div>\n			\n			\n		\n		\n\n\n		\n			<div class=\"jetpack-videopress-player__wrapper\"> <div class=\"toolbelt-video-wrapper\"></div></div>\n			\n			\n		\n		\n\n\n<h2 class=\"wp-block-heading\" id=\"font-library\">Font Library</h2>\n\n\n\n		\n			<div class=\"jetpack-videopress-player__wrapper\"> <div class=\"toolbelt-video-wrapper\"></div></div>\n			\n			\n		\n		\n\n\n<p>📙 <strong><a href=\"https://developer.wordpress.org/news/2024/04/01/how-to-register-custom-font-collections-for-the-font-library/\">How to register custom font collections for the Font Library</a> </strong>&#8211; WordPress 6.5 will ship with the Font Library. Learn how to use a built-in API for registering custom font collections. <em>(WordPress Developer Blog)</em></p>\n\n\n\n<p>📽️ <strong>Anne McCarthy</strong>&nbsp;posted a new video:&nbsp;<strong><a href=\"https://www.youtube.com/watch?v=Pnx_nkB-O2E\">No Code, All Fonts thanks to the Font Library in WordPress 6.5</a>.</strong>&nbsp;She wrote in the description:</p>\n\n\n\n<ul>\n<li>The Font Library operates globally, similar to the Media Library, allowing you to easily install, remove, and activate fonts across your entire site.</li>\n\n\n\n<li>Whether a font is installed by you or provided by your theme or plugin, the Font Library provides seamless selection across your editing experience.</li>\n\n\n\n<li>Google Fonts is integrated into the Font Library experience, offering various typography options and quick uploads.</li>\n\n\n\n<li>This new ability empowers you to control a foundational aspect of your site’s design without the need for coding.</li>\n\n\n\n<li>Extenders can provide their font collections and manage permissions, including turning the feature off.</li>\n</ul>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\"><a href=\"https://make.wordpress.org/core/2024/03/14/new-feature-font-library/\">New Feature: Font Library</a></blockquote>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"block-bindings-api\">Block Bindings API</h2>\n\n\n<div class=\"ngl-articles colored ngl-articles-50_50 ngl-articles-frontend\">\n\n	\n	<div class=\"ngl-articles-wrap ngl-articles-webview\">\n	\n						\n			<div class=\"ngl-article-mobile\">\n				<div width=\"100%\" border=\"0\">\n					<div>\n						<div valign=\"top\">\n							<div class=\"ngl-article-mob-wrap\">\n							<div class=\"ngl-article-featured\"><a href=\"https://gutenbergtimes.com/block-bindings-and-custom-fields-an-almost-no-code-example/\" target=\"_self\" rel=\"\"><img src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2024-02-21-at-11.06.40.png?w=652&ssl=1\" /></a></div><div class=\"ngl-article-title\"><a href=\"https://gutenbergtimes.com/block-bindings-and-custom-fields-an-almost-no-code-example/\" target=\"_self\" rel=\"\"><span>Block Bindings and Custom Fields &#8211;  an (almost) no-code example</span></a></div><div class=\"ngl-article-excerpt\">This article received two updates today, March 13, 2024: Link to second part of the Introducing Block Bindings article series. Screenshot of the visual indicator for single block With the&hellip;</div>							</div>\n						</div>\n					</div>\n				</div>\n			</div>\n			\n			\n			\n\n		\n		\n		</div>\n\n</div>\n\n\n<p>📙 <strong><a href=\"https://developer.wordpress.org/news/2024/02/20/introducing-block-bindings-part-1-connecting-custom-fields/\">Introducing Block Bindings, part 1: connecting custom fields</a> </strong>&#8211; The first tutorial in a two-part series that introduces the Block Bindings API in WordPress 6.5. Part 1 focuses on custom fields. <em>(WordPress Developer Blog)</em></p>\n\n\n\n<p>📙 <a href=\"https://developer.wordpress.org/news/2024/03/06/introducing-block-bindings-part-2-working-with-custom-binding-sources/\"><strong>Introducing Block Bindings, part 2: Working with custom binding sources</strong></a> &#8211; The second tutorial in a two-part series that introduces the Block Bindings API in WordPress 6.5. Part 2 focuses on registering and using custom binding sources.<em>(WordPress Developer Blog)</em></p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\"><a href=\"https://make.wordpress.org/core/2024/03/06/new-feature-the-block-bindings-api/\">New Feature: The Block Bindings API</a></blockquote>\n</div>\n\n\n\n<p>🗞️ <strong>Brian Coords</strong>&nbsp;reported for the WPTavern on&nbsp;<a href=\"https://wptavern.com/the-block-bindings-api-brings-dynamic-data-to-blocks\"><strong>The Block Bindings API Brings Dynamic Data to Blocks</strong></a>. “As the block editor continues to evolve its content management capabilities, the lack of support for custom fields has been one of the key roadblocks for users and developers. While custom fields in WordPress are still widely used, in the block editor they’ve been relegated to a drawer at the bottom of the screen, and haven’t been as deeply integrated as many would like. With the coming&nbsp;Block Bindings API, things are about to change in a very good way.” he wrote.</p>\n\n\n\n<p>📽️ In his latest video on YouTube, <strong>Brian Coords</strong>&nbsp;shows you how he uses&nbsp;<a href=\"https://www.youtube.com/watch?v=qD5U7TNUKTQ\"><strong>Block Variations with the Block Bindings API</strong></a>&nbsp;and how you can offer a “no-code” experience for your users with Block Variations. Coords shared&nbsp;<a href=\"https://github.com/bacoords/example-block-variation\">his code via GitHub</a></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"block-hooks-api\">Block Hooks API</h2>\n\n\n\n<p>📽️ <strong>Bernie Reiter</strong>&nbsp;and&nbsp;<strong>Nick Diego</strong>&nbsp;took participants of the Developer Hours on the journey&nbsp;<a href=\"https://www.youtube.com/watch?v=ezPHiyhhaoQ\">exploring Block Hooks in WordPress 6.5</a>. In addition to covering the basics, they looked at practical examples that you can implement in your projects.</p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<div class=\"toolbelt-video-wrapper\"></div>\n</div>\n\n\n\n<p>📙 <a href=\"https://developer.wordpress.org/news/2024/03/25/exploring-the-block-hooks-api-in-wordpress-6-5/\"><strong>Exploring the Block Hooks API in WordPress 6.5</strong></a> &#8211; The Block Hooks API is an extensibility mechanism that allows you to dynamically insert blocks into block themes. Learn how to use the API in your projects in this comprehensive overview. <em>(WordPress Developer Blog)</em></p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\"><a href=\"https://make.wordpress.org/core/2024/03/04/updates-to-block-hooks-in-6-5/\">Updates to Block Hooks in 6.5</a></blockquote>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"interactivity-api\">Interactivity API</h2>\n\n\n\n<p>🎙️ If you don’t have a lot of time, but are curious about the Interactivity API, you and listen to&nbsp;<strong>Mario Santos</strong>,&nbsp;<strong>Ryan Welcher</strong>&nbsp;and&nbsp;<strong>Josepha Haden Chomphosy</strong>&nbsp;on the 73rd episode of the<strong>&nbsp;<a href=\"https://wordpress.org/news/2024/02/episode-73-inside-the-interactivity-api\">WP Briefing discussing the Interactivity API</a></strong>. “a new foundational tool that helps developers create memorable interactive front-end experiences.” and the show notes lists a ton of resources.</p>\n\n\n\n<a href=\"https://wordpress.org/news/2024/02/episode-73-inside-the-interactivity-api\"><img width=\"652\" height=\"367\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/WPBriefingInteractivityAPI.jpeg?resize=652%2C367&ssl=1\" alt=\"Cover image of the podcast episode in Interactivity API\" class=\"wp-image-27606\" /></a>\n\n\n\n<p>🗞️ On the WPTavern site,&nbsp;<strong><a href=\"https://twitter.com/jamesgiroux\">James Giroux</a></strong>&nbsp;reported on&nbsp;<a href=\"https://wptavern.com/interactivity-api-prepares-for-its-official-debut-in-wordpress-6-5\"><strong>Interactivity API Prepares for its Official Debut in WordPress 6.5</strong></a>. “The Interactivity API and how it uses WordPress could be a pivotal moment in the Project’s history. It could create a new way of working with WordPress.&nbsp;” he wrote. And he might be right. It’s definitely exciting, and I am excited about all the tutorials and case studies that will be written in the upcoming months.</p>\n\n\n\n<p>📙 <a href=\"https://developer.wordpress.org/news/2024/02/29/an-introduction-to-block-based-mega-menus/\"><strong>An introduction to block-based mega menus</strong></a> &#8211; In this tutorial, we’ll explore how to build a Mega Menu block that integrates with the Core Navigation block using new features coming in WordPress 6.5. <em>(WordPress Developer Blog)</em></p>\n\n\n\n<div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\"><a href=\"https://make.wordpress.org/core/2024/03/04/interactivity-api-dev-note/\">Interactivity API in 6.5</a></blockquote>\n</div>\n\n\n\n<p>📗 <strong>Jonathan Bossenger</strong>&nbsp;experimented with the Interactivity API and used&nbsp;<a href=\"https://jonathanbossenger.com/2023/12/wordpress-as-a-game-development-platform/\"><strong>WordPress as a game development platform.</strong></a>&nbsp;It’s a fun game, where the logos of other web development platform chase after the WordPress logo. I lasted 25 seconds. How long did you last?</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 05 Apr 2024 15:46:32 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:16;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"Do The Woo Community: Introducing Groundbreaker, Empowering Women in Tech in Uganda\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=80862\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://dothewoo.io/introducing-groundbreaker-empowering-women-in-tech-in-uganda/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:168:\"During CloudFest 2024, BobWP met with Groundbreaker, a nonprofit empowering young women in Uganda for tech careers through scholarships. Find more on groundbreaker.org.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 05 Apr 2024 08:59:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:17;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"Do The Woo Community: Accessibility Comes to Do the Woo with Anne and Taeke\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=80839\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"https://dothewoo.io/accessibility-comes-to-do-the-woo-with-anne-and-taeke/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:231:\"Anne and Taeke discuss the expansive realm of web accessibility, covering its intersection with profitability, society, and legal compliance. They invite listener engagement and promise a diverse range of topics in future episodes.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 04 Apr 2024 08:48:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:18;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"WPTavern: #114 – Tammie Lister on the Journey Through Design and Theming\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=155234\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://wptavern.com/podcast/114-tammie-lister-on-the-journey-through-design-and-theming\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:48061:\"Transcript<div>\n<p>[00:00:00] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p>Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, design and the future of theming in WordPress.</p>\n\n\n\n<p>If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice. Or by going to WP Tavern.com forward slash feed forward slash podcast. And you can copy that URL in to most podcast players.</p>\n\n\n\n<p>If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you, and hopefully get you, or your idea, featured on the show. Head to WP Tavern.com forward slash contact forward slash jukebox, and use the form there.</p>\n\n\n\n<p>So on the podcast today, we have Tammie Lister. Tammie is a product creator focusing on WordPress. She has a hybrid background across product, design, psychology and development. She contributes to WordPress and is passionate about open source and the community. If you&#8217;ve been in the WordPress space for awhile, Tammie&#8217;s name is likely a familiar one. She&#8217;s an 18 year veteran of the project. A talented designer, developer and a key contributor to the project. Her journey has made her wear a variety of hats in both agency, life and product development.</p>\n\n\n\n<p>Today, Tammie shares insights that span from the practical, to the philosophical within the open source landscape. We get to hear Tammie&#8217;s perspective on this crucial experimentation phase in WordPress theme development. The balance she seeks between minimalist design and functional complexity, and active roles, including the default theme task force.</p>\n\n\n\n<p>Our discussion takes us into the evolving WordPress editor experience, user roles and interface design. We discussed the future of WordPress UI and UX, touching on visual configurations and how the Gutenberg site editor continues to shape our digital toolkit.</p>\n\n\n\n<p>For those inspired by themes, Tammie reveals her passion for them from preserving the essence of classic themes, to ways that the project might break new ground.</p>\n\n\n\n<p>She also introduces us to some of our own projects, such as Composition Themes and discusses her Classic to Block Themes project as well.</p>\n\n\n\n<p>Tammie shares some of the resources that she recommends for both beginners and seasoned developers alike, bringing to light the many pathways that you can now choose to learn about WordPress.</p>\n\n\n\n<p>Looking over the horizon of collaborative editing and design systems, Tammie&#8217;s excitement for what&#8217;s next is palpable.</p>\n\n\n\n<p>So, whether you&#8217;re a developer, a designer or a WordPress aficionado this episode is for you.</p>\n\n\n\n<p>If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to WP Tavern.com forward slash podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p>A quick note, before we begin, this episode was recorded live at WordCamp Asia. There was quite a lot of background noise to contend with, and I&#8217;ve done my best to make the audio as easy to listen to as possible.</p>\n\n\n\n<p>And so without further delay, I bring you Tammie Lister.</p>\n\n\n\n<p>I am joined on the podcast by Tammie Lister. Hello Tammie.</p>\n\n\n\n<p>[00:03:44] <strong>Tammie Lister:</strong> Hello. How are you?</p>\n\n\n\n<p>[00:03:45] <strong>Nathan Wrigley:</strong> Yeah, good. Thank you for joining me today. We are at WordCamp Asia. I actually don&#8217;t know the name of the venue, but we are at WordCamp Asia. And Tammie&#8217;s giving us a presentation during the event. But before she tells us about that, just give us a little bit of a background. Give us your potted biography. Tell us who you are, where you&#8217;ve been, whatever you like.</p>\n\n\n\n<p>[00:04:04] <strong>Tammie Lister:</strong> Ah, yeah. So my name is Tammie Lister. I have been involved in project, oh, I think 18 years or so now, a little while. I have been pretty much, designer, developer, worn most hats around the project. I&#8217;ve been a full-time contributor, I&#8217;ve worked on phase one of Gutenberg, and I&#8217;ve also worked in agencies. And currently, I am working a kind of hybrid function, working with products, and also doing some sponsored contribution.</p>\n\n\n\n<p>[00:04:32] <strong>Nathan Wrigley:</strong> You&#8217;ve been around the houses, haven&#8217;t you, basically? You&#8217;ve been there, done that. What&#8217;s your talk about? It&#8217;s called The Elements of WordPress, but I&#8217;ve got it written down in front of me, so I know what it&#8217;s about. But you want to, just for the sake of the audience, maybe somebody listening to this will be able to watch it on WordPress TV. Tell us what you&#8217;re intending to say.</p>\n\n\n\n<p>[00:04:48] <strong>Tammie Lister:</strong> Yeah. So my talk is specifically looking at the elements of WordPress, going up from blocks, to patterns, to template parts, to templates, and then styling. And looking at how they all come together. So everything on the front end of the site, but also the hidden design system as well.</p>\n\n\n\n<p>[00:05:03] <strong>Nathan Wrigley:</strong> So that&#8217;s the talk. You haven&#8217;t done it yet, have you?</p>\n\n\n\n<p>[00:05:06] <strong>Tammie Lister:</strong> Yes.</p>\n\n\n\n<p>[00:05:06] <strong>Nathan Wrigley:</strong> You have. And how did it go?</p>\n\n\n\n<p>[00:05:08] <strong>Tammie Lister:</strong> It went really well. I was really pleased to be able to deliver it and, as of all these talks, I think it&#8217;s a good idea to kind of deliver it. I always like writing blog posts, so I&#8217;m hoping to write a blog post about it, and then iterate on it. And some of the conversations are really interesting afterwards as well.</p>\n\n\n\n<p>[00:05:22] <strong>Nathan Wrigley:</strong> Yeah. A little bit off piste, but how do you manage the nerves for things like that?</p>\n\n\n\n<p>[00:05:26] <strong>Tammie Lister:</strong> I am atrocious with nerves. I am not one of those people that ever doesn&#8217;t have nerves. I would probably worry if I didn&#8217;t have nerves.</p>\n\n\n\n<p>[00:05:33] <strong>Nathan Wrigley:</strong> Well, it&#8217;s something that I couldn&#8217;t do, so bravo. Thank you for doing that. So I&#8217;ve got a list of questions here, and I&#8217;ll go through them, and we&#8217;ll tackle them one at a time. So my first question to you, and because I know of the history that you&#8217;ve had, this question seems like on message, but we&#8217;ll see.</p>\n\n\n\n<p>I&#8217;ve written down, over the last 10 years let&#8217;s say, WordPress, well, let&#8217;s maybe go for 5 years. WordPress has changed a lot. Tell us what you make of everything that&#8217;s happened since your involvement, you know, phase one, and all of that. What sticks out as the most important moments?</p>\n\n\n\n<p>[00:06:02] <strong>Tammie Lister:</strong> The word at the moment that I&#8217;m focusing on is patterns. I love patterns because they, and I kind of said this in my talk, because when people think of a site, they don&#8217;t think of blocks, they think of patterns. If you shut your eyes and you think of a site. So that, to me, is really significant because it&#8217;s starting to deal with the science and deal with the interface as people see it.</p>\n\n\n\n<p>A lot of the work that we&#8217;ve done, is dealing with it as people see it, because a lot of phase one, and a lot of all that work was foundational. I kind of use the term iceberg. And it was all that kind of groundwork, or that big foundational pieces. And you don&#8217;t see that, and you don&#8217;t recognise that.</p>\n\n\n\n<p>The work now is refinements on top of that, and it can seem bigger, but it&#8217;s making all of that hidden work visible. So I really like that. I like it when something that I made is changed, I get great delight in that. I like it when the language is firmed, both visually and also that we start having solid names for things, and the name stick, rather than the names changing.</p>\n\n\n\n<p>[00:07:03] <strong>Nathan Wrigley:</strong> We&#8217;ve had a a lot of changing of names, haven&#8217;t we?</p>\n\n\n\n<p>[00:07:05] <strong>Tammie Lister:</strong> Yeah. I really like that we are using proper things, so we&#8217;ll get examples, reusable blocks, and then patterns, and syncing, and all those kind of things. That we&#8217;re also making things in response to how they&#8217;re being used, is really important as well.</p>\n\n\n\n<p>Initially, you&#8217;re going to make the best bet that you can be. So phase one was very much a, well, we know we need the editor, we know we need this, the block kind of needs it, this is how an editor kind of should work, rough bet, you know, throw something.</p>\n\n\n\n<p>But then you only know when people are using it how to refine it. And then, even more so when site editor, the site editor and block editor are very different. So all of that kind of information refines and changes it as well.</p>\n\n\n\n<p>[00:07:44] <strong>Nathan Wrigley:</strong> You mentioned an iceberg, and whilst I don&#8217;t want to sort of open up Pandora&#8217;s box a little bit, how well do you feel the whole of the Gutenberg project, from phase one, was communicated? Because it feels, right now, 2024, it feels like a lot of things are beginning to land, and are beginning to be understood. I&#8217;ve got the intuition that, for the last five years or so there was, just maybe the communication wasn&#8217;t what it could have been, or something like that. So it was difficult for people to understand, and that leads to all sorts of interesting conversations.</p>\n\n\n\n<p>[00:08:13] <strong>Tammie Lister:</strong> I think communication is a conversation, and conversations need to happen between two, both ways. That&#8217;s where I come back to. I think everyone has learned in this, you know, we didn&#8217;t even really have a concept of developer relations. You know, we were asking the people who were building it to do developer relations, who weren&#8217;t doing developer relations, who didn&#8217;t know how to do developer relations, right? Or we were asking people to build it, whilst also advocating for it.</p>\n\n\n\n<p>You know, all these kind of different things. And we&#8217;ve learned over time, and how to do an awful lot in this project. And we&#8217;ve had to learn a lot of, we have things like hallway hangouts, now and we have all these amazing, like the developer blog, and we have all these amazing resources that we didn&#8217;t have in phase one.</p>\n\n\n\n<p>We had, just had some like user feedback sessions, and we didn&#8217;t have the FSE program, the outreach. That kind of didn&#8217;t happen, that started happening later. We didn&#8217;t have specific people who were specifically focused on things. That was the people who were building it as well.</p>\n\n\n\n<p>So I think we&#8217;ve learned from having those conversations and refining it. But also, it&#8217;s really hard to communicate what you don&#8217;t know yet, whilst you are learning how to do it. So if you&#8217;re like, I need to experiment and I need to explore this thing, but you need to give me time to experiment and explore this thing, that&#8217;s a completely different conversation.</p>\n\n\n\n<p>[00:09:31] <strong>Nathan Wrigley:</strong> Yeah, I was having, a chat with somebody yesterday, and sort of explaining that if WordPress was a, I don&#8217;t know, a blue chip company, and it was a for-profit entity, and you had a hierarchy with the CEO at the top, you could communicate everything down with just a memo. But the nature of the WordPress project, given that there&#8217;s loads of volunteer hours, and contributor hours, and people are in different time zones, I think that&#8217;s a really difficult thing to manage.</p>\n\n\n\n<p>[00:09:51] <strong>Tammie Lister:</strong> Well you couldn&#8217;t say like, hey, can everyone just go into experimentation mode for like four years, and just everyone not judge anything that&#8217;s going to be produced. That&#8217;s a whole different conversation. And then who&#8217;s going to get the memo that we&#8217;re actually all in experimentation. And then if Bob in the corner, and then Mary in the other corner doesn&#8217;t get that memo, they&#8217;re going to be judging something. Bob and Mary are super awesome people, but they&#8217;re not going to have that knowledge to make those judgements on different things.</p>\n\n\n\n<p>[00:10:15] <strong>Nathan Wrigley:</strong> Yeah. I have no intuition as to whether anything&#8217;s changed in the background, but it sounds, from everything that you&#8217;ve said and the messaging that I&#8217;m receiving, that that message has been understood, in the places where it needs to be understood. That getting the message out, getting buy-in from people who are using it, communicating it, setting up things like the FSE program as you mentioned, and the Learn WordPress, and the mentor sponsorship.</p>\n\n\n\n<p>[00:10:37] <strong>Tammie Lister:</strong> It&#8217;s maturing of the project as well, and maturing of concepts and learning, like we all learn. I think that&#8217;s one of the things in the open source projects, you learn by doing. And it&#8217;s as safe a place as you can have as any to learn from, and as gentle a place.</p>\n\n\n\n<p>But we all need to be very gentle with allowing that learning, and just give that consideration of, we&#8217;re all learning together, we&#8217;re all reflecting on what we do. That ability to experiment, if we can kind of replicate that and keep that, I think that&#8217;s going to serve us well in the future as well.</p>\n\n\n\n<p>[00:11:10] <strong>Nathan Wrigley:</strong> I haven&#8217;t been in the WordPress ecosystem since day one, probably more like 12 years or something like that. So long enough to know a bit, but not long enough to know everything. But it does feel like when phase one began, that was probably the moment where WordPress changed beyond all recognition, in a way that it had never done before. So there may was no need to communicate on such a deep level.</p>\n\n\n\n<p>[00:11:33] <strong>Tammie Lister:</strong> I think there&#8217;s always been pivotal changes. They&#8217;ve just sometimes not, if it&#8217;s not impacting your area, impacted so many areas, I think if it impacts your area, it may have impacted a smaller area, so it would&#8217;ve felt huge in that smaller area, to that group of people.</p>\n\n\n\n<p>Because it impacted so many people, it&#8217;s the editor, right? The editor is where you go to write things. You want to impact a big area of WordPress, impact the editor. It&#8217;s pretty much impacting the heart, right? In a beautiful way.</p>\n\n\n\n<p>It really is important to think about, there&#8217;s been, you know, from plugins, to themes, to different things. There&#8217;s been so many areas that have had pivotal changes from day one that, I&#8217;m sure different people would have this on this day, and this time. This was this change that shook me, right? And I can think of many little kerfuffles, that kind of people would&#8217;ve felt, or little blips that people felt.</p>\n\n\n\n<p>But we kind of have learned along the way to have those, and learn from those. And each one you learn from, and each one as a community. I think one of the big things to do is think, okay, how do we then progress? How do we then take those learnings? How do we then get better? And I do think we have some strong learnings from this project.</p>\n\n\n\n<p>[00:12:49] <strong>Nathan Wrigley:</strong> Yeah. I also feel the footprint is important, because back 12 years ago, let&#8217;s just use that number. I don&#8217;t know what the percentage was, but it wasn&#8217;t 43 that this number, this percentage of the internet&#8217;s being used. So obviously the impact.</p>\n\n\n\n<p>[00:13:00] <strong>Tammie Lister:</strong> The footprint and the businesses that are established on it, and the livelihoods, and the families, and the people that depend on it, you know? And the children, and the partners, and there&#8217;s passion, and there&#8217;s the depth and the roots, and the people that have been on it for decades, or whatever. That leaves a lot of change. You know, trying to change things when someone has been very used to something for 15, whatever years, is quite a change.</p>\n\n\n\n<p>[00:13:26] <strong>Nathan Wrigley:</strong> How confusing do you think the editing experience is at the moment? So I&#8217;m in WordPress all the time, I have this subset of things that I need to achieve. And so for me to do that is really straightforward, because I&#8217;ve spent the time to understand the things that I need to do.</p>\n\n\n\n<p>But if I was somebody brand new coming to WordPress, what&#8217;s your intuition about how finished it is as an editing experience? Do you think we&#8217;ve got a way to go? Are you happy? Of anybody that I&#8217;ve met, you&#8217;ve probably put as much thought into this as anybody. And so I&#8217;m just curious what you think.</p>\n\n\n\n<p>[00:13:57] <strong>Tammie Lister:</strong> So I don&#8217;t think it&#8217;s baked yet, seeing it as a cake, because I think it&#8217;s getting there. One of the things with core is it&#8217;s always going to be the middle ground. And I think we often forget that when we&#8217;re looking at the interface, or we&#8217;re looking at the product, that it&#8217;s the middle that it&#8217;s going for.</p>\n\n\n\n<p>And I would always encourage people to think about how, yes, you can use it out of the box, you can use the middle, but maybe, what do you want to turn on or off? There are options that you can turn, settings as well. I would like to have more configurations to be able to be done, so that you can have less or more, depending on that.</p>\n\n\n\n<p>One of the big things from an agency perspective, is more control from user locking, and user roles, and user capacities. I&#8217;m also probably a big critic as well. I think those people that have been involved in the project, are probably way more critical than those who are outside.</p>\n\n\n\n<p>I always find that interesting. Like, you&#8217;re always going to be more critical of the things that you&#8217;ve ever touched, than anyone else&#8217;s going to be critical. If you know how the cake&#8217;s made, you&#8217;re going to be more critical about the cake.</p>\n\n\n\n<p>I think, for me, I have a personal taste, and then I have a work taste. And so I can share both of those. My personal taste is super minimal, so I would actually like to see, how less distilled can it be. But I also know, for most jobs to be done, that&#8217;s also not going to be the case at all. So I don&#8217;t want to see that to be the default of the interface.</p>\n\n\n\n<p>What I maybe want from a design perspective is absolutely not what should be the default case. And that is always the challenge as a creator of interfaces. But I would definitely like to see different types. I would like to see more visual configuration of that. And I would like to see the ability to, just be able to change the experience a lot more, and style it.</p>\n\n\n\n<p>[00:15:37] <strong>Nathan Wrigley:</strong> Do you feel that the project is heading in the right direction with the UI, the UX that we&#8217;ve got at the moment? Where patterns seem to be taking a bit more of a leading role, and also we&#8217;ve got FSE. I mean, goodness me, we could spend, honestly we could do two hours on FSE. But, is this the direction you want to see it go in? Some like really visual way of just, okay, I want to put that little pattern in that row.</p>\n\n\n\n<p>[00:15:57] <strong>Tammie Lister:</strong> So I love using the site editor&#8217;s Dreamweaver. And I go back, like super dates me. But it is right. Like, for me, that&#8217;s how I make themes now. I love Figma, but Figma, I really use, I don&#8217;t know if you know the concept of style tiles, which is basically just like, you pick your colors, you pick your fonts, and then you just make a little tile basically.</p>\n\n\n\n<p>That&#8217;s kind of what I do. And then I put that into a theme json, and then I load it up, using create block theme, the plugin. I always get those words muddled round. And then I go straight into the editor, and then I start mixing stuff around, and I make my patterns, and I do export. So I&#8217;m basically using it like Dreamweaver, that&#8217;s what I&#8217;m doing, because I find it incredibly effective.</p>\n\n\n\n<p>I strongly recommend people do that, because you are then in it and, would you release it like that? No, probably not, because then you don&#8217;t get translatable, all of those things. But I find it a really effective tool, and it&#8217;s become not just a way to do it, it&#8217;s a way to create. It&#8217;s almost like a coding tool that way.</p>\n\n\n\n<p>Patterns being central, I think is way more important. We do put too much emphasis on blocks, because patterns to me are way more important. One of the things I want with patterns is, I want pattern variations. I really would love to see that.</p>\n\n\n\n<p>[00:17:08] <strong>Nathan Wrigley:</strong> Just tell us more about that, because I think that could easily get missed.</p>\n\n\n\n<p>[00:17:11] <strong>Tammie Lister:</strong> Yeah, so as we have, you know, we have block styles or pattern styles, maybe we call it. Being able to attach different styling to different patterns that you can change. I don&#8217;t know how that happens, but I think that that would be really nice, to be able to switch that in the interface somehow. No idea how that happens.</p>\n\n\n\n<p>The other thing I would love is easier sharing styling. In fact, I&#8217;ve had a couple of conversations at this WordCamp of people just being like, I just want to port. People are going back to CSS Zen Garden. It&#8217;s got a place in everyone&#8217;s heart, right? And what if, bear with me, I&#8217;ve had more than one person say this to me in the past couple of days. What if you could go on the site, and you could grab a load of code, and no matter what theme you had, you could put it in, and then your site would look like that.</p>\n\n\n\n<p>[00:17:56] <strong>Nathan Wrigley:</strong> Neat. Neat. Really neat.</p>\n\n\n\n<p>[00:17:59] <strong>Tammie Lister:</strong> That is kind of what we want. And if it&#8217;s just styling, I mean, it&#8217;s going to be more or less, right? Because of the patterns and everything. But if you are grabbing that and getting the styles, that&#8217;s kind of where we probably should be heading, I think, personally. Very opinions on my own.</p>\n\n\n\n<p>But for me, that&#8217;s true independence of styling. And that&#8217;s what I really want, because I love ephemeral styling. That creative freedom. I think it opens up, not just to developers. It allows front end developers to really polish their fine art. They can boost their skills. They can do even more CSS on top of it, if they want to.</p>\n\n\n\n<p>And they can do even more amazing animation. It opens all these things up to more designers to be able to do it without having to know to code. So at both ends, more capable as well. So it doesn&#8217;t limit anyone.</p>\n\n\n\n<p>[00:18:48] <strong>Nathan Wrigley:</strong> Some of the steps that you mentioned, I don&#8217;t exactly know the level of every listener to this podcast, but some of them will be very technical, and would&#8217;ve understood everything that you&#8217;ve said. But then you may have said something like theme json, and then some people are glazing over and thinking, what? What&#8217;s your intuition as to where being able to create themes and patterns, what level of expertise would you ideally like to see that? Would it be ideal to allow anybody?</p>\n\n\n\n<p>[00:19:12] <strong>Tammie Lister:</strong> I would literally love you to be able to, you know, the Pattern Directory, or the Museum of Block Art. Maybe we can literal just go, pattern directory. I would love a style directory. Where you could literally go and grab a style, grab it, and then you can put it.</p>\n\n\n\n<p>[00:19:23] <strong>Nathan Wrigley:</strong> So no knowledge required, you just need to be able to just go through the directory, copy and paste.</p>\n\n\n\n<p>[00:19:27] <strong>Tammie Lister:</strong> I would love that. WordPress Zen Garden.</p>\n\n\n\n<p>[00:19:30] <strong>Nathan Wrigley:</strong> Yeah, Zen Garden takes me right back.</p>\n\n\n\n<p>[00:19:32] <strong>Tammie Lister:</strong> WordPress Zengarden. How amazing would that be, right?</p>\n\n\n\n<p>[00:19:34] <strong>Nathan Wrigley:</strong> But I guess even that step for some people, I know it seems almost ridiculous on a WordPress podcast, to say even that step might be a of a leap.</p>\n\n\n\n<p>[00:19:41] <strong>Tammie Lister:</strong> But if you had it in the interface.</p>\n\n\n\n<p>[00:19:43] <strong>Nathan Wrigley:</strong> In the interface. Okay, so it&#8217;s not like a separate Zen Garden site.</p>\n\n\n\n<p>[00:19:46] <strong>Tammie Lister:</strong> The pattern directory is in the interface. So if you had the style interface in there somehow, and you could browse it, and you could be like, I want a whatever. I have this rather peculiar analogy I&#8217;m going to share for theming, which is, at the moment, themeing should be super easy to change. But at the moment, changing a theme is like removing your head, rather than changing your clothes. Changing your jumpers should be easy, right?</p>\n\n\n\n<p>And it should just be super simple to change styling. And themes are great and amazing, but they&#8217;re a package, that&#8217;s what they are. And we need to just go back to having that beautiful freedom. And then we can have these creative freedoms.</p>\n\n\n\n<p>Themes to me are, we talk about design. Design and art are very, very different. But art is where meets WordPress in theming, to me. And art is part of my background. And there is potential for us to have some beautiful art in themes again. If we just have that freedom, and we stop themes having to have all this weight in them as well, and be tied down.</p>\n\n\n\n<p>[00:20:47] <strong>Nathan Wrigley:</strong> I get the feeling that an ideal place for you to land with this would be that, most people can do most of what they need to do when they want to style their own website. But there&#8217;s always still going to be an area for a professional.</p>\n\n\n\n<p>[00:20:59] <strong>Tammie Lister:</strong> If you think of it like fashion, is good example. So you can go and have custom fashion, you can go and have high-end, haute couture. You can always go and have custom tailoring. You can go and have all of that. Or you can go to high street, and go get something off the rack. And I think that&#8217;s a really good model for us to kind of think of it as well, right?</p>\n\n\n\n<p>[00:21:16] <strong>Nathan Wrigley:</strong> Nobody&#8217;s used that on me before. That actually sums it up perfectly. That&#8217;s nice, yeah.</p>\n\n\n\n<p>[00:21:20] <strong>Tammie Lister:</strong> Yeah. And that isn&#8217;t belittling anything. That&#8217;s totally fine, you know. And that still allows us to have theme shops, fashion shops, right? That still allows us to have very functional, you know, we have very functional clothing, we have functional themes as well.</p>\n\n\n\n<p>And I think it&#8217;s really important to think about the site works, the site has to do something. Some fashion is very frivolous. Some themes are going to be incredibly frivolous as well. And I actually adore frivolous themes. I don&#8217;t think we have enough of them.</p>\n\n\n\n<p>But some are going to have to just be functional, and jobs to be done as well, because absolutely. And some are going to be frameworks, and some are going to be whatevers, you know. But it&#8217;s having those options. You know, you&#8217;re looking at high street, you have the options to be able to wear different clothing as well.</p>\n\n\n\n<p>And some people are going to be super dependent on a brand, and super passionate about only wearing that brand as well, you know, all those kind of things.</p>\n\n\n\n<p>[00:22:13] <strong>Nathan Wrigley:</strong> So you can peel back the curtain a little bit on this, because of your experience inside the project, trying to drive this change. How does it happen? Are there certain people that we should be, you know, if we&#8217;re strongly into themes, and we&#8217;re opinionated about that, and we want to make the change, where do we go? Do we start talking directly to people like you? Are there other people that we need to be banging on the door and saying, this is what we want?</p>\n\n\n\n<p>[00:22:36] <strong>Tammie Lister:</strong> So I&#8217;m not a full-time contributor, so I&#8217;m just like anybody else in that sense. I mean, I have the knowledge, I&#8217;ve been in the project, but there&#8217;s many people who&#8217;ve been in the project and have that knowledge.</p>\n\n\n\n<p>My biggest thing is use the things, start experimenting, start creating if you can. And I&#8217;m well aware, I&#8217;m suggesting that most people have a time machine to do that, because you are trying to do your job as well as you&#8217;re doing that. But if you can, in your projects, start using them. As you start using new things, you&#8217;re going to find bugs, because the universe.</p>\n\n\n\n<p>And then you can start reporting those issues, and then you can start saying, these things need to change, when you&#8217;re changing classic themes to block themes, that&#8217;s one of the big things at the moment. So you can help with those things.</p>\n\n\n\n<p>And just find the area that you want to help with. Reporting one issue, which is a few minutes, is an incredibly big help. Having one conversation is incredibly helpful. Watching one hallway hangout, which is an hour, is a big help. Watching a video, going to a talk. But then scaling it up, going to a triage session.</p>\n\n\n\n<p>It&#8217;s really finding where you are. Experiment, have a pattern in the Museum of Block Art. Have a pattern in the Pattern Directory. Find where you want to join in. But by using these things, you start to contribute, is the biggest thing, because you start then knowing how they fit.</p>\n\n\n\n<p>To dive in straight away and say, these things should be this way, without having used them in their current state, is a little bit, you might not be knowing how they are utilised. I would also always encourage people to search to see that something&#8217;s not coming up. So if you&#8217;re going to log something as an issue, just have a little quick search, and see whether it&#8217;s coming up to be fixed, before you log it in the GitHub repo. That&#8217;s always a really good kind of tip as well.</p>\n\n\n\n<p>There&#8217;s the channels in Slack, but Slack can also be quite a lot for a lot of people. So just, yeah, just using it, and just figure out where your happy is. But just start experimenting and using is the biggest one.</p>\n\n\n\n<p>[00:24:33] <strong>Nathan Wrigley:</strong> Yeah, joining in, we could probably sum it up, couldn&#8217;t we? That&#8217;s nice. Where would you go? There was a nice little segue there, because you were talking about ways to learn, and you mentioned a couple of things.</p>\n\n\n\n<p>But, where do you find to be the best places to send somebody who&#8217;s, well, let&#8217;s just say a novice? Let&#8217;s go with that. Where are the online resources, the places to hang out?</p>\n\n\n\n<p>[00:24:51] <strong>Tammie Lister:</strong> So there&#8217;s a couple of different ones. We are very lucky, we have a developer blog now, which is incredible good resources. But all the Hallway Hangouts, amazing to watch back. Learn WordPress is also a really good resource. And between all of those, you&#8217;ve just got your good start then.</p>\n\n\n\n<p>And then there&#8217;s quite a few people in between those that start doing. So Ryan has been doing some through develop blog, has also been doing some live streams. So just doing things like that.</p>\n\n\n\n<p>The problem with a lot of these things are, maybe a live stream is like an hour watching. That might be quite a lot of time for you. So that&#8217;s why maybe following like a quick little tutorial, that maybe has a GitHub repo that you can do quickly. Again it&#8217;s, how much time have you got?</p>\n\n\n\n<p>I find pointing people to the Museum of Block Art&#8217;s quite good, because they can just go there, they can see the code, they can drop it in. And then they can learn, oh, this is what a pattern is. And some of those are quite fun. Or go to the Pattern Directory, and then they can be like, oh okay, well, this is what a pattern is, and this is how it forms. Yeah, so those kind of things as well.</p>\n\n\n\n<p>WordPress.tv is also really, really good, because, if you&#8217;ve got some time, type in whatever you want to follow, and just start learning that way. You can learn some really diverse things that way. Following along some State of the Words, the kind of pivotal points, you are going to find out the points of the project that way as well, is a good milestone as well.</p>\n\n\n\n<p>[00:26:11] <strong>Nathan Wrigley:</strong> I will make sure that there is a link to everything that Tammie just said. So if you go to wptavern.com/podcast, and you search for Tammie&#8217;s episode and you find it, there will be all of the links in there.</p>\n\n\n\n<p>Lets pivot a little bit. It&#8217;s not apropos of themes at all but, what do you think about this current phase that we&#8217;re in of Gutenberg? Which is called phase three. But the highlight item for me, I mean there&#8217;s absolutely loads to be honest, but I&#8217;m just going to talk about collaborative editing. What do you make about that? And especially related to themes and sites more generally, not just the content, but editing collaboratively, just the way the whole site looks, so the theme.</p>\n\n\n\n<p>[00:26:47] <strong>Tammie Lister:</strong> I think it hasn&#8217;t been worked out yet, how it&#8217;s going to work on the theme. I don&#8217;t know if it means you are creating the theme collaboratively.</p>\n\n\n\n<p>[00:26:54] <strong>Nathan Wrigley:</strong> It&#8217;s to imagine actually.</p>\n\n\n\n<p>[00:26:56] <strong>Tammie Lister:</strong> Well, it definitely means you&#8217;re creating, so if you think of the site editor as the builder of the theme, which it kind of is, then technically, if you are creating content, which is the theme, you are creating that collaboratively, so yes. Collaborative editing at enterprise scale is something that happens quite often anyway.</p>\n\n\n\n<p>[00:27:17] <strong>Nathan Wrigley:</strong> So tools like Figma, you can do all of that collaborative editing is my understanding.</p>\n\n\n\n<p>[00:27:20] <strong>Tammie Lister:</strong> Yeah. So I&#8217;m very, if I put my design hat on, very used to, in Figma, like comments and, or even like in Google Docs, people are very used to like leaving messages and whatever. So I just think being very aware of those kind of workflows, is kind of interesting.</p>\n\n\n\n<p>One of the things we might find is, someone would just set up a template, and it&#8217;d be like, add something here, and something here later. So adding comments to your templates, might be curious and interesting.</p>\n\n\n\n<p>A different aspect might be people using different themes in the backend. That kind of comes to mind, from accessibility reasons. That is also something that I&#8217;ve always thought about is, could people want to have different editor experiences depending on their accessibility. Which you might do as well. So collaborative editor experiences, or different editor experiences. Which is slightly a sidetrack of this, but it&#8217;s something to consider.</p>\n\n\n\n<p>But phase three is collaborative editing, and plus, plus, plus. Which also the design system, finally, kind of flow. And that kind of, to me, is more Lego pieces to play with. And that&#8217;s the bit that I am incredibly excited about. Because a lot of the stuff that&#8217;s been hidden, we&#8217;ve had a design system all along. It&#8217;s really good.</p>\n\n\n\n<p>People, when they talk about the work that&#8217;s recently done, they&#8217;re pointing just to like the editor. Yes, but it&#8217;s not going to just be the editor. It&#8217;s going to be coming into the settings, into the admin, and to everything, because it needs to. There&#8217;s areas of WordPress that haven&#8217;t been touched for a very long time. And by bringing these components, and being this unification through, it&#8217;s better user experience. But it&#8217;s one user experience.</p>\n\n\n\n<p>Again, that point of, it&#8217;s a middle road. If it&#8217;s, the way that it&#8217;s being done, means you then will be able to have the same level of customisation, the same level of extensibility, the same level of styling on top of it. So you&#8217;ll be able to then, for your end users, customise it how you want to. So you have that flexibility still, yeah.</p>\n\n\n\n<p>[00:29:17] <strong>Nathan Wrigley:</strong> I think it&#8217;s fabulous that somebody who&#8217;s been around in the projects as long as you have, and I&#8217;m sure you&#8217;ve had your ups and downs, I&#8217;m sure that, you know, some days it&#8217;s like, oh, WordPress. It sounds like you are very, very, genuinely excited about what&#8217;s coming. That&#8217;s amazing.</p>\n\n\n\n<p>[00:29:30] <strong>Tammie Lister:</strong> And I&#8217;m excited about who&#8217;s doing it.</p>\n\n\n\n<p>[00:29:32] <strong>Nathan Wrigley:</strong> Oh, okay. Yeah.</p>\n\n\n\n<p>[00:29:33] <strong>Tammie Lister:</strong> It&#8217;s exciting the new, I love when you have fresher people have fresher eyes on it. I love when older people have fresh eyes on it as well, and different energy. I love when, as I&#8217;ve mentioned previously, when someone re-does work that I&#8217;ve done, I&#8217;m so excited. I&#8217;m like, yes, that&#8217;s gone.</p>\n\n\n\n<p>But it&#8217;s exciting to see areas that haven&#8217;t been touched for such a long time. We shouldn&#8217;t have areas that haven&#8217;t been for 10 years, because that&#8217;s how many years. That&#8217;s like dog years.</p>\n\n\n\n<p>[00:30:02] <strong>Nathan Wrigley:</strong> Tell us a little bit about your stuff. We&#8217;ve heard about your relationship with WordPress. Let&#8217;s just get into what you are doing at the minute. I think you said you had four hats or something. Is it four hats?</p>\n\n\n\n<p>[00:30:11] <strong>Tammie Lister:</strong> Yeah, I go with lots of hats.</p>\n\n\n\n<p>[00:30:12] <strong>Nathan Wrigley:</strong> What are the four hats? What&#8217;s keeping Tammie busy at the minute?</p>\n\n\n\n<p>[00:30:14] <strong>Tammie Lister:</strong> So I&#8217;m working on a project called Gildenberg. I&#8217;m working with Luke and Jonathan. What we&#8217;re doing is, we&#8217;re working on a guild of product creators, and we&#8217;re working to support them through that as well. That&#8217;s really exciting. So I&#8217;m doing that a little bit.</p>\n\n\n\n<p>I&#8217;m also creating my own, looking to create my own products. I&#8217;m working out what that means. Spoilers, going to start with theming. I&#8217;m also collaborating with some, doing some agency work as well. And I&#8217;ve been collab&#8217;ing some awesome plugins, doing some classic block based work. Which I actually really enjoy.</p>\n\n\n\n<p>There&#8217;s something about converting classic themes to block. One, because I&#8217;m learning where the friction points are. I&#8217;m also really lucky to be sponsored by Automattic, to be doing two days a week on the default theme task force.</p>\n\n\n\n<p>[00:30:59] <strong>Nathan Wrigley:</strong> Go on, tell us more about that. That sounds fun.</p>\n\n\n\n<p>[00:31:00] <strong>Tammie Lister:</strong> Yeah, I am really excited about that. It&#8217;s 400 odd tickets on the default themes. So the idea is, eventually, it came from the community summit. There&#8217;s actually a post up by Jonathan Desrosiers. Rather than scorch earthing, and removing all the default themes, it&#8217;s what if we actually fixed them? Which is a beautiful and wonderful concept.</p>\n\n\n\n<p>So what we&#8217;re doing is, we&#8217;re going through each ticket, and we are going to analyse, does it need fixing? Some of those tickets have been sat there for four, five years. They haven&#8217;t had attention.</p>\n\n\n\n<p>So we&#8217;re going to look at it, we&#8217;re going to see if it even stands in this time. If it does, great, let&#8217;s ship it, let&#8217;s get that patch in. If it doesn&#8217;t, it&#8217;s got a new patch. If it needs closing, let&#8217;s close it. And then we&#8217;ll able to see the lay of the land, once we don&#8217;t have this amount of tickets. Then we can decide where we go from this, on block based theme.</p>\n\n\n\n<p>[00:31:48] <strong>Nathan Wrigley:</strong> Kind of a nice project, that you can see that 400 dropping.</p>\n\n\n\n<p>[00:31:51] <strong>Tammie Lister:</strong> Oh goodness, yeah. We&#8217;ve already done some at contribution day.</p>\n\n\n\n<p>[00:31:53] <strong>Nathan Wrigley:</strong> Oh nice. Lovely.</p>\n\n\n\n<p>[00:31:55] <strong>Tammie Lister:</strong> And it is. I got to be part of some of the default themes. You know, one of my first roles within WordPress, you know, I kind of came in through theming. Theming has been a theme throughout my whole history of WordPress, throughout everything. And my heart is strongly there.</p>\n\n\n\n<p>And default themes, yes, some of them are classic, and we could be like, oh, just forget it. I don&#8217;t believe that. I think it&#8217;s history. It&#8217;s like denying that we have a history, right? And I love block themes. I think they&#8217;re amazing and they&#8217;re fantastic, but that doesn&#8217;t mean that we should forget that we have these themes.</p>\n\n\n\n<p>I think we should look at how we can bring the essence of those, if we want to bring them. Or we should look at how can we support the people that are still using them and how can we have that respect. So, if someone&#8217;s using 2011, how can we still respect that they&#8217;re using 2011?</p>\n\n\n\n<p>[00:32:50] <strong>Nathan Wrigley:</strong> Yeah. Yeah.</p>\n\n\n\n<p>[00:32:51] <strong>Tammie Lister:</strong> As well.</p>\n\n\n\n<p>[00:32:52] <strong>Nathan Wrigley:</strong> Yeah, that&#8217;s a lovely project. You very quickly glossed over, there was one there where you are going to be looking at doing your own projects, but you didn&#8217;t dive into that. Maybe it&#8217;s because you haven&#8217;t distilled it quite yet.</p>\n\n\n\n<p>[00:33:03] <strong>Tammie Lister:</strong> I haven&#8217;t yet fully.</p>\n\n\n\n<p>[00:33:04] <strong>Nathan Wrigley:</strong> What&#8217;s, the kind of intuition that that you&#8217;re going to tackle.</p>\n\n\n\n<p>[00:33:08] <strong>Tammie Lister:</strong> I really want to start creating my own themes again, that&#8217;s one of the things. And I also want to start exploring maybe some plugins as well. I don&#8217;t have an idea yet, but the idea that I can start. I&#8217;m going to use the word playing, but playing to an end. I have so many ideas, and that&#8217;s awesome, but I need to work out which idea I&#8217;m going to work on.</p>\n\n\n\n<p>[00:33:30] <strong>Nathan Wrigley:</strong> Okay, so maybe we should do this conversation again in 2025, and see where you are?</p>\n\n\n\n<p>[00:33:34] <strong>Tammie Lister:</strong> I have a theme site, Composition Themes, and I want to, I want to start making themes that have one purpose and, both that are beautiful, but also that have one purpose for types as well. That&#8217;s where I want to be themeing. But I also really like the idea of doing similar for plugins.</p>\n\n\n\n<p>Maybe it&#8217;s blocks, but maybe it&#8217;s also companion experience plugins. Going back to that idea of experience. I love the idea of maybe making the experience lesser for the editor or maybe exploring different things around that.</p>\n\n\n\n<p>[00:34:04] <strong>Nathan Wrigley:</strong> Yeah. Okay. 2025 is the date. We&#8217;ll have you back and we&#8217;ll see. What was it again?</p>\n\n\n\n<p>[00:34:08] <strong>Tammie Lister:</strong> Composition Themes.</p>\n\n\n\n<p>[00:34:10] <strong>Nathan Wrigley:</strong> Composition Themes.</p>\n\n\n\n<p>[00:34:10] <strong>Tammie Lister:</strong> Yeah. I also have Classic to Block Themes as well.</p>\n\n\n\n<p>[00:34:13] <strong>Nathan Wrigley:</strong> Oh, nice. Okay, we&#8217;ll put both of those in the show notes. Great. Well, Tammie Lister, thank you so much for joining me on the podcast today. I really appreciate it.</p>\n\n\n\n<p>[00:34:21] <strong>Tammie Lister:</strong> Thank you.</p>\n\n\n\n<p>[00:34:21] <strong>Nathan Wrigley:</strong> You are very welcome.</p>\n</div>\n\n\n\n<p>On the podcast today we have <a href=\"https://tammielister.com/\">Tammie Lister</a>.</p>\n\n\n\n<p>Tammie is a product creator focusing on WordPress. She has a hybrid background across product, design, psychology and development. She contributes to WordPress and is passionate about open source, and the community.</p>\n\n\n\n<p>If you’ve been in the WordPress space for a while, Tammie&#8217;s name is likely a familiar one. She&#8217;s an 18-year veteran of the project, a talented designer, developer, and a key contributor to the project. Her journey has made her wear a variety of hats in both agency life and product development.</p>\n\n\n\n<p>Today, Tammie shares insights that span from the practical to the philosophical within the open-source landscape. We get to hear Tammie&#8217;s perspective on this crucial experimentation phase in WordPress theme development, the balance she seeks between minimalist design and functional complexity, and her active roles, including the default theme task force.</p>\n\n\n\n<p>Our discussion takes us into the evolving WordPress editor experience, user roles, and interface design. We discuss the future of WordPress UI / UX, touching on visual configurations and how the Gutenberg site editor continues to shape our digital toolkit.</p>\n\n\n\n<p>For those inspired by themes, Tammie reveals her passion for them. From preserving the essence of classic themes to ways that the project might break new ground.</p>\n\n\n\n<p>She also introduces us to some of her own projects, such as Composition Themes, and discusses her Classic to Block Themes project as well.</p>\n\n\n\n<p>Tammie shares some of the resources that she recommends for both beginners and seasoned developers alike, bringing to light the many pathways that you can now choose to learn about WordPress.</p>\n\n\n\n<p>Looking over the horizon of collaborative editing and design systems, Tammie&#8217;s excitement for what&#8217;s next is palpable. So, whether you&#8217;re a developer, a designer, or a WordPress aficionado, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p><a href=\"https://asia.wordcamp.org/2024/\">WordCamp Asia</a></p>\n\n\n\n<p><a href=\"https://wordpress.org/plugins/create-block-theme/\">Create Block Theme plugin</a></p>\n\n\n\n<p><a href=\"https://www.csszengarden.com/\">CSS Zen Garden</a></p>\n\n\n\n<p><a href=\"https://wordpress.org/patterns/\">Pattern Directory</a></p>\n\n\n\n<p><a href=\"https://block-museum.com/\">Museum of Block Art</a></p>\n\n\n\n<p><a href=\"https://developer.wordpress.org/news/\">Developer blog</a></p>\n\n\n\n<p><a href=\"https://make.wordpress.org/core/tag/hallwayhangout/\">Hallway Hangouts</a></p>\n\n\n\n<p><a href=\"https://learn.wordpress.org/\">Learn WordPress</a></p>\n\n\n\n<p><a href=\"https://wordpress.tv/\">WordPress.tv</a></p>\n\n\n\n<p><a href=\"https://wordpress.org/state-of-the-word/\">State of the Word from 2024</a></p>\n\n\n\n<p><a href=\"https://guildenberg.com/\">Gildenberg</a></p>\n\n\n\n<p><a href=\"https://make.wordpress.org/core/2023/12/05/proposal-default-theme-task-force-for-2024/\">Jonathan Desrosiers&#8217; post &#8220;Proposal: Default Theme Task Force for 2024&#8221;</a></p>\n\n\n\n<p><a href=\"https://compositionthemes.com/\">Composition Themes</a></p>\n\n\n\n<p><a href=\"https://classictoblock.com/\">Classic to Block Themes</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 03 Apr 2024 14:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:19;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:76:\"Do The Woo Community: You Don’t Need to be a Developer to Join a Hackathon\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://dothewoo.io/?p=80797\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://dothewoo.io/you-dont-need-to-a-developer-to-join-a-hackathon/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:137:\"Patricia, a non-developer and WordPress contributor, shares her experience and the value of having diverse skills at CloudFest Hackathon.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 03 Apr 2024 09:02:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"BobWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:20;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"HeroPress: The Time I Left My Island – Quella volta che sono uscito dalla mia isola\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://heropress.com/?post_type=heropress-essays&p=6656\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:214:\"https://heropress.com/essays/the-time-i-left-my-island-quella-volta-che-sono-uscito-dalla-mia-isola/#utm_source=rss&utm_medium=rss&utm_campaign=the-time-i-left-my-island-quella-volta-che-sono-uscito-dalla-mia-isola\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:21363:\"<img width=\"1024\" height=\"512\" src=\"https://heropress.com/wp-content/uploads/2024/04/040224-min.jpg\" class=\"attachment-large size-large wp-post-image\" alt=\"Pull Quote: The sea has never been a limit, now that I know the way, I can cross it whenever I want. - Il mare non è mai stato un limite, ora che conosco la strada, posso attraversarlo tutte le volte che voglio.\" /><p><a href=\"https://heropress.com/feed/#italian\">Questo saggio è disponibile anche in italiano.</a></p>\n\n\n\n<p>Perfect, I have my blank sheet, notes on what I need to express, and I&#8217;m ready to write this essay. I have my hot coffee on the desk and my compilation of Bob Dylan playing in my ears, but we&#8217;re on the tenth song and I haven&#8217;t written a word yet, in fact, I&#8217;ve written and then deleted many. Do you know what happens? I&#8217;m not a writer, I spend my life in PHP, why should I completely detach from what is my daily routine? Okay, here we go! I&#8217;ll open my code editor, coffee, and Dylan at this hour are constants, let&#8217;s see if the words flow now.</p>\n\n\n\n<h2 class=\"kt-adv-heading6656_ed8ffe-24 wp-block-kadence-advancedheading\">My Island</h2>\n\n\n\n<p>I&#8217;m Sardinian, I come from an island in the Mediterranean envied for its sea, climate, food, and the warmth of its people. Let&#8217;s talk about an island, and sometimes the sea is a boundary, it&#8217;s a beautiful blue wall that separates you from the rest of the world, often it&#8217;s difficult to feel Italian, let alone European.</p>\n\n\n\n<p>My story begins here, with a strong introversion orchestrating my life, a passion for computer science, PHP which had been accompanying me for about 5 years, and some small attempts to overcome my shyness. Not to mention the years of studying English at school, which remained theoretical and never put into practice. To help me overcome shyness, I had started speaking at small events about Free Software, and there had been some small improvements. Meanwhile, I was beginning to get to know a CMS called WordPress, required by several companies; at that time, I didn&#8217;t know what it would give me.</p>\n\n\n\n<p>I had left my small town and moved to Cagliari, the city, on my island and facing the sea. Imagine, in 10 minutes with public transport, I was at the nearest beach, and in 30 minutes, I was at those beaches you see in screensavers. I felt in my place, at least geographically. But sometimes an island doesn&#8217;t offer you much from a work perspective, and remote work wasn&#8217;t yet so widespread. But my move to Cagliari was just a first step, like when you dip your foot in the water to see if it&#8217;s cold, before taking a run and diving in.</p>\n\n\n\n<h2 class=\"kt-adv-heading6656_06671b-01 wp-block-kadence-advancedheading\">Let&#8217;s change the song, but also the city and life.</h2>\n\n\n\n<p>I packed my bags, took a flight, and changed regions to pursue a job. I was leaving the place that De Andrè, a famous Italian singer-songwriter, described: &#8220;Life in Sardinia is perhaps the best a man can wish for: twenty-four thousand kilometers of forests, countryside, coasts immersed in a miraculous sea should coincide with what I would recommend to God to give us as Paradise.&#8221; And I arrived in what another famous Italian singer, Ligabue, describes as &#8220;This city is a hell disguised as paradise, where every dream is at risk of burning.&#8221;</p>\n\n\n\n<p>The city called me, and now I&#8217;m here. There are proposals, there are opportunities, there are hopes, and there are dreams, all within reach, my reach. The city is ready to give me everything but it needs me, my time, and my hard work. I just had to change, the island had to become a city, shyness must disappear here and change pace. Walking following that frenetic rhythm, which I didn&#8217;t understand, but which was ready to give me more and more.</p>\n\n\n\n<p>If you walk fast, in a place you don&#8217;t know, you risk coming across a street you don&#8217;t know and you could find yourself in a situation you never want to relive. You could walk on asphalt, on the sidewalk, or on a lawn, and if you&#8217;re not careful, it&#8217;s easy to stumble upon something, and from a panic attack, it&#8217;s not always easy to get back up, from two, worse.</p>\n\n\n\n<p>During the same period, I found myself on a fairly intense WordPress-based project, and between one check and another, my eye fell on a type of event I didn&#8217;t know, called WordCamp Torino, just over an hour by train from where I was.</p>\n\n\n\n<p>Early wake-up call, coffee, and off to the station, the train departs and slowly the city fades away. I participate in a contributor day and a day of talks. A nice event, I took thousands of notes but experienced only as much as my shyness allowed me to.</p>\n\n\n\n<p>I knew that this event was much more beautiful than what I had experienced, so I started paying more and more attention to that part of the site until I found two tickets, Zurich and Verona. I bought the ticket to Verona immediately, but Zurich was two weeks earlier and the choice wasn&#8217;t so easy.</p>\n\n\n\n<p>Zurich is part of German-speaking Switzerland, okay that the WordCamp was organized in two languages, but my English had been stagnant for almost 12 years, plus it was a trip to be done alone.</p>\n\n\n\n<p>Verona was a great WordCamp, I began to understand how these events work and to meet some members of the city&#8217;s MeetUp.</p>\n\n\n\n<p>Honestly, I remember Zurich less and less, it was a beautiful WordCamp, but I learned more things about myself there than about WordPress. I just wonder if there are Swiss people who believe that my surname is &#8220;sorry my English is terrible&#8221;, because when I&#8217;m a bit nervous, I speak faster and to introduce myself I would say &#8220;My name is Matteo sorry my English is terrible, nice to meet you&#8221;. The thing I remember best is that I filled out the application to be a speaker and volunteer during the return trip. Let&#8217;s talk about WordCamp Milano.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-but-it-s-just-a-tool-how-can-it-do-all-this\">But it&#8217;s just a tool, how can it do all this?</h2>\n\n\n\n<p>I was preparing my slides, comparing WordPress development with another CMS, starting from the latter. After finishing the first section where I had to talk about WordPress, I had to create a separation slide. Somewhat sarcastically, I wrote &#8220;But we&#8217;re at a WordCamp so let&#8217;s go home!&#8221; Ajo is a word widely used in Sardinia, taking it away from a Sardinian is like preventing a Roman from saying daje, it&#8217;s the equivalent of an English &#8220;let’s go&#8221;.</p>\n\n\n\n<p>It wasn&#8217;t my first time in front of an audience, but I was used to a maximum of 20/30 people. I found myself facing a university class with a lot of people, I was extremely excited and super tense. But at my &#8220;ajo&#8221; moment, amidst some laughter and some smiles, I felt at home again, in my island but at the same time in Milan, what a strange feeling.</p>\n\n\n\n<p>But it&#8217;s just a CMS, a work tool, how can it do all this? A stupid question if the person asking it has books like &#8220;Just for Fun&#8221; by Linus Torvalds, &#8220;The Cathedral and the Bazaar&#8221; by Eric Steven Raymond, and &#8220;Free Software, Free Society&#8221; by Richard Stallman in their library. So the term &#8220;community&#8221; in those texts was true and WordPress was the best example I could come across.</p>\n\n\n\n<p>In the span of a few months, I also attended events in Dublin and volunteered in Glasgow, English wasn&#8217;t a limitation for me, just something I had to work on.</p>\n\n\n\n<p>Glasgow was at the beginning of 2020, the last memory of a WordCamp before a year of closure, a year where there were online events, but the energy was different. A period in which I changed two jobs.</p>\n\n\n\n<p>It was a period halfway between the city and the island until the end of 2021, when I saw &#8220;WordCamp Geneva&#8221;, I proposed to tell my story at WordCamps, how they helped me, but they still do, both with language confidence and shyness. It was accepted and that became both my first talk in English, but also the non-technical one. A talk that involved a higher intimacy never experienced before, which will always remain a source of pride for me.</p>\n\n\n\n<p>From that moment on, WordCamp after WordCamp, each stop began to give me more and more emotions and more and more lessons, especially about myself, but not about who I am, but about what I could and wanted to be.</p>\n\n\n\n<p>From WordCamp Italy where I first became an organizer to Turin and Verona as a speaker.</p>\n\n\n\n<p>In all three, I decided to participate both days, also attending contribution days and gladly joining the polyglots team, a group I have never abandoned.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-to-infinity-and-beyond\">To infinity and beyond</h2>\n\n\n\n<p>Then they announced WordCamp Europe in Turin, the city where it all started, I applied as an organizer, which was accepted. Now I find myself talking to many new people in English almost twice a week. Every time is a challenge to my shyness, but by now I&#8217;ve learned to accept them.</p>\n\n\n\n<p>Sometimes I find myself comparing my first and last WordCamp. From a silent Contribution Day to one where I shared my experience, from being an attendee to a speaker with many listeners, from a day in silence to being someone trying to integrate the newcomers, from a person who leaves early to the last person leaving the after-party.</p>\n\n\n\n<p>But WordPress is just a tool, the end goal is always something else, in my story it&#8217;s not a website but understanding a part of myself and stopping suffocating my true identity and starting to behave in my own way. Making me understand that my island side shouldn&#8217;t be suppressed but valued, it was always me. Like in the code, with oneself too, there are best practices, they are needed to look back and live in harmony with oneself. In my case, WordCamp after WordCamp, I added one more brick to my self-esteem and I understood something more about my shyness.</p>\n\n\n\n<p>In the end, living the WordPress community, getting to know many different people guided me towards rediscovering myself until I realized that I had never left my island, maybe it was the city&#8217;s fog that made me perceive it as farther away, it had always been here. The sea has never been a limit, now that I know the way, I can cross it whenever I want. My island was me and now I&#8217;ve learned to accept it.</p>\n\n\n\n<p>Yes, I&#8217;d say I did well to use the dark editor! Let&#8217;s contribute!</p>\n\n\n\n<h1 class=\"wp-block-heading\" id=\"italian\">Quella volta che sono uscito dalla mia isola</h1>\n\n\n\n<p>Perfetto, ho il mio foglio bianco, gli appunti su quello che devo esprimere e sono pronto a scrivere questo saggio. Ho il mio caffè caldo sulla scrivania e la mia compilation di Bob Dylan alle orecchie, ma siamo alla decima canzone e non ho ancora scritto una parola, anzi, ne ho scritte e poi cancellate tante. Sai che succede? Non sono uno scrittore, passo la mia vita in PHP, perché dovrei estraniarmi completamente da ciò che è la mia quotidianità? Ok, ci sono! Apro il mio editor di codice, il caffè e Dylan a quest&#8217;ora sono una costante, vediamo se ora le parole escono.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-la-mia-isola\">La mia isola</h2>\n\n\n\n<p>Sono sardo, vengo da un’isola del mediterraneo invidiata per il mare, il clima, il cibo ed il cuore delle persone. Parliamo di un isola, e il mare a volte è un limite, è un bellissimo muro blu che ti separa dal resto del mondo, spesso si ha la difficoltà di sentirsi italiani, figurati europei.</p>\n\n\n\n<p>La mia storia inizia qua, con una forte introversione che orchestrava la mia vita, la passione per l&#8217;informatica, il PHP che da circa 5 anni mi accompagnava e qualche piccolo tentativo di superare la mia timidezza. Senza dimenticare gli anni di studio dell&#8217;inglese a scuola, che sono rimasti teorici e mai messi in pratica. Per aiutarmi a sconfiggere la timidezza avevo iniziato a fare lo speaker in piccoli eventi sul Software Libero e qualche piccolo miglioramento c&#8217;era stato. Intanto iniziavo a conoscere un CMS chiamato WordPress richiesto da diverse aziende, in quel periodo non sapevo quello che mi avrebbe dato.</p>\n\n\n\n<p>Avevo lasciato il mio paesino e trasferito a Cagliari, la città, nella mia isola e davanti al mare. Pensate, in 10 minuti con i mezzi cittadini ero nella spiaggia più vicina e in 30 minuti ero in quelle spiagge che si vedono nei screensaver. Mi sentivo nel mio posto, almeno geograficamente. Ma un&#8217;isola a volte, non ti offre tantissimo da un punto di vista lavorativo e il lavoro da remoto non era ancora così diffuso. Ma il mio trasferimento a Cagliari era solo un primo passo, come quando metti il piede in acqua per sapere se è fredda, prima di prendere la rincorsa e tuffarsi.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-cambiamo-canzone-ma-anche-citta-e-vita\">Cambiamo canzone, ma anche città e vita</h2>\n\n\n\n<p>Avevo riempito le valigie, preso un volo e cambiato regione per seguire un lavoro. Lasciavo il luogo che De Andrè, un famoso cantautore italiano, descriveva: “La vita in Sardegna è forse la migliore che un uomo possa augurarsi: ventiquattromila chilometri di foreste, di campagne, di coste immerse in un mare miracoloso dovrebbero coincidere con quello che io consiglierei al buon Dio di regalarci come Paradiso” e arrivavo in quella che un altro famoso cantante italiano, Ligabue, descrive come “Questa città è un inferno travestito da paradiso, dove ogni sogno è a rischio di bruciarsi&#8221;.</p>\n\n\n\n<p>La città mi ha chiamato, ed ora sono qua. Ci sono proposte, ci sono occasioni, ci sono speranze e ci sono sogni e tutte a portata di mano, la mia mano. La città è pronta a darmi tutto ma ha bisogno di me, del mio tempo e del mio duro lavoro. Dovevo solo cambiare, l’isola doveva diventare città, la timidezza deve sparire qua e cambiare passo. Camminare seguendo quel ritmo frenetico, che non capivo, ma che era pronto a darmi sempre di più.</p>\n\n\n\n<p>Se cammini veloce, in un posto che non conosci, rischi di imbatterti in una strada che non conosci e potresti trovarti in una situazione che mai vorresti rivivere. Potresti camminare sull’asfalto, sul marciapiede o su un prato, e se non si sta attenti è facile inciampare su qualcosa e da un attacco di panico non sempre è facile rialzarsi, da due peggio.</p>\n\n\n\n<p>Nello stesso periodo mi sono ritrovato su un progetto basato su WordPress abbastanza intenso e tra un controllo e l&#8217;altro mi è caduto l’occhio su una tipologia di evento, che non conoscevo, chiamato WordCamp Torino a poco più di un ora di treno da dove stavo.&nbsp;</p>\n\n\n\n<p>Sveglia presto, caffè e di corsa in stazione, il treno parte e pian piano la città si allontana. Partecipo ad un giorno di contributor day e ad una giornata di talk. Un bel evento, preso migliaia di appunti ma vissuto come solo la mia timidezza mi permetteva di essere.&nbsp;</p>\n\n\n\n<p>Sapevo che questo evento era molto più bello di quello che avevo vissuto, quindi inizio a prestare sempre più attenzione a quella parte del sito sino a che non trovai due biglietti, Zurigo e Verona. Il biglietto di Verona lo presi subito, ma Zurigo era due settimane prima e la scelta non era così facile.&nbsp;</p>\n\n\n\n<p>Zurigo fa parte della Svizzera tedesca, ok che il WordCamp era organizzato in due lingue, ma il mio inglese era rimasto fermo da quasi 12 anni, in più era un viaggio da fare da solo.</p>\n\n\n\n<p>Verona fu un ottimo WordCamp, iniziai a capire il funzionamento di questi eventi e conoscere alcuni componenti dei MeetUp della città.</p>\n\n\n\n<p>Zurigo sinceramente lo ricordo sempre meno, è stato un bellissimo WordCamp, ma ho imparato lì più cose su me stesso che su WordPress. Mi chiedo solamente se ci sono svizzeri che credono che il mio cognome sia “sorry my English is terrible”, perchè quando sono un po’ nervoso, parlo più veloce e per presentarmi dicevo “My name is Matteo sorry my English is terrible, nice to meet you”. La cosa che ricordo meglio è che ho compilato la domanda per fare da speaker e volontario durante il viaggio di ritorno.&nbsp;</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-parliamo-di-wordcamp-milano\">Parliamo di WordCamp Milano.</h2>\n\n\n\n<p>Ma è solo uno strumento, come può fare tutto questo?</p>\n\n\n\n<p>Preparo le mie slide, confrontavo lo sviluppo su WordPress con un altro CMS, partendo da quest’ultimo. Finito il primo pezzo dovevo parlare di WordPress, dovevo creare una slide di separazione, un po’ sarcasticamente scrissi “Ma siamo in un WordCamp quindi ajo a casa!”. Ajo è una parola molto usata in Sardegna, toglierla a un sardo è come impedire ad un romano di dire daje, è l&#8217;equivalente di un “let’s go” inglese.&nbsp;</p>\n\n\n\n<p>Non era la prima volta davanti ad un pubblico, ma ero abituato a un massimo di 20/30 persone, mi trovai davanti una classe universitaria con tantissime persone, ero emozionatissimo e super teso. Ma al mio momento del “ajo”, tra qualche risata e qualche sorriso mi sentii nuovamente a casa, nella mia isola ma allo stesso tempo a Milano, che strana emozione.&nbsp;</p>\n\n\n\n<p>Ma si tratta di un CMS, uno strumento di lavoro, come può fare tutto questo? Una domanda stupida se chi la fa ha nella sua libreria libri come “Rivoluzionario per caso” di Linus Torvald, “La cattedrale e il bazaar” di Eric Steven Raymond e “software libero, pensiero libero” di Richard Stallman. Quindi il termine “comunità” in quei testi era vero e WordPress era il miglior esempio in cui potevo capitare.</p>\n\n\n\n<p>Nel giro di pochi mesi, partecipai anche a Dublino e feci da volontario a Glasgow, l’inglese non era un mio limite, ma solo qualcosa su cui dovevo lavorare.&nbsp;</p>\n\n\n\n<p>Glasgow fu ad inizio 2020, l’ultimo ricordo di un WordCamp prima di un anno di chiusura, un anno in cui c&#8217;erano gli eventi online, ma l’energia era diversa. Un periodo in cui cambia due lavori.<br />Fu un periodo a metà tra la città e l’isola fino alla fine del 2021, quando vidi “WordCamp Ginevra”, proposi di raccontare la mia storia nei WordCamp, come mi aiutarono, ma lo fanno tutt’ora, sia con la sicurezza nella lingua che con la timidezza. Fu accettato e quello per me diventò sia il mio primo talk in inglese, ma anche quello non tecnico. Un talk che prevedeva un&#8217;intimità più alta mai sperimentata, che rimarrà per sempre un mio orgoglio.</p>\n\n\n\n<p>Da quel momento in poi, WordCamp dopo WordCamp, ogni tappa iniziò a regalarmi sempre più emozioni e sempre più lezioni, soprattutto su me stesso, ma non su come sono, ma su quello che potevo e volevo essere.&nbsp;</p>\n\n\n\n<p>Da WordCamp Italia in cui feci per la prima volta l’organizer a Torino e Verona da speaker.</p>\n\n\n\n<p>In tutti e tre decisi di partecipare entrambi i giorni, partecipando anche alle giornate di contribuzione e portandomi con piacere nel team polyglots, gruppo che non ho mai più abbandonato.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-verso-l-infinito-ed-oltre\">Verso l’infinito ed oltre</h2>\n\n\n\n<p>Poi annunciarono WordCamp Europe a Torino, la città dove tutto è iniziato, feci domanda come organizer, che fu accettata. Ora mi ritrovo a parlare con tantissime persone nuove in inglese quasi due volte alla settimana. Ogni volta è una sfida alla mia timidezza, ma ormai ho imparato ad accettarle.</p>\n\n\n\n<p>A volte mi capita di confrontare il mio primo ed ultimo WordCamp. Da un Contribution Day silenzioso ad uno in cui raccontavo la mia esperienza, solo attendee a speaker con tantissimi ascoltatori, da una giornata in silenzio a persona che cercava di far integrare i nuovi, da persona che rientra presto all’ultima persona che esce dall&#8217;after party.</p>\n\n\n\n<p>Ma WordPress è solo uno strumento, il fine è sempre un altro, nella mia storia non è un sito internet ma riuscire a capire una parte di me e smettere di soffocare la mia vera identità ed iniziare a comportarsi a modo mio. Facendomi capire che la mia parte isola non andava soffocata ma valorizzata, ero sempre io. Come nel codice, anche con se stessi, ci sono delle best practice, servono per riguardarsi e vivere in armonia con se stessi. Nel mio caso, WordCamp dopo WordCamp ho messo un mattoncino in più alla mia autostima e ho capito qualcosa in più sulla mia timidezza.</p>\n\n\n\n<p>Alla fine vivere la community di WordPress, conoscere tante persone diverse mi ha guidato verso la riscoperta di me stesso sino ad accorgermi che non avevo mai lasciato la mia isola, forse era la nebbia della città che me la faceva percepire più lontana, era sempre stata qui. Il mare non è mai stato un limite, ora che conosco la strada, posso attraversarlo tutte le volte che voglio. La mia isola ero io e ora ho imparato ad accettarlo.</p>\n\n\n\n<p>Si, direi che ho fatto bene ad usare l’editor scuro! Ajo a contribuire!</p>\n<p>The post <a href=\"https://heropress.com/essays/the-time-i-left-my-island-quella-volta-che-sono-uscito-dalla-mia-isola/\">The Time I Left My Island &#8211; Quella volta che sono uscito dalla mia isola</a> appeared first on <a href=\"https://heropress.com\">HeroPress</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 03 Apr 2024 07:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Matteo Enna\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:21;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"WordPress.org blog: WP Briefing: Episode 76: A WordPress 6.5 Sneak Peek\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://wordpress.org/news/?post_type=podcast&p=17158\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"https://wordpress.org/news/2024/04/episode-76-a-wordpress-6-5-sneak-peek/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:40470:\"<p>Join WordPress Executive Director, Josepha Haden Chomphosy, as she offers an exclusive preview of the upcoming WordPress 6.5 release, accompanied by special guest Dave Smith, one of the Editor Tech leads for this release. Don&#8217;t miss this opportunity for an insider&#8217;s look!</p>\n\n\n\n<h2 class=\"wp-block-heading\">Credits</h2>\n\n\n\n<p>Host: <a href=\"https://profiles.wordpress.org/chanthaboune/\">Josepha Haden Chomphosy</a><br />Guest: <a href=\"https://profiles.wordpress.org/get_dave/\">Dave Smith</a><br />Editor: <a href=\"https://profiles.wordpress.org/dustinhartzler/\">Dustin Hartzler</a><br />Logo: <a href=\"https://profiles.wordpress.org/javiarce/\">Javier Arce</a><br />Production: <a href=\"https://profiles.wordpress.org/bjmcsherry/\">Brett McSherry</a> and <a href=\"https://profiles.wordpress.org/eidolonnight/\">Nicholas Garofalo</a><br />Song: Fearless First by Kevin MacLeod</p>\n\n\n\n<h2 class=\"wp-block-heading\">Show Notes</h2>\n\n\n\n<ul>\n<li><a href=\"https://wordpress.org/download/\">WordPress Download</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/6-5/#:~:text=To%20get%20involved%20in%20WordPress,leave%20feedback%20on%20the%20ticket.\">WordPress 6.5 Development Cycle</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2024/03/07/unblocking-wp6-5-font-library-and-synced-pattern-overrides/\">Unblocking WP6.5 – Font Library and Synced Pattern Overrides</a></li>\n\n\n\n<li><a href=\"https://developer.wordpress.org/block-editor/reference-guides/packages/packages-dataviews/\">Data Views</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2023/07/12/admin-design/\">WP-Admin Redesign</a></li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/ticket/59166\">Font Library</a></li>\n\n\n\n<li><a href=\"https://developer.wordpress.org/news/2024/02/29/an-introduction-to-block-based-mega-menus/\">An Introduction to Block-Based Mega Menus</a></li>\n\n\n\n<li><a href=\"https://www.youtube.com/daveonwp\">Dave on WP</a>\n<ul>\n<li><a href=\"https://www.youtube.com/watch?v=ySyJRYAbU_M\">These TINY Link Editing CHANGES Just Made WORDPRESS 6.5 So Much Better</a></li>\n</ul>\n</li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2024/03/04/interactivity-api-dev-note/\">Interactivity API in 6.5</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/test/2024/01/13/early-opportunities-to-test-wordpress-6-5/\">Opportunities to Test WordPress 6.5</a></li>\n\n\n\n<li><strong>Small List of Big Things</strong>\n<ul>\n<li><a href=\"https://make.wordpress.org/community/2024/03/08/asia-meetup-revival-project-2024/\" target=\"_blank\" rel=\"noreferrer noopener\">Asia Meetup Revival Project 2024</a> </li>\n\n\n\n<li><a href=\"https://make.wordpress.org/meetings/\" target=\"_blank\" rel=\"noreferrer noopener\">Upcoming WordPress Meetings</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/marketing/2024/03/20/making-a-wordpress-media-corps/\" target=\"_blank\" rel=\"noreferrer noopener\">Making a WordPress Media Corps</a></li>\n</ul>\n</li>\n\n\n\n<li>Have a question you’d like answered? Submit them to&nbsp;<a href=\"mailto:wpbriefing@WordPress.org\">WPBriefing@WordPress.org</a>.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Transcript</h2>\n\n\n\n<span id=\"more-17158\"></span>\n\n\n\n<p>[00:00:00] <strong>Josepha:</strong> Hello, everyone, and welcome to the WordPress Briefing, the podcast where you can catch quick explanations of the ideas behind the WordPress open source project, some insight into the community that supports it, and get a small list of big things coming up in the next two weeks.</p>\n\n\n\n<p>I&#8217;m your host, Josepha Haden Chomphosy. Here we go!&nbsp;</p>\n\n\n\n<p>[00:00:28] (Intro Music)&nbsp;</p>\n\n\n\n<p>[00:00:39] <strong>Josepha:</strong> Dave, I&#8217;m so excited to have you here with us today. Welcome.</p>\n\n\n\n<p>[00:00:42] <strong>Dave:</strong> Thank you. I&#8217;m really excited to be here. Thank you so much for inviting me on.</p>\n\n\n\n<p>[00:00:46] <strong>Josepha:</strong> Yeah. So before we get much further, how about you tell us a little bit about what you do on the WordPress project? And if I recall correctly, that you have a role on the release squad. So just let us know a bit about what that role is and what that looks like.</p>\n\n\n\n<p>[00:01:00] <strong>Dave:</strong> Sure. Absolutely. Well, obviously said I&#8217;m Dave Smith. I&#8217;m from England in the United Kingdom, and I am full-time contributor to WordPress. I&#8217;ve focused primarily on the Block Editor during that time. And I&#8217;ve been doing it for about three years now. And fortunately for me, I am sponsored by Automattic, so that allows me to contribute full-time to the project, which is fantastic.</p>\n\n\n\n<p>But my history of WordPress goes back a fair way longer than that, and I used to work in agency land, and so I used WordPress for making things for a living before I worked in WordPress if you see what I mean.&nbsp;</p>\n\n\n\n<p>[00:01:35] <strong>Josepha:</strong> I, no, I definitely understand. I also was agency before WordPress.&nbsp;</p>\n\n\n\n<p>[00:01:40] <strong>Dave:</strong> I think it&#8217;s a common origin story, if you see what I mean. And yes, you&#8217;re absolutely right. I&#8217;ve been fortunate enough in this release, WordPress 6.5, to be the Co-editor Tech Lead. Obviously alongside my colleague which is Riad Benguella. Some of you may know him. He is the lead architect of Gutenberg. So yeah, it&#8217;s been fantastic to work alongside him.</p>\n\n\n\n<p>[00:02:00] <strong>Josepha:</strong> Yeah, excellent. One of these days, I&#8217;m going to get Riad on here. I think I&#8217;ve never had him on.</p>\n\n\n\n<p>[00:02:05] <strong>Dave:</strong> Oh, you should definitely.&nbsp;</p>\n\n\n\n<p>[00:02:06] <strong>Josepha:</strong> He&#8217;s so kind and reasonable. And I was just gonna tell a personal anecdote about Riad, and I don&#8217;t know that it makes any sense, but I&#8217;m gonna do it anyway. I&#8217;m gonna do it anyway. I saw him at an event like right after he came back from his most recent sabbatical, and he was like, it was great being away, but also like, I had forgotten what kind of energy events like this really bring in.</p>\n\n\n\n<p>And he has always struck me as an introvert, but I think maybe he&#8217;s like an outgoing introvert or something. Cause normally, like, introvert introverts are not like, this gives me so much energy. They&#8217;re like, I know that this is important work, and I&#8217;m here. And so that&#8217;s my personal anecdote about Riad, I am, gonna get him on here someday, but be that as it may, we&#8217;re delighted to have you.</p>\n\n\n\n<p>So, 6.5 is coming out are you excited, number one?</p>\n\n\n\n<p>[00:02:54] <strong>Dave:</strong> I am very excited. Yeah, it&#8217;s been a long road into this release. As you may know, well, as you do know, it&#8217;s, it was delayed by one week. That was actually, I think was, was a good decision. We&#8217;ve had a lot of work needing to go into the Font Library feature. I&#8217;ve seen a few posts saying there were bugs.</p>\n\n\n\n<p>[00:03:09] <strong>Dave:</strong> I think mainly it was a decision about where to upload fonts to, which seems quite amazing when you think about it. I was talking to my wife about it the other day, and she said, really, you&#8217;re delaying a release because of where to upload things. But, yeah, this is software that runs a considerable part of the web.</p>\n\n\n\n<p>So when we make these decisions about where things uploaded, we&#8217;ve got to be really confident that they are the right decisions. And so, yeah, that decision to delay the release has been good. And we&#8217;ve had an opportunity to make sure the release is fully robust and ready to go out. So yeah, I&#8217;m super excited to see it land.</p>\n\n\n\n<p>[00:03:40] <strong>Josepha:</strong> Yeah. I have some follow up questions about just like, how doing all of that work in public feels. But probably, we should get through the bulk of the sorts of things that people tune into this episode for, so like, let&#8217;s talk about some of the big features that are going into 6.5 so that folks have a sense for that.</p>\n\n\n\n<p>And then we&#8217;ll take a look at just like things that you&#8217;re excited to get in, things that I&#8217;m excited to get in. And maybe like if there&#8217;s a hidden surprise for users, things that will be really beneficial to users, but they don&#8217;t quite see it yet. We can maybe cover that too, but like, what are the big things going into this release from your perspective?</p>\n\n\n\n<p>[00:04:17] <strong>Dave:</strong> Sure. There&#8217;s some highlights, I think that the key highlights, and we should probably cover them. So the first one we&#8217;ve already touched on it is the Fonts Library. And this has been brewing for a while now, and it&#8217;s finally come to fruition. And it basically allows you to manage, install, and upload custom fonts for use on your website. And it&#8217;s really, really powerful. It&#8217;s, I think it&#8217;s going to really change the way people create themes and create their websites. It is unlocking a lot of power for users.</p>\n\n\n\n<p>[00:04:46] <strong>Josepha:</strong> And for folks who&#8217;ve been listening to this podcast for a long time, you have heard me say for, I think, like a year, basically every release podcast where we&#8217;re looking at what&#8217;s coming up. I&#8217;m like, and this time it&#8217;s fonts. I&#8217;m so excited. And so I&#8217;m saying it again this time, &#8217;cause it&#8217;s really happening this time.</p>\n\n\n\n<p>[00:05:03] <strong>Dave:</strong> It&#8217;s finally here. Yeah, it&#8217;s a great feature. There&#8217;s a lot of work gone into it. It&#8217;s really, really good.</p>\n\n\n\n<p>[00:05:07] <strong>Josepha:</strong> So much work. We&#8217;ve been working on it for like two or three years. And it&#8217;s at the point where like getting it out in front of people is the only way to figure out where the remaining problems will be. And it is the most scary part of any software release, I assume, the things where you&#8217;re like, this is time for people to tell us how it&#8217;s broken. Please look at it and break it for a while.</p>\n\n\n\n<p>[00:05:29] <strong>Dave:</strong> Yeah, absolutely. We&#8217;ve been working on resolving any bugs that we could find, but there&#8217;s always going to be things we haven&#8217;t noticed. So yeah, we can&#8217;t wait for users to get their hands on it. Exactly. Other than fonts, we&#8217;ve also got revisions that are now in place in the Site Editor. And this is more than just undo, redo that people may be already familiar with in the editor.</p>\n\n\n\n<p>It actually gives you the ability to fully revert your site back to any state that you previously had it. So you could make some changes in the editor. You could completely close down your computer, go away for a week, come back. And you&#8217;ve still got the opportunity to say, &#8220;Ah, do you know what? I don&#8217;t like the way that looks. I&#8217;m just gonna; I&#8217;m gonna roll that back.&#8221; And there&#8217;s a nice UI that shows you what it will affect. And you can even roll back styles, you know, like style changes. So it&#8217;s, it&#8217;s super, super powerful. And it&#8217;s just something we&#8217;ve been waiting for for such a long time. Just, it&#8217;s fantastic to see it land.</p>\n\n\n\n<p>[00:06:17] <strong>Josepha:</strong> I&#8217;m really excited about this one personally because I have been to so many meetup events with like new users being taught how to do things with WordPress. And invariably, in the last two or three years, the people who are presenting to new users are saying consistently like, &#8220;You can do any experimental thing that you feel like you need to do with your sites because there&#8217;s an undo button. WordPress wouldn&#8217;t let you do things that fully break your site.&#8221;</p>\n\n\n\n<p>Like there is a lot of trust in our kind of like time machine, roll-it-back kind of implementations. And so I&#8217;m really excited about this one. I think that for all of our new and mid-level users. Who like, have a little bit of fear, but mostly joy around it. Like, this will only increase that and so I&#8217;m super excited for this one to go in there.</p>\n\n\n\n<p>[00:07:09] <strong>Dave:</strong> Yeah, it&#8217;s really nice. Other than that, the two things I wanted to touch on as well, which is we&#8217;ve got these new views now for key objects in WordPress. So things like pages, patterns, templates, and template parts in the Site Editor. You can now view these in a sort of a table layout or in a grid layout. So it gives you a much easier way to sort them, find them, filter them. And I think it points us forward to the possibilities we&#8217;ve got in the future for the editor sort of taking some parts of WP Admin and making them more accessible without having to leave the Site Editor. And it&#8217;s extremely powerful; you can search in real-time, find things very, very quickly, do all the things you&#8217;re used to from the post listing screen, but all within the Site Editor. And it&#8217;s for these key objects that you use quite a lot of the time. So I think it&#8217;s going to be really, a really great thing for users to get hold of.</p>\n\n\n\n<p>[00:07:55] <strong>Josepha:</strong> Is this related to the Data Views work that we&#8217;ve been doing in the first part of the year here?</p>\n\n\n\n<p>[00:08:00] <strong>Dave:</strong> Exactly that exactly. The Data Views work has been a major feed into this, and this is where we see the fruits of all that work coming to the fore for the first time. And I expect to see more of that in future releases as well.</p>\n\n\n\n<p>[00:08:12] <strong>Josepha:</strong> Yeah. For folks who are really, really watching, like, our administrative side of things, you probably are aware that we, I don&#8217;t know, I wouldn&#8217;t say that we paused the phase three roadmap for this, but I do think that we made a clear choice to get this Data Views work done first so that we could, in parallel with phase three, do a bit of work on the WP Admin redesign, the dashboard redesign, which we all know, like, we love this dashboard, but also this dashboard, it needs a sprucing up, it needs a little bit of, of polish and a little bit of 2024 style I was going to say design. I don&#8217;t know if the design folks would love if I just was like, it needs to be modernized that way, but also like it, it does, right?</p>\n\n\n\n<p>[00:09:00] <strong>Dave:</strong> Yeah, and I mean, you know, we all know that the Site Editor is being used more and more. If you&#8217;ve got a Block theme, you&#8217;re using the Site Editor increasingly, and you&#8217;re spending less and less time sort of going between screens in WP Admin. So it makes sense that, you know, these things are accessible within that one interface of the Site Editor. So, yeah, it&#8217;s only going to be a good thing for users going forward.</p>\n\n\n\n<p>[00:09:20] <strong>Josepha:</strong> Yeah, absolutely. I probably should have like a whole episode about Data Views and what it&#8217;s intending to do, what it&#8217;s actually doing, what it&#8217;s going to look like as it goes because that&#8217;s such a big project. And so many things rely on it. And so, note to self and all listeners, that&#8217;s the thing that you should keep an eye out for. We&#8217;re going to get it done. But you said you had a final thing also.</p>\n\n\n\n<p>[00:09:40] <strong>Dave:</strong> Yeah, I&#8217;ve got one more which is this is for our users of classic themes. We haven&#8217;t forgotten about you. Basically, we now have support for appearance tools. So in prior releases, the Block themes have got these really cool design tools like ability to set border colors, border radius, link colors, you name it. We&#8217;ve got all these tools, but they haven&#8217;t been always available to classic themes. And classic themes can use the Block Editor; they may not be using the Site Editor in the same way, but they can use the Block Editor. And we&#8217;ve not made those things available in the same way, but there&#8217;s been work going into this release to allow that to happen.</p>\n\n\n\n<p>[00:10:11] <strong>Dave:</strong> So now you can opt into those if you so wish. And it is an opt-in basis. So none your themes will break out of the box if you&#8217;ve got classic theme or classic site. But it is a powerful tool to those people who are using classic themes, and that&#8217;s completely legitimate.</p>\n\n\n\n<p>[00:10:26] <strong>Josepha:</strong> And so is the opt in like something that you can do for yourself or something that your developer needs to do?</p>\n\n\n\n<p>[00:10:32] <strong>Dave:</strong> You would need to do it in your theme code. So you&#8217;d need to do that with PHP. So, your theme developer, if they choose to update their theme and provide support for these things. Then, they would obviously need to test their theme works with those new tools, make sure it&#8217;s ready, and then they would ship that update.</p>\n\n\n\n<p>And so maybe after 6.5 is released, you may see some themes incrementally adding support. My understanding at the moment is that the core themes, the Block themes, will not automatically add those straight away. I think they need more time to allow them to bed in and more time to get them ready for prime time if you see what I mean, but you know the fact that they&#8217;re there and ready means that the wider theme audience and theme developers can start taking advantage of them.</p>\n\n\n\n<p>[00:11:15] <strong>Josepha:</strong> Nice, nice. I have been wondering lately, this is only marginally related, but I&#8217;m gonna wonder it out loud anyway. I&#8217;ve been wondering lately if like, our classic themes, our most favorite, our most loved classic themes do need a little bit of help moving into a Block theme future. And I think that this will help. I think, on the one hand this will help, and on the other hand, like, what would it take for us to just say, and you&#8217;re not the theme person I know, but like, what would it take for us to just say, &#8220;These are our top five most favorite, most used, classic themes that we&#8217;ve got in WordPress. Let&#8217;s rebuild it in blocks and just ship the block version of it and help the classic themes users that love the design, love the look, love the features get introduced to this new block territory so that they can see that not only do they have the look, the feel, the features, but also the flexibility that comes with that and a little bit more feeling of safety as they wander around modifying themes.&#8221;</p>\n\n\n\n<p>[00:12:18] <strong>Josepha:</strong> I have no fear of any code changes and didn&#8217;t when I started working with WordPress, as opposed to working in WordPress, but I think that that&#8217;s not the way that that works right now. Like there&#8217;s a whole lot of like, I need to get it right-ish with folks who are using our software. And so I just wonder if that will help everybody feel a little more confident in what they&#8217;re doing, knowing they&#8217;re not going to break things because we&#8217;ve built it so you can&#8217;t.</p>\n\n\n\n<p>[00:12:45] <strong>Dave:</strong> It could do, it could do. And I was just thinking as you were talking, like, do we have any themes that already do that? And, of course, we do have 2021. If you can think back that far into the mists of time, we had 2021 classic, which is that it&#8217;s called 2021, but we also 2021 blocks, which is doing very much what you&#8217;ve just described.</p>\n\n\n\n<p>[00:13:03] <strong>Dave:</strong> So we haven&#8217;t pursued that for the new default themes or block themes, but, you know, it might be something to look at for onboarding if there are any of classic themes from the more distant past, you know, maybe some of those could do with a block theme equivalent just to let people on board to that experience and just feel comfortable. Yeah, interesting, interesting. You should definitely talk to the theme people about that.</p>\n\n\n\n<p>[00:13:23] <strong>Josepha:</strong> I&#8217;m going to. They&#8217;re going to love it. They&#8217;re going to be like, Yay! Of course! Of course! I don&#8217;t know, actually. I don&#8217;t know if anyone ever loves the things that I suggest, but that doesn&#8217;t mean that they&#8217;re not going to get suggested. I have all these ideas, and they got to come out somewhere. Okay. So do you have something that you worked on that&#8217;s not in this big list of features or that you helped people to really shepherd into the release that you think is really cool? Like, maybe it&#8217;s not going to be super visible or something, but like that you&#8217;ve personally felt was like a cool feature, excited for it to get into the release.</p>\n\n\n\n<p>[00:13:53] <strong>Dave:</strong> Yeah, there are a couple of things, a couple of things at the top of mind. One of them is user-facing and one of them is more developer-facing features. So, I&#8217;ll start with the developer feature first. And this one is a change to an API. Now, that API is always a slightly intimidating word, I think, but it just means a set of tools, a standardized set of tools that developers can use to do something. And in this case, it&#8217;s the allowed blocks API.&nbsp;</p>\n\n\n\n<p>[00:14:20] <strong>Josepha:</strong> Sounds so fun.&nbsp;</p>\n\n\n\n<p>[00:14:21] <strong>Dave:</strong> Yeah, I know it&#8217;s riveting, isn&#8217;t it? But trust me, it does come with some benefits. So the Navigation block is a good example. It&#8217;s a block that acts as a container and it&#8217;s got child blocks. Okay. But you can only insert certain blocks. You can insert links, you can insert social icons, you can insert search. But if you want to insert, I don&#8217;t know, an Icon block, for example. You can&#8217;t do that, but you can with WordPress 6.5 because of the change to the allow box API. And what it allows you to do is say, &#8220;I want to additionally allow the following blocks to be inserted as well.&#8221;</p>\n\n\n\n<p>So as a developer, you can hook into this filter and change those blocks. Now, okay, so far, so good. &#8220;What&#8217;s the big deal?&#8221; you might say, well, it&#8217;s open the door, is open the door to some very, very interesting explorations. Some of which I&#8217;ve no doubt that you and your listeners would have already encountered. And one is by a colleague of mine called Nick Diego. And I think it&#8217;s on the WordPress Developer blog right now. I think he&#8217;s done a fantastic inspiration into mega menus in the navigation block. I&#8217;m someone who&#8217;s worked on the Navigation block extensively in the past, and I&#8217;m very aware of how much users want mega menus to be a part of the Navigation block.</p>\n\n\n\n<p>[00:15:30] <strong>Dave:</strong> I was never convinced it was going to be something we were going to do in core, because it requires so many different things. But Nick has actually managed with this allow blocks API and some other tweaks as well to build a mega menu as a plugin for WordPress using the standard Navigation block.</p>\n\n\n\n<p>And I think that&#8217;s just one example of the utility of this API. But for example, I mentioned that you could add icons to your Navigation block and you can&#8217;t really do that at the moment. It&#8217;s pretty powerful. It&#8217;s kind of hidden away. It&#8217;s in the release notes, but it&#8217;s not massively clear, but it does open some pretty big doors. And I think if you&#8217;re a developer or a theme author, indeed, you should you should definitely be looking into that and see what it enables for you.</p>\n\n\n\n<p>[00:16:06] <strong>Josepha:</strong> Yeah, we&#8217;ll put a link to Nick&#8217;s post in the show notes, and we&#8217;ll share it around the social spaces. So like, I hear you saying it&#8217;s buried, it&#8217;s hard to see, it won&#8217;t necessarily be exciting now, but will be exciting later, but like mega menus and sliders, those are the most contested things that people want to put on sites all the time. Like from my agency days, like when I was thinking in the mindset of a strategist, a data person, that&#8217;s what I was doing. Like, I never wanted sliders. I never wanted mega menus because it just implied that we didn&#8217;t have a decision about the sites we were making, like we had not decided the primary purpose, and also it was just hard to track, but it was always literally every single time people are like well if Amazon has it why can&#8217;t we have it? You&#8217;re like, yeah, I know, but they&#8217;re Amazon. They&#8217;re not the same like mega menus sliders. I know that from a project perspective that we&#8217;re like, that should be a theme thing. That should be in theme territory. But I think it makes sense to have in core because so many people want to be able to do it.</p>\n\n\n\n<p>[00:17:14] <strong>Josepha:</strong> And just because like someone like me feels like it&#8217;s not the right call for your business doesn&#8217;t mean that you shouldn&#8217;t be able to make that decision for yourself, you know, I think that&#8217;s a, I think that&#8217;s a great, a great feature to call out.</p>\n\n\n\n<p>[00:17:28] <strong>Dave:</strong> Yeah, absolutely. I completely agree. I can look for my agency days. I can exactly imagine that sort of thing. We have a lot of people, a problem that a lot of people are facing. So it&#8217;s really important that we provide the tools to allow people to do that now. And we can always look at if it&#8217;s valid to include it in core later, then we can look at that as well.</p>\n\n\n\n<p>Yeah. So that&#8217;s, that&#8217;s the first one I had. The second one is a little bit more user-facing. I would say it&#8217;s hidden away. But I&#8217;m not 100 percent sure it is. I mean, Josepha, how often do you create links when you&#8217;re working with WordPress?</p>\n\n\n\n<p>[00:17:58] <strong>Josepha:</strong> Like every time that I&#8217;m in WordPress.</p>\n\n\n\n<p>[00:18:00] <strong>Dave:</strong> Yeah, exactly. Same here. I do it all the time, right? And a lot of people do. And for a long while, contributors to the editor have been sort of collecting and collating the feedback that&#8217;s come in from people about their frustrations with the built in link interface in the Block Editor. So if you&#8217;re creating a hyperlink to, you know, hyperlink to another page or, you know, you&#8217;re going to link to Nick&#8217;s mega menu article, you&#8217;re going to be doing that a lot, right?</p>\n\n\n\n<p>That&#8217;s something that people do when they&#8217;re creating content in WordPress. And so we worked a lot to refine that with a contributor who, who you may know, Rich Tabor. Who&#8217;s also, I think, on the release squad as well. An influencer in the WordPress space as well. He spent a lot of time looking at the UX and myself and a number of other contributors have spent a lot of time in this release refining that. And I think it&#8217;s surprisingly difficult to get right, but I think we&#8217;ve, I think we&#8217;ve made some nice improvements to that will be nice quality of life for people who, to do this sort of content creation quite a lot.</p>\n\n\n\n<p>So there&#8217;s things like now when you create the link for the first time, it remains open on the initial creation of the link. So that means you can quickly then easily adjust the link. I mean, it seems obvious, doesn&#8217;t it? Yeah, but it&#8217;s not happening. It just used to just automatically close, and the people are like, &#8220;Hey, I wanted to make more adjustments.&nbsp;&#8220;</p>\n\n\n\n<p>[00:19:08] <strong>Josepha:</strong> I wasn&#8217;t done yet.&nbsp;</p>\n\n\n\n<p>[00:19:10] <strong>Dave:</strong> Exactly. Yeah, exactly. We&#8217;ve, we&#8217;ve streamlined the UI. We&#8217;ve removed a lot of clutter, but we&#8217;ve also added some useful tools, like ability to copy a link and remove the link directly from the control itself. And lastly along with lots of other accessibility changes in this release. We have worked a lot on refining the implementation.</p>\n\n\n\n<p>So that is discoverable for, for users of assistive tech because we spent a lot of time talking to core accessibility team and other people, and they were finding it very hard to perceive that the UI was there because of the way that keyboard interactions work and you&#8217;ve got the block toolbar in the way and things like that.</p>\n\n\n\n<p>We think we&#8217;ve nailed on a really good solution now that works for, not only uses assistive tech, but actually provides benefits for sighted users as well. It&#8217;s kind of difficult to talk about. I mean, I have got a video covering this on my YouTube channel, which kind of shows it in a bit more detail, but we&#8217;re happy it&#8217;s in a much better place.</p>\n\n\n\n<p>[00:20:02] <strong>Dave:</strong> And yeah if people have got feedback about it, and when, when 6.5 comes out, we&#8217;re always happy to hear that. And you can go to the WordPress GitHub repository and raise an issue. And one of us will jump on it and see what we can do.</p>\n\n\n\n<p>[00:20:13] <strong>Josepha:</strong> And we can include a link to that video also. So like, for folks where this sounded intriguing, but they don&#8217;t quite get the concept, like video content all day, let&#8217;s pop it into our show notes. And everybody can take a look at it there. I think that&#8217;s a great idea.</p>\n\n\n\n<p>[00:20:28] <strong>Dave:</strong> Great. Yeah, I appreciate that.</p>\n\n\n\n<p>[00:20:30] <strong>Josepha:</strong> So final question, maybe, maybe final question, final planned question. Is there anything from a user-facing perspective again that you feel has not really gotten the airtime that it needs so far?&nbsp;</p>\n\n\n\n<p>[00:20:44] <strong>Dave:</strong> I think there&#8217;s a lot of technical changes that have happened in this release. So it&#8217;s easy to look at those. I mean, we&#8217;ve covered quite a lot of the key ones that will be user-facing in terms of Font Library and Revisions. We&#8217;ve got things that are going to this release that enable things a lot for people to experience in the future, I think, so underlying changes like the Interactivity API becoming public. Now that&#8217;s public, plugin developers can start to make sites much more interactive on the front of the site rather than just in the editor. So I think that once 6.5 has gone in, and people have started to explore the Interactivity API in more detail, we might see more plugins offering sort of interactivity on the fronts of their sites. An example is obviously the lightbox you&#8217;ve got with images in core, but I can; there&#8217;s way more stuff that you can do with that. So we&#8217;re going to see more of that.&nbsp;</p>\n\n\n\n<p>[00:21:28] <strong>Dave:</strong> We&#8217;ve got Block Hooks that have landed in 6.5, and this is going to open for things like ecommerce plugins and to be able to add, you know, cart blocks or log in, log out blocks to things like navigation, for example, or you might want a ability to like all your comments, and you can do that with Block Hooks and then a plugin developer can just, you know, when the plugin is enabled, they can just make it so that those things just appear on your site, but you still got control over the design.</p>\n\n\n\n<p>So there&#8217;s a lot of like hidden things I think are going to uncover new features for users over time as a result of the community getting involved and changing their plugins and themes to do these take advantage of these new tools.&nbsp;</p>\n\n\n\n<p>[00:22:07] <strong>Josepha:</strong> Yeah, so the Interactivity API, obviously it has &#8220;API&#8221; on it. And so no one&#8217;s thinking, well, this is a user-facing thing. And while the API is not a user facing thing, like, I think that you&#8217;re right. That what it enables absolutely is going to be really useful and hopefully really engaging for like end-to-end users, like the users that are not listening to this podcast and they don&#8217;t know we exist, like they don&#8217;t know that WordPress has a community building it, they&#8217;re just like, it exists, there&#8217;s a software that came out of nowhere, like, I&#8217;m really excited to see how our developers in the community start to use that in their plugins and themes and get that out to end users. I&#8217;m really, really excited to see how creative they get with it.</p>\n\n\n\n<p>Did you have a final thing?</p>\n\n\n\n<p>[00:22:51] <strong>Dave:</strong> There&#8217;s a lot of design changes, I think. I mean, we can&#8217;t cover them all, obviously, in verbal form in this podcast, but some things that are just standing out to me if we look at the source of truth for, for WordPress 6.5, it is, it is big. There&#8217;s a lot in this release. But there&#8217;s some very cool things for, I don&#8217;t know, quality. I like to see them as like quality of life design design changes. Things like, if you drop an image, as a background image of a cover block, it automatically sets the overlay color for that cover block to match the most prominent color of the background image. Like things like that, they seem small, but over time, they just, you just drop that thing, and it just does it. And it&#8217;s like, this is nice. And it feels like a nice tool to use that just is intuitive. And I think there&#8217;s, we&#8217;ll see a lot of those things landing in this release that can just make the experience of working with WordPress and working in the Site Editor much, much nicer.</p>\n\n\n\n<p>[00:23:41] <strong>Josepha:</strong> Yeah. I remember when I first ran into that particular thing, it was on the Showcase, our most recent redesign of it. We&#8217;re using that functionality in there before it was available in core. Obviously, I know, but it was really fascinating. I&#8217;m not great with color combinations. Like, I don&#8217;t have a sense for, like, oh, that&#8217;s the primary thing. That&#8217;s not. And so having that being done kind of automatically so that my stuff looks good anyway, despite what my color sense said to do or not. I thought it was great. Makes you look good as somebody who&#8217;s running a business. You don&#8217;t have to know how things work in order to have excellently functional, really beautiful things.</p>\n\n\n\n<p>[00:24:21] <strong>Josepha:</strong> And I think that&#8217;s a great thing about all of our releases. Obviously, everything is supposed to work that way, but like this one has a lot of really cool things like that available. I think those are really the questions that I had. Is there anything you want to make sure to share before we kind of give last thoughts and head out?</p>\n\n\n\n<p>[00:24:39] <strong>Dave:</strong> Yeah, I was, I was thinking a lot about, you know, the community we&#8217;ve got with WordPress, and I think that people outside of WordPress may not really understand that how amazing this community is that we&#8217;ve got here, but I wanted to say to people like don&#8217;t shy away from contributing to WordPress. I get that, you know, people like myself are fortunate enough to be sponsored to do it. But there&#8217;s always something that people can do, even if that&#8217;s just spending like 30 minutes testing a release or donating some of your time to run one of the meetings. It can really make a difference overall. Even just filing a bug report for something you see in WordPress 6.5 or testing 6.5 before it goes out, those little things do make a big difference. And if you&#8217;re not sure where to go, then we can signpost you with links, no doubt in this, in the podcast description with where where&#8217;s to go. But yeah, I just want to encourage people to get involved, basically.</p>\n\n\n\n<p>[00:25:27] <strong>Josepha:</strong> Yeah. And it&#8217;s all working out in public, like we&#8217;ve got developers, designers, marketing folks, community folks like all doing this work out where everybody can see it. And so that, I know, can look really kind of overwhelming. But I want to just highlight, like, you don&#8217;t have to know everything about what&#8217;s happening in the project in order to get involved in the project. Like every small bit of contribution toward like finding a new bug or confirming that a bug happens across other devices, other setups, things like that, like those all help make things better and keep things moving as quickly as we are able to make them move. And so, yeah, I&#8217;ll second that every little thing that you think like that won&#8217;t make a difference. It does. We can&#8217;t tell that things are broken or things are working or things are in need of some care unless you highlight those for us. And this is the best way to do it is to show up and give 30 minutes to send out a group testing invite to your meetup group or whatever it is that you all have been thinking you should do, like, this is your sign. You can do it.</p>\n\n\n\n<p>[00:26:34] <strong>Dave:</strong> Everyone should get involved if they can.</p>\n\n\n\n<p>[00:26:37] <strong>Josepha:</strong> I agree. I agree. Dave, this has been such an excellent conversation. Thank you so much for joining me today.</p>\n\n\n\n<p>[00:26:42] <strong>Dave:</strong> Oh, thank you very much. It&#8217;s a pleasure.</p>\n\n\n\n<p>[00:26:43] (Music interlude)&nbsp;</p>\n\n\n\n<p>[00:26:49] <strong>Josepha:</strong> What an interesting release we&#8217;ve got coming out this week. I&#8217;m so glad you all made it this far in the pod, and now it&#8217;s time for our small list of big things.</p>\n\n\n\n<p>[00:27:00] <strong>Josepha:</strong> First up, following up on the WordPress meetup reactivation project that we had in 2022, we aim to revive some meetup groups in big cities that are inactive or help the local WordPress community that are not yet part of our meetup chapter program to join our program. There is a post out on the community P2 on the community site. That is titled Asia Meetup Revival Project 2024. I&#8217;ll leave a link to that in the show notes if you want to read more about that and figure out how to get involved.</p>\n\n\n\n<p>And speaking of getting involved, we have roughly a million meetings. Because it&#8217;s a new month, we&#8217;re in April now. New month, new opportunities. There are a lot of things happening in April. We will be coming out of a major release, obviously, and so there will be some minor release follow up to do. There will be a lot of discussion about what&#8217;s coming next, what&#8217;s in trunk, what&#8217;s not in trunk. But also a lot of work being done around our next big major events, our next big major training initiatives. There&#8217;s just so much happening. Spring is a time when we are looking at stuff that&#8217;s new, what we want to invest in, what we want to grow. And so if you have not attended one in a while or even at all if you&#8217;ve never attended a meeting in the community, then this is a great time to start and join your fellow community members trying to make WordPress better every day.</p>\n\n\n\n<p>[00:28:23] <strong>Josepha:</strong> And then the final thing on our small list of big things is I am looking at helping to shift the focus of our WordPress marketing community. We&#8217;ve had a bit of a struggle over the years to figure out what our primary focus and our primary impact can be. So there&#8217;s a post up called &#8216;Making a WordPress Media Corps&#8217;. It&#8217;s gotten quite a bit of attention, and I do really think that it has a lot of potential for solving some of the issues that we have and kind of getting some quick wins into our recent history of that team so that we can move forward confidently together. So pop on over, give it a read, share your thoughts. And if you are one of these qualified media partners, also let us know.&nbsp;</p>\n\n\n\n<p>[00:29:08] <strong>Josepha:</strong> That, my friends, is your small list of big things.</p>\n\n\n\n<p>Don&#8217;t forget to follow us on your favorite podcast app or subscribe directly on WordPress.org/news. You&#8217;ll get a friendly reminder whenever there&#8217;s a new episode. And if you liked what you heard today, share it with a fellow WordPresser, or if you had questions about what you heard, you can share those with me at WPBriefing@WordPress.org. I&#8217;m your host, Josepha Haden Chomphosy. Thank you for tuning in today for the WordPress Briefing, and I&#8217;ll see you again in a couple of weeks.&nbsp;</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 02 Apr 2024 20:18:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Brett McSherry\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:22;a:6:{s:4:\"data\";s:13:\"\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"WordPress.org blog: WordPress 6.5 “Regina”\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=17132\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:42:\"https://wordpress.org/news/2024/04/regina/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:67660:\"<img width=\"1024\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2024/04/Release-Edition-Inline-Image.png?resize=1024%2C683&ssl=1\" alt=\"WordPress 6.5 \" />\n\n\n\n<p>Say hello to WordPress 6.5 “Regina,” inspired by the dynamic versatility of renowned jazz violinist <a href=\"https://en.wikipedia.org/wiki/Regina_Carter\">Regina Carter</a>. An award-winning artist and storied jazz educator known for transcending genre, Regina’s technical foundations in classical music and deep understanding of jazz have earned her the reputation of boldly going beyond what’s possible with the violin.&nbsp;</p>\n\n\n\n<p>Let the stunning twists and subtle turns of <a href=\"https://open.spotify.com/playlist/37i9dQZF1DZ06evO1WEiVo?si=534335c984804713\">Regina’s genre-bending sound</a> surprise you as you explore everything 6.5 offers.</p>\n\n\n\n<p>This latest version of WordPress puts more power into the details. It offers new and improved ways to fine-tune and enhance your site-building experience, letting you take control in ways that make it your own. You’ll find new ways to manage your site’s typography, more comprehensive revisions available in more places, and a collection of Site Editor updates paired with impressive performance gains to help you get things done smoother and faster.</p>\n\n\n\n<p>&#8220;Regina&#8221; also marks the introduction of some breakthrough developer tools that will start transforming how you use and extend blocks to craft engaging experiences. The Interactivity API opens up a world of creative front-end possibilities, while the Block Bindings API makes dynamic connections between blocks and data seamless. These, among other developer-focused improvements and updates, are ready to help you evolve how you build with WordPress.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://wordpress.org/download/\">Download WordPress 6.5 &#8220;Regina&#8221;</a></div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s inside 6.5</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Add and manage fonts across your site</h3>\n\n\n\n<p>The new Font Library puts you in control of an essential piece of your site’s design—typography—without coding or extra steps. Effortlessly install, remove, and activate local and Google Fonts across your site for any Block theme. The ability to include custom typography collections gives site creators and publishers more options when it comes to styling content.</p>\n\n\n\n<img width=\"1024\" height=\"656\" src=\"https://i0.wp.com/wordpress.org/news/files/2024/04/Font-Manager-2.png?resize=1024%2C656&ssl=1\" alt=\"\" class=\"wp-image-17167\" />\n\n\n\n<h3 class=\"wp-block-heading\">Get more from your revisions—including revisions for templates and template parts</h3>\n\n\n\n<p>Work through creative projects with a more comprehensive picture of what’s been done—and what you can fall back on. Get details like time stamps, quick summaries, and a paginated list of all revisions. View revisions from the Style Book to see how changes impact every block. Revisions are also now available for templates and template parts.</p>\n\n\n\n<img width=\"1024\" height=\"656\" src=\"https://i0.wp.com/wordpress.org/news/files/2024/04/Revisions-1.png?resize=1024%2C656&ssl=1\" alt=\"\" class=\"wp-image-17168\" />\n\n\n\n<h3 class=\"wp-block-heading\">Play with enhanced background and shadow tools</h3>\n\n\n\n<ul>\n<li>Control the size, repeat, and focal point options for background images in Group blocks so you can explore subtle or splashy ways to add visual interest to layouts.&nbsp;</li>\n\n\n\n<li>Set aspect ratios for Cover block images and easily add color overlays that automatically source color from your chosen image.&nbsp;</li>\n\n\n\n<li>Add box shadow support to more block types and create layouts with visual depth, or throw a little personality into your design.</li>\n</ul>\n\n\n\n<img width=\"1024\" height=\"656\" src=\"https://i0.wp.com/wordpress.org/news/files/2024/04/design-tools-1.png?resize=1024%2C656&ssl=1\" alt=\"\" class=\"wp-image-17169\" />\n\n\n\n<h3 class=\"wp-block-heading\">Discover new Data Views</h3>\n\n\n\n<p>Every piece of your site comes with a library of information and data—now, you can find what you need quickly and organize it however you like. Data views for pages, templates, patterns, and template parts let you see data in a table or grid view, with the option to toggle fields and make bulk changes.</p>\n\n\n\n<img width=\"1024\" height=\"656\" src=\"https://i0.wp.com/wordpress.org/news/files/2024/04/Data-Views-1.png?resize=1024%2C656&ssl=1\" alt=\"\" class=\"wp-image-17165\" />\n\n\n\n<h3 class=\"wp-block-heading\">Smoother drag-and-drop</h3>\n\n\n\n<p>Feel the difference when you move things around, with helpful visual cues like displaced items in List View or frictionless dragging to anywhere in your workspace—from beginning to end.</p>\n\n\n\n<img width=\"1024\" height=\"656\" src=\"https://i0.wp.com/wordpress.org/news/files/2024/04/drag-and-drop-1.png?resize=1024%2C656&ssl=1\" alt=\"\" class=\"wp-image-17170\" />\n\n\n\n<h3 class=\"wp-block-heading\">Improved link controls</h3>\n\n\n\n<p>Create and manage links easily with a more intuitive link-building experience, like a streamlined UI and a shortcut for copying links.</p>\n\n\n\n<img width=\"1024\" height=\"656\" src=\"https://i0.wp.com/wordpress.org/news/files/2024/04/link-controls-1.png?resize=1024%2C656&ssl=1\" alt=\"\" class=\"wp-image-17171\" />\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s fresh for developers in 6.5</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Bring interactions to blocks with the Interactivity API</h3>\n\n\n\n<p>The <a href=\"https://make.wordpress.org/core/2024/03/04/interactivity-api-dev-note/\">Interactivity API</a> offers developers a standardized method for building interactive front-end experiences with blocks. It simplifies the process, with fewer dependencies on external tooling, while maintaining optimal performance. Use it to create memorable user experiences, like fetching search results instantly or letting visitors interact with content in real time.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Connect blocks to custom fields or other dynamic content</h3>\n\n\n\n<p>Link core block attributes to custom fields and use the value of custom fields without creating custom blocks. Powered by the <a href=\"https://make.wordpress.org/core/2024/03/06/new-feature-the-block-bindings-api/\">Block Bindings API</a>, developers can extend this capability further to connect blocks to any dynamic content—even beyond custom fields. If there’s data stored elsewhere, easily point blocks to that new source with only a few lines of code.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Add appearance tools to Classic themes</h3>\n\n\n\n<p>Give designers and creators using Classic themes access to an upgraded design experience. Opt in to support for spacing, border, typography, and color options, even without using theme.json. Once support is enabled, more tools will be automatically added as they become available.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Explore improvements to the plugin experience</h3>\n\n\n\n<p>There&#8217;s now an <a href=\"https://make.wordpress.org/core/2024/03/05/introducing-plugin-dependencies-in-wordpress-6-5/\">easier way to manage plugin dependencies</a>. Plugin authors can supply a new <code>Requires Plugins</code> header with a comma-separated list of required plugin slugs, presenting users with links to install and activate those plugins first.</p>\n\n\n\n<h2 class=\"wp-block-heading\">From fast to faster: Performance updates</h2>\n\n\n\n<p>This release includes 110+ performance updates, resulting in an impressive increase in speed and efficiency across the Post Editor and Site Editor. Loading is over two times faster than in 6.4, with input processing speed up to five times faster than the previous release.</p>\n\n\n\n<p>&nbsp;Translated sites see up to 25% improvement in load time for this release courtesy of <a href=\"https://make.wordpress.org/core/2024/02/27/i18n-improvements-6-5-performant-translations/\">Performant Translations</a>. Additional performance highlights include <a href=\"https://make.wordpress.org/core/2024/02/23/wordpress-6-5-adds-avif-support/\">AVIF image support</a> and improvements for <a href=\"https://make.wordpress.org/core/2024/02/29/performance-improvements-for-registering-block-variations-with-callbacks/\">registering block variations with callbacks</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A tradition of inclusion</h2>\n\n\n\n<p>This release includes more than 65 accessibility improvements across the platform, making it more accessible than ever. It contains an important fix that unblocks access to the admin submenus for screen reader users and others who navigate by keyboard. This release also adds fixes to color contrast in admin focus states, positioning of elements, and cursor focus, among many others, that help improve the WordPress experience for everyone.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Learn more about WordPress 6.5</h2>\n\n\n\n<p>Check out the new&nbsp;<a href=\"https://wordpress.org/download/releases/6-5/\">WordPress 6.5 page</a>&nbsp;to learn more about the numerous enhancements and features of this release—including short demos of some of the highlighted features. </p>\n\n\n\n<p>Explore <a href=\"https://learn.wordpress.org/\">Learn WordPress</a> for quick how-to videos, <a href=\"https://learn.wordpress.org/social-learning/\">online workshops</a>, and other free resources to level up your WordPress knowledge and skills.</p>\n\n\n\n<p>Check out the <a href=\"https://make.wordpress.org/core/2024/03/15/wordpress-6-5-field-guide/\">WordPress 6.5 Field Guide</a> for detailed technical information and <a href=\"https://make.wordpress.org/core/tag/dev-notes-6-5/\">developer notes</a> to help you build with WordPress and get the most out of this release. Don’t forget to subscribe to the <a href=\"https://developer.wordpress.org/news/\">Developer Blog</a> for developer updates, feature tutorials, and other helpful WordPress content from a developer perspective.</p>\n\n\n\n<p>For more information about installation, file changes, fixes, and other updates, read the <a href=\"https://wordpress.org/documentation/wordpress-version/version-6-5/\">6.5 release notes</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">The 6.5 release squad</h2>\n\n\n\n<p>Every release has many moving parts with its own triumphs and challenges. It takes a dedicated team of enthusiastic contributors to help keep things on track and moving smoothly. 6.5 is made possible by a cross-functional group of contributors, always ready to champion ideas, remove blockers, and resolve issues.</p>\n\n\n\n<ul>\n<li>Release Lead: <a href=\"https://profiles.wordpress.org/matt/\">Matt Mullenweg</a></li>\n\n\n\n<li>Release Coordinators: <a href=\"https://profiles.wordpress.org/akshayar/\">Akshaya Rane</a>, <a href=\"https://profiles.wordpress.org/priethor/\">Héctor Prieto</a>, <a href=\"https://profiles.wordpress.org/marybaum/\">Mary Baum</a></li>\n\n\n\n<li>Core Tech Leads: <a href=\"https://profiles.wordpress.org/davidbaumwald/\">David Baumwald</a>, <a href=\"https://profiles.wordpress.org/swissspidy/\">Pascal Birchler</a></li>\n\n\n\n<li>Editor Tech Leads: <a href=\"https://profiles.wordpress.org/get_dave/\">David Smith</a>, <a href=\"https://profiles.wordpress.org/youknowriad/\">Riad Benguella</a></li>\n\n\n\n<li>Core Triage Leads: <a href=\"https://profiles.wordpress.org/chaion07/\">Ahmed Kabir Chaion</a>, <a href=\"https://profiles.wordpress.org/audrasjb/\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/rajinsharwar/\">Rajin Sharwar</a></li>\n\n\n\n<li>Editor Triage Leads: <a href=\"https://profiles.wordpress.org/annezazu/\">Anne McCarthy</a>, <a href=\"https://profiles.wordpress.org/fabiankaegy/\">Fabian Kägy</a></li>\n\n\n\n<li>Design Leads: <a href=\"https://profiles.wordpress.org/benjamin_zekavica/\">Benjamin Zekavica</a>, <a href=\"https://profiles.wordpress.org/richtabor/\">Rich Tabor</a></li>\n\n\n\n<li>Marketing and Communication Leads: <a href=\"https://profiles.wordpress.org/dansoschin/\">Dan Soschin</a>, <a href=\"https://profiles.wordpress.org/laurlittle/\">Lauren Stein</a></li>\n\n\n\n<li>Documentation Leads: <a href=\"https://profiles.wordpress.org/estelaris/\">Estela Rueda</a>, <a href=\"https://profiles.wordpress.org/leonnugraha/\">Leonardus Nugraha</a>, <a href=\"https://profiles.wordpress.org/stevenlinx/\">Steven Lin</a></li>\n\n\n\n<li>Performance Leads: <a href=\"https://profiles.wordpress.org/joemcgill/\">Joe McGill</a>, <a href=\"https://profiles.wordpress.org/mukesh27/\">Mukesh Panchal</a></li>\n\n\n\n<li>Test Leads: <a href=\"https://profiles.wordpress.org/oglekler/\">Olga Gleckler</a>, <a href=\"https://profiles.wordpress.org/lumiblog/\">Patrick Lumumba</a>, <a href=\"https://profiles.wordpress.org/vipuljnext/\">Vipul Ghori</a></li>\n\n\n\n<li>Default Themes Leads: <a href=\"https://profiles.wordpress.org/poena/\">Carolina Nymark</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you, contributors</h2>\n\n\n\n<p>WordPress believes in democratizing publishing and the <a href=\"https://opensource.org/osd-annotated\">freedoms that come with open source</a>. Supporting this idea is a global and diverse community of people collaborating to strengthen the software.&nbsp;</p>\n\n\n\n<p>WordPress 6.5 reflects the countless efforts and passion of around 700 contributors in at least 57 countries. This release also welcomed over 150 first-time contributors!</p>\n\n\n\n<p>Their collaboration delivered more than 2,500 enhancements and fixes, ensuring a stable release for all—a testament to the power and capability of the WordPress open source community.</p>\n\n\n<p class=\"is-style-wporg-props-long alignfull\"><a href=\"https://profiles.wordpress.org/benniledl/\">!Benni</a> · <a href=\"https://profiles.wordpress.org/_ck_/\">_ck_</a> · <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> · <a href=\"https://profiles.wordpress.org/aaronrobertshaw/\">Aaron Robertshaw</a> · <a href=\"https://profiles.wordpress.org/abmamun007/\">Abdullah Mamun</a> · <a href=\"https://profiles.wordpress.org/webcommsat/\">Abha Thakor</a> · <a href=\"https://profiles.wordpress.org/fitehal/\">Abhishek Deshpande</a> · <a href=\"https://profiles.wordpress.org/abletec/\">abletec</a> · <a href=\"https://profiles.wordpress.org/acosmin/\">acosmin</a> · <a href=\"https://profiles.wordpress.org/adampickering/\">Adam Pickering</a> · <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a> · <a href=\"https://profiles.wordpress.org/adarshposimyth/\">Adarsh Akshat</a> · <a href=\"https://profiles.wordpress.org/ajmcfadyen/\">admcfajn</a> · <a href=\"https://profiles.wordpress.org/chaion07/\">Ahmed Chaion</a> · <a href=\"https://profiles.wordpress.org/engahmeds3ed/\">Ahmed Saeed</a> · <a href=\"https://profiles.wordpress.org/ajithrn/\">Ajith R N</a> · <a href=\"https://profiles.wordpress.org/skyakash12/\">Akash Muchandikar</a> · <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a> · <a href=\"https://profiles.wordpress.org/atachibana/\">Akira Tachibana</a> · <a href=\"https://profiles.wordpress.org/akmelias/\">akmelias</a> · <a href=\"https://profiles.wordpress.org/wpfy/\">Akramul Hasan</a> · <a href=\"https://profiles.wordpress.org/akshayar/\">Akshaya Rane</a> · <a href=\"https://profiles.wordpress.org/schlessera/\">Alain Schlesser</a> · <a href=\"https://profiles.wordpress.org/alanfuller/\">Alan Fuller</a> · <a href=\"https://profiles.wordpress.org/ahoereth/\">Alex</a> · <a href=\"https://profiles.wordpress.org/xknown/\">Alex Concha</a> · <a href=\"https://profiles.wordpress.org/alexkingorg/\">Alex King</a> · <a href=\"https://profiles.wordpress.org/akirk/\">Alex Kirk</a> · <a href=\"https://profiles.wordpress.org/ajlende/\">Alex Lende</a> · <a href=\"https://profiles.wordpress.org/viper007bond/\">Alex Mills</a> · <a href=\"https://profiles.wordpress.org/alexstine/\">Alex Stine</a> · <a href=\"https://profiles.wordpress.org/alexandrebuffet/\">Alexandre Buffet</a> · <a href=\"https://profiles.wordpress.org/alexanderkoledov/\">AlexKole</a> · <a href=\"https://profiles.wordpress.org/alh0319/\">Amber Hinds</a> · <a href=\"https://profiles.wordpress.org/sabreuse/\">Amy Hendrix (sabreuse)</a> · <a href=\"https://profiles.wordpress.org/amykamala/\">Amy Kamala</a> · <a href=\"https://profiles.wordpress.org/anandau14/\">Anand Upadhyay</a> · <a href=\"https://profiles.wordpress.org/anlino/\">Anders Nor&#233;n</a> · <a href=\"https://profiles.wordpress.org/afercia/\">Andrea Fercia</a> · <a href=\"https://profiles.wordpress.org/andraganescu/\">Andrei Draganescu</a> · <a href=\"https://profiles.wordpress.org/euthelup/\">Andrei Lupu</a> · <a href=\"https://profiles.wordpress.org/andrewhayward/\">Andrew Hayward</a> · <a href=\"https://profiles.wordpress.org/l1nuxjedi/\">Andrew Hutchings</a> · <a href=\"https://profiles.wordpress.org/nacin/\">Andrew Nacin</a> · <a href=\"https://profiles.wordpress.org/norcross/\">Andrew Norcross</a> · <a href=\"https://profiles.wordpress.org/azaozz/\">Andrew Ozz</a> · <a href=\"https://profiles.wordpress.org/andrewserong/\">Andrew Serong</a> · <a href=\"https://profiles.wordpress.org/andrewleap/\">andrewleap</a> · <a href=\"https://profiles.wordpress.org/andbalashov/\">Andrii Balashov</a> · <a href=\"https://profiles.wordpress.org/oandregal/\">André Maneiro</a> · <a href=\"https://profiles.wordpress.org/afragen/\">Andy Fragen</a> · <a href=\"https://profiles.wordpress.org/apeatling/\">Andy Peatling</a> · <a href=\"https://profiles.wordpress.org/aneeshd16/\">Aneesh Devasthale</a> · <a href=\"https://profiles.wordpress.org/ankit-k-gupta/\">Ankit K Gupta</a> · <a href=\"https://profiles.wordpress.org/ankitmaru/\">Ankit Panchal</a> · <a href=\"https://profiles.wordpress.org/annezazu/\">Anne McCarthy</a> · <a href=\"https://profiles.wordpress.org/antpb/\">Anthony Burchell</a> · <a href=\"https://profiles.wordpress.org/ant1busted/\">Antoine</a> · <a href=\"https://profiles.wordpress.org/antonlukin/\">Anton Lukin</a> · <a href=\"https://profiles.wordpress.org/atimmer/\">Anton Timmermans</a> · <a href=\"https://profiles.wordpress.org/antonvlasenko/\">Anton Vlasenko</a> · <a href=\"https://profiles.wordpress.org/lighthouse79/\">Antonella</a> · <a href=\"https://profiles.wordpress.org/colomet/\">Antonio D.</a> · <a href=\"https://profiles.wordpress.org/antonisme/\">Antonis Lilis</a> · <a href=\"https://profiles.wordpress.org/arena94/\">arena94</a> · <a href=\"https://profiles.wordpress.org/aristath/\">Ari Stathopoulos</a> · <a href=\"h