\":\"em\",\"size\":1.5600000000000001,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"em\",\"size\":\"\",\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"58\",\"left\":\"0\",\"isLinked\":false},\"__globals__\":{\"typography_typography\":\"\",\"text_color\":\"\"},\"pa_condition_repeater\":[],\"_animation\":\"zoomIn\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"1da6a652\",\"elType\":\"widget\",\"settings\":{\"title\":\"2023 - 2024\",\"header_size\":\"h4\",\"title_color\":\"#BCBCBCAB\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Inter\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"typography_font_weight\":\"500\",\"typography_line_height\":{\"unit\":\"em\",\"size\":1.2,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"em\",\"size\":\"\",\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"8\",\"left\":\"0\",\"isLinked\":false},\"__globals__\":{\"title_color\":\"\",\"typography_typography\":\"\"},\"pa_condition_repeater\":[],\"_animation\":\"zoomIn\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"273cde10\",\"elType\":\"widget\",\"settings\":{\"title\":\"Search Engine Optimization\",\"title_color\":\"#5B78F6\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Inter\",\"typography_font_size\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"typography_font_weight\":\"500\",\"typography_line_height\":{\"unit\":\"em\",\"size\":1.2,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"em\",\"size\":\"\",\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"8\",\"left\":\"0\",\"isLinked\":false},\"__globals__\":{\"typography_typography\":\"\"},\"pa_condition_repeater\":[],\"_animation\":\"zoomIn\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"26df857d\",\"elType\":\"widget\",\"settings\":{\"title\":\"Dowell Research Singapore\",\"header_size\":\"h4\",\"title_color\":\"#BCBCBC