INSERT INTO `wp_posts` VALUES (16,1,'2024-02-29 17:05:18','2024-02-29 17:05:18','<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>BRANDING - RAVEN STUDIO</h2>		\n			<h2><img src=\"https://kitpapa.net/gridly/wp-content/uploads/2023/04/star-2.png\" alt=\"Star\">\n AESTHETIC DESIGN FOR BRAND  <br>NEW STARTUP \n<img src=\"https://kitpapa.net/gridly/wp-content/uploads/2023/04/star-2.png\" alt=\"Star\"></h2>		\n			<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image img{vertical-align:middle;display:inline-block}</style>										<img width=\"1920\" height=\"551\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1.jpeg\" alt=\"\" srcset=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1.jpeg 1920w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-300x86.jpeg 300w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-1024x294.jpeg 1024w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-768x220.jpeg 768w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-1536x441.jpeg 1536w\" sizes=\"(max-width: 1920px) 100vw, 1920px\" />													\n			<h2>RAVEN STUDIO</h2>		\n		<p>Sit amet luctussd fav venenatis, lectus magna fringilla inis urna, porttitor rhoncus dolor purus non enim praesent in elementum sahas facilisis leo, vel fringilla est ullamcorper eget nulla facilisi etisam dignissim diam quis enim lobortis viverra orci sagittis eu volutpat odio facilisis mauris sit.</p><p>Scelerisque fermentum duisi faucibus in ornare quam sisd sit amet luctussd fav venenatis, lectus magna fringilla zac urna, porttitor rhoncus dolor purus non enim praesent cuz elementum sahas facilisis leot.</p>		\n			<h2>ABOUT</h2>		\n		<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit ut aliquam, purus sit amet luctus venenatis, lectus magna ve fringilla urna, porttitor rhoncus dolor purus nonds enim isi praesent elementum facilisis leo.</p><p>Vel fringilla est ullamcorper eget nulla facilisi etiama ashfa dignissim diam quis enim lobortis scelerisque fermentum dui faucibus in ornare quam viverra orci sagittis eu agv he volutpat odio asas facilisis mauris sit.</p>		\n													<img width=\"37\" height=\"76\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/icon2.png\" alt=\"\" />													\n													<img width=\"1920\" height=\"551\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1.jpeg\" alt=\"\" srcset=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1.jpeg 1920w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-300x86.jpeg 300w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-1024x294.jpeg 1024w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-768x220.jpeg 768w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project-dt-1-1536x441.jpeg 1536w\" sizes=\"(max-width: 1920px) 100vw, 1920px\" />													\n													<img width=\"568\" height=\"488\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/project3.jpeg\" alt=\"\" srcset=\"h