INSERT INTO `wp_posts` VALUES (26,1,'2024-02-29 17:05:29','2024-02-29 17:05:29','<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image img{vertical-align:middle;display:inline-block}</style>										<img width=\"457\" height=\"546\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/AFAQ-WAHEED-WordPress-Developer.jpg\" alt=\"Afaq Waheed WordPress Developer\" srcset=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/AFAQ-WAHEED-WordPress-Developer.jpg 457w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/AFAQ-WAHEED-WordPress-Developer-251x300.jpg 251w\" sizes=\"(max-width: 457px) 100vw, 457px\" />													\n			<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>AFAQ WAHEED</h2>		\n			<h4>afaqwaheed10@gmail.com</h4>		\n			<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-widget-social-icons.elementor-grid-0 .elementor-widget-container,.elementor-widget-social-icons.elementor-grid-mobile-0 .elementor-widget-container,.elementor-widget-social-icons.elementor-grid-tablet-0 .elementor-widget-container{line-height:1;font-size:0}.elementor-widget-social-icons:not(.elementor-grid-0):not(.elementor-grid-tablet-0):not(.elementor-grid-mobile-0) 