INSERT INTO `wp_posts` VALUES (75,1,'2024-02-29 17:05:53','2024-02-29 17:05:53','<img width=\"646\" height=\"629\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/me2.png\" alt=\"\" srcset=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/me2.png 646w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/me2-300x292.png 300w\" sizes=\"(max-width: 646px) 100vw, 646px\" />													\n													<img width=\"48\" height=\"48\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/star-2.png\" alt=\"\" />													\n			<h2>SELF-SUMMARY</h2>		\n													<img width=\"48\" height=\"48\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/star-2.png\" alt=\"\" />													\n													<img width=\"37\" height=\"76\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/icon2.png\" alt=\"\" />													\n			<h2>David Henderson</h2>		\n		<p>I am a San francisco-based product designer with a focus on web design, illustration, a visual development. I have a diverse range of experience having worked across various fields and industries.</p>		\n			<h2>EXPERIENCE</h2>		\n			<h2>2007 - 2017</h2>		\n			<h2>Framer Designer & Developer</h2>		\n			<h4>Bluebase Designs</h4>		\n			<h2>2017 - 2023</h2>		\n			<h2>Front-End Developer</h2>		\n			<h4>Larsen & Toubro</h4>		\n			<h2>EDUCATION</h2>		\n			<h2>2004 - 2007</h2>		\n			<h2>Bachelor Degree in Psychology</h2>		\n			<h4>University of California</h4>		\n			<h2>2007 - 2009</h2>		\n			<h2>Master Degree in Designing</h2>		\n			<h4>University of Texas</h4>		\n					<a target=\"_blank\" rel=\"noopener\">\n						Icon-dribbble\n											</a>\n					<a target=\"_blank\" rel=\"noopener\">\n						Icon-twitter-1\n											</a>\n			<h4>STAY WITH ME</h4>		\n			<h2>Profiles</h2>		\n			<a href=\"/contact/\">\n			<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"46\" height=\"42\" viewBox=\"0 0 46 42\" fill=\"none\"><path d=\"M30.9224 21.2014C25.