INSERT INTO `wp_posts` VALUES (129,1,'2024-02-29 17:59:20','2024-02-29 17:59:20','<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image img{vertical-align:middle;display:inline-block}</style>										<img width=\"457\" height=\"546\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/AFAQ-WAHEED-WordPress-Developer.jpg\" alt=\"Afaq Waheed WordPress Developer\" srcset=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/AFAQ-WAHEED-WordPress-Developer.jpg 457w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/AFAQ-WAHEED-WordPress-Developer-251x300.jpg 251w\" sizes=\"(max-width: 457px) 100vw, 457px\" />													\n			<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h4>WordPress Developer</h4>		\n			<h1>AFAQ WAHEED.</h1>		\n		<p>I am a WordPress Developer based in Pakistan.</p>		\n			<a href=\"http://afaq-waheed-portfolio.local/about/\">\n			<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"46\" height=\"42\" viewBox=\"0 0 46 42\" fill=\"none\"><path d=\"M30.9224 21.2014C25.1291 21.2014 24.618 24.7796 24.618 27.3354C24.618 21.5421 21.5509 21.2014 17.9727 21.2014C24.618 21.2014 24.618 17.2824 24.618 14.8969C24.618 20.3494 27.8554 21.2014 30.9224 21.20