INSERT INTO `wp_posts` VALUES (366,1,'2024-04-14 06:03:31','2024-04-14 06:03:31','<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>DIVI BUILDER</h2>		\n			<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image img{vertical-align:middle;display:inline-block}</style>										<img width=\"1886\" height=\"838\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/04/Divi-Theme-Works.png\" alt=\"\" srcset=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/04/Divi-Theme-Works.png 1886w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/04/Divi-Theme-Works-300x133.png 300w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/04/Divi-Theme-Works-1024x455.png 1024w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/04/Divi-Theme-Works-768x341.png 768w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/04/Divi-Theme-Works-1536x682.png 1536w\" sizes=\"(max-width: 1886px) 100vw, 1886px\" />													\n													<img width=\"37\" height=\"97\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/icon3.png\" alt=\"\" />													\n			<h2>Year</h2>		\n			<h2>2024</h2>		\n			<h2>Client</h2>		\n			<h2>N/A</h2>		\n			<h2>Service