INSERT INTO `wp_posts` VALUES (373,1,'2024-04-14 06:06:33','2024-04-14 06:06:33','<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>Dowell store </h2>		\n			<style>/*! elementor - v3.19.0 - 28-02-2024 */\n.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image img{vertical-align:middle;display:inline-block}</style>										<img width=\"1884\" height=\"790\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/Dowell-Store.png\" alt=\"Dowell Store\" srcset=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/Dowell-Store.png 1884w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/Dowell-Store-300x126.png 300w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/Dowell-Store-1024x429.png 1024w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/Dowell-Store-768x322.png 768w, http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/Dowell-Store-1536x644.png 1536w\" sizes=\"(max-width: 1884px) 100vw, 1884px\" />													\n													<img width=\"37\" height=\"97\" src=\"http://afaq-waheed-portfolio.local/wp-content/uploads/2024/02/icon3.png\" alt=\"\" />													\n			<h2>Year</h2>		\n			<h2>2023</h2>		\n			<h2>Client</h2>		\n			<h2>Dowell Ux Living Lab</h2>		\n			<h2>Services</h2>		\n			<h2>WordPress</h2>		\n			<h2>Project</h2>		\n			<h2>Dynamic</h2>		\n			<h2>Description</h2>		\n		<p>Dowellstore\'s comprehensive documentation website, featuring APIs, libraries, WordPress plugins, and React packages. Explore easy-to-understand guides and resources for seamless integration and enhanced functionality.</p>		\n			<h2>Website Development Tools and Techniques</h2>		\n		<ul><li>Utilizes Elementor Pro for page building</li><li>Incorporates WPGetAPI for API testing</li><li>Implements W3 Total Cache for speed optimization</li><li>Ensures user-friendliness with Yoast and Rank Math plugins</li><li>Offers detailed documentation for easy reference</li><li>Optimizes keyword placement and images</li><li>Utilizes the Kadence theme for an elegant design</li><li>Includes a contact form for seamless communication</li></ul>		\n			<a href=\"https://dowellstore.org/\" target=\"_blank\" rel=\"noopener\">\n						Visit Website\n					</a>\n			<style>\n@media only screen and (max-width: 1023px){\n    .text-image br{\n        display: none;\n    }\n}\n@media only screen and (max-width: 767px){\n    .text-image img{\n        width: 25px;\n}\n}\n</style>','E-Commerce','','inherit','closed','closed','','353-revision-v1','','','2024-04-14 06:06:33','2024-04-14 06:06:33','',353,'http://afaq-waheed-portfolio.local/?p=373',0,'revision','',0);
